update content_bodies set title = 'Wide Area Tourism Video of Matsuyama, Toon, and Tobe', description = 'Matsuyama City, Toon City, and Tobe Town are filled with spots to enjoy rich nature and traditional culture. This video presents these attractions in an engaging way.' where id = 'tNc2-ZuYkM_z9Fj_1pFJT';
update content_bodies set title = '四国松山[松山市公式観光WEBサイト]', description = '松山市は穏やかで美しい瀬戸内海に面し、温暖で雨の少ない気候が特徴の地域です。西側には海、東側には山があり、都会の快適さと田舎ののどかさを兼ね備えています。道後温泉などの温泉や、近代俳句の礎を築いた正岡子規の存在から、「いで湯と城と文学のまち」として文化的魅力が豊富です。市の中心には、江戸時代から残る貴重な天守を有する松山城があり、その周辺には城下町の文化が息づいています。また、四国遍路の旅人を温かく迎える「おもてなし」の精神も根付いています。' where id = '5UCIpIvPc6zhIFhuM-3x4';
update content_bodies set title = 'Matsuyama, Shikoku [Official Tourism Website of Matsuyama City]', description = 'Matsuyama City, located on the serene and beautiful Seto Inland Sea, enjoys a mild climate with little rainfall throughout the year. The city combines the convenience of urban life with the tranquility of rural areas, with the sea to the west and mountains to the east. Known for its rich cultural heritage, Matsuyama is home to Dogo Onsen, one of Japan''s oldest hot springs, and the legacy of Masaoka Shiki, a pioneer of modern haiku. The city is often referred to as ''the town of hot springs, castles, and literature.'' At its center stands Matsuyama Castle, which features a rare Edo-period keep, surrounded by a town that preserves the culture of the castle town. The city has a long history of welcoming pilgrims from the Shikoku Pilgrimage, embodying a spirit of warm hospitality.' where id = 'IQaLPwgzgH5v52--HBFJt';
update content_bodies set title = '弘前ねぷた300年祭～弘前ねぷたをもっと知ろう！～', description = '弘前ねぷたは1722年に初めて文献に登場し、2022年に300年を迎えました。弘前ねぷた300年祭実行委員会は、弘前ねぷたの歴史と伝統を継承し、未来へ繋げるために、記念動画「歴史編」と「資料編」の2本を制作しました。詳細は提供されたリンクをご覧ください。' where id = 'd5JijBeBYAexrrClxTInY';
update content_bodies set title = 'Hirosaki Neputa 300th Festival - Let''s Learn More About Hirosaki Neputa!', description = 'The Hirosaki Neputa first appeared in documents in 1722, marking its 300th anniversary in 2022. The Hirosaki Neputa 300th Festival Executive Committee has produced two commemorative videos, ''History Edition'' and ''Materials Edition,'' to preserve the history and traditions of Hirosaki Neputa and connect them to the future. For more information, visit the provided link.' where id = 'dZ9PCCqFpfq5n4rJbWvY7';
update content_bodies set title = '弘前ねぷた300年祭～弘前ねぷたをもっと知ろう！～【歴史編】', description = '弘前ねぷたは1722年に初めて文献に登場し、2022年に300年を迎えました。弘前ねぷた300年祭実行委員会は、弘前ねぷたの歴史と伝統を継承し、未来へ繋げるために、記念動画【歴史編】【資料編】の2本を制作しました。歴史編は以下のリンクからご覧いただけます。https://youtu.be/375QrjNIFS4。詳細については弘前市観光部観光課（TEL：0172-40-0236）またはhttps://www.hirosaki-kanko.or.jp/edit.html?id=neputa300をご覧ください。' where id = 's78nn31Eope0aLgaw51vB';
update content_bodies set title = 'Hirosaki Neputa 300th Festival - Learn More About Hirosaki Neputa! - [History Edition]', description = 'The Hirosaki Neputa first appeared in documents in 1722 (the 7th year of the Kyoho era) and celebrated its 300th anniversary in 2022. The Hirosaki Neputa 300th Festival Executive Committee has produced two commemorative videos, [History Edition] and [Materials Edition], to preserve the history and traditions of Hirosaki Neputa and connect them to the future. You can watch the [History Edition] here: https://youtu.be/375QrjNIFS4. For more information, contact the Hirosaki City Tourism Department at TEL: 0172-40-0236 or visit https://www.hirosaki-kanko.or.jp/edit.html?id=neputa300.' where id = 'hHKDDdhomWp6gAyXMj8RL';
update content_bodies set title = '岩木スカイライン～紅葉～', description = '岩木スカイラインは、特に秋の季節に美しい紅葉を楽しむことができる絶景ドライブコースです。このルートは観光客や地元の人々に人気があり、自然の美しさを体験する機会を提供しています。詳細については、公式ウェブサイトをご覧ください。' where id = 'qtRVdC8WsTN12o7QR9V1h';
update content_bodies set title = 'Iwaki Skyline - Autumn Foliage', description = 'Iwaki Skyline is a scenic drive that offers stunning views, especially during the autumn season when the foliage transforms into vibrant colors. The route is popular among tourists and locals alike, providing an opportunity to experience the beauty of nature. For more information, visit the official website.' where id = 'hoQ0JupdvsSJczSih9H_V';
update content_bodies set title = 'サイクルネットHIROSAKI～クロスバイク紹介動画～', description = 'サイクルネットHIROSAKIでは、観光用の貸自転車としてクロスバイクを提供しています。岩木山を望むアップルロードを走り、りんご畑のすぐ横を通る爽快なライディングを楽しむことができます。最高のサイクルトラベル体験を提供します。営業時間は9:00から17:00までで、事前予約が必要です。料金は1回3,000円（税込）で、弘前市立観光館で貸出を行っています。' where id = 'YtLCWbdVO17DHSqK5E1Ww';
update content_bodies set title = 'Cycle Net HIROSAKI - Cross Bike Introduction Video', description = 'Cycle Net HIROSAKI offers rental bicycles for sightseeing, featuring cross bikes. Enjoy a refreshing ride along the Apple Road with views of Mount Iwaki and right next to apple orchards. We provide the best cycling travel experience. Operating hours are from 9:00 AM to 5:00 PM, and reservations are required in advance. The rental fee is 3,000 yen (tax included) per bike. Bicycles can be rented at the Hirosaki City Tourist Information Center.' where id = 'H39cBbeH8imFeFp3JJGrf';
update content_bodies set title = '弘前公園中濠城船', description = '弘前公園中濠城船は青森県弘前市に位置しています。この船は弘前さくらまつりに関連しており、詳細は提供されたリンクで確認できます。' where id = 'vXgN4MpgGL8KAKlbQw85w';
update content_bodies set title = 'Hirosaki Park Nakaguro Castle Boat', description = 'Located in Hirosaki City, Aomori Prefecture, the Hirosaki Park Nakaguro Castle Boat is associated with the Hirosaki Cherry Blossom Festival. More information can be found at the provided link.' where id = 'ULWJuHQN2d-sC_-PXn-kk';
update content_bodies set title = '花筏タイムラプス', description = '青森県弘前市にある弘前公園の花筏タイムラプス映像です。この映像は、春に多くの訪問者を惹きつける弘前さくらまつりの魅力を捉えています。美しい桜の風景が映し出され、弘前公園の自然の美しさを感じることができます。' where id = 'HZ2rGdBUpir-kggT_kRqb';
update content_bodies set title = 'Hanai-kata Time-lapse', description = 'This time-lapse video showcases the beauty of Hanai-kata in Hirosaki Park, located in Hirosaki City, Aomori Prefecture. The video captures the essence of the Hirosaki Cherry Blossom Festival, a significant event that attracts many visitors each spring.' where id = 'W-nmz4PIeptLlKwMogyA4';
update content_bodies set title = '日本最古のソメイヨシノ タイムラプス', description = '青森県弘前市にある弘前公園の日本最古のソメイヨシノを紹介するタイムラプス映像です。この映像は、弘前さくらまつりの期間中に、歴史ある桜の美しさを捉えています。' where id = 'flJQ9BHKawP8-xQCrYXA-';
update content_bodies set title = 'Japan''s Oldest Somei Yoshino Time-lapse', description = 'This time-lapse video showcases the oldest Somei Yoshino cherry trees located in Hirosaki Park, Aomori Prefecture. The video captures the beauty of these historic trees during the Hirosaki Cherry Blossom Festival.' where id = 'c9NfbVBrNTe8ctW0BuC1K';
update content_bodies set title = 'Travel Salad 中国語繁体字版', description = '青森県弘前市のPR動画で、弘前公園や津軽藩ねぷた村、藤田記念庭園洋館などのスポットを取材した内容です。' where id = 'w3K9tkajd9Y9ulSHNXBwA';
update content_bodies set title = 'Travel Salad Traditional Chinese Version', description = 'This is a promotional video for Hirosaki City in Aomori Prefecture, featuring locations such as Hirosaki Park, Tsugaru Han Neputa Village, and the Fujita Memorial Garden Western-style building.' where id = '1FsRVLVGYH6HkfzWUSwXE';
update content_bodies set title = '【ヨロン島】お母さんを連れて行きたい！ヨロン島のオフシーズンの癒し5選', description = '「ヨロンブルー」と称される美しい海に囲まれたヨロン島は、冬でも温暖な気候が魅力です。この島では、豊かな自然環境と温かい島人との出会いを通じて、忘れられない思い出を作ることができます。寒い都会を離れ、ゆったりとした島時間を楽しみながら、優しい出会いを体験してみてください。' where id = 'cdj5dLXOcdvxQxgF05l2k';
update content_bodies set title = 'Yoron Island: 5 Healing Experiences to Enjoy with Your Mother in the Off-Season', description = 'Yoron Island, surrounded by the beautiful sea known as ''Yoron Blue,'' offers a warm climate even in winter. This island is not only rich in natural beauty but also provides unforgettable memories through encounters with its friendly locals. Escape the cold city and enjoy the relaxed island time while cherishing gentle interactions.' where id = 'v9XXkD5Mm8gy89W3bW0OM';
update content_bodies set title = '【ヨロン島】守ってほしい！陸のマナー', description = '南国の楽園、ヨロン島のマナーを紹介する動画です。ヨロン島を訪れることは、ヨロンファミリーの一員になることを意味します。美しい海や海の生き物、島の人々はすべて家族のような存在です。優しい気持ちで旅を楽しんでください。出演は与論島劇団 野性の島人、制作は81plus株式会社です。' where id = 'T8tW4NZ8N3I_9lxbH6g6F';
update content_bodies set title = 'Yoron Island Etiquette - Land Edition', description = 'This video presents the etiquette of Yoron Island, a tropical paradise. Traveling to Yoron Island means becoming part of the Yoron family. The beautiful sea, marine life, and the island''s people are all like family. Visitors are encouraged to travel with a kind heart.' where id = 'jut8v9pS4LX3GpIhT5s9X';
update content_bodies set title = 'un, paru, aikyun', description = '映画「un, paru, aikyun」は、監督の伊藤広大によって制作され、日本国際観光映像祭 ART ＆ FACTORY JAPAN で観客賞を受賞しました。この作品は、与論島における農業と漁業を基盤とした生活に焦点を当てています。' where id = 'irHNsFDdmFhB3BydAPuW6';
update content_bodies set title = 'un, paru, aikyun', description = 'The film ''un, paru, aikyun'' directed by Hiroshi Ito received the Audience Award at the Japan International Tourism Film Festival ART & FACTORY JAPAN. It highlights the lifestyle based on agriculture and fishing on Yoron Island.' where id = 'DF_hDnt-5jU4l8rsv72T8';
update content_bodies set title = 'ヨロンがもっと楽しくなる島あそび', description = '「ヨロンブルー」と呼ばれる美しい海に囲まれたヨロン島には、まだ知られていない歴史や文化、アクティビティが豊富にあります。この島を訪れることで、美しい自然と共に新たな魅力を発見し、楽しむことができます。詳細は公式サイトやインスタグラムをご覧ください。' where id = '340AerSzSCiFPnIiMQZbm';
update content_bodies set title = 'Enjoy Yoron More - Island Activities to Make Your Yoron Experience More Fun', description = 'Yoron Island, surrounded by the beautiful sea known as ''Yoron Blue,'' is rich in history, culture, and activities that are yet to be discovered. Visitors to Yoron Island can enjoy its stunning natural beauty while exploring the unique attractions that the island has to offer. For more information, visit the official website or Instagram.' where id = 'g0wAQoQ38OevYrYv0DF9-';
update content_bodies set title = '【文化ツアー編】ENJOY YORON MORE - ヨロンがもっと楽しくなる島あそび', description = '「ヨロンブルー」と呼ばれる美しい海に囲まれたヨロン島には、まだ知られていない歴史や文化、アクティビティが豊富にあります。ヨロン島を訪れた際には、美しい自然と共に新たな魅力を楽しんでください。' where id = 'aLJy8qvBCegfp4wWevSDw';
update content_bodies set title = 'Cultural Tour Edition: Enjoy Yoron More - Discover More Fun on Yoron Island', description = 'Yoron Island, surrounded by the beautiful sea known as ''Yoron Blue,'' is rich in history, culture, and activities that are still largely unknown. Visitors to Yoron Island can enjoy the stunning natural beauty while discovering new attractions and experiences unique to the island.' where id = 'DEdsheLx87w1Yh8q5Xk3X';
update content_bodies set title = '【ウェルネス編】ENJOY YORON MORE - ヨロンがもっと楽しくなる島あそび', description = '「ヨロンブルー」と呼ばれる美しい海に囲まれたヨロン島には、まだ知られていない歴史や文化、アクティビティが豊富にあります。この島を訪れることで、美しい自然と共に新たな魅力を発見し、楽しむことができます。ヨロン島の魅力を存分に味わってください。' where id = 'F0OJOgaeyVd7i8gHnsIsa';
update content_bodies set title = 'Enjoy Yoron More - Island Activities for Wellness', description = 'Yoron Island, surrounded by the beautiful sea known as ''Yoron Blue,'' is rich in undiscovered history, culture, and activities. Visitors to Yoron Island can enjoy the stunning natural beauty while exploring the island''s unique attractions. Experience the charm of Yoron and make the most of your visit.' where id = 'FWPVyynC82sZE12JJH9M-';
update content_bodies set title = '【星空ツアー編】ENJOY YORON MORE - ヨロンがもっと楽しくなる島あそび', description = '「ヨロンブルー」と呼ばれる美しい海に囲まれたヨロン島には、まだ知られていない歴史や文化、アクティビティなどの魅力がたくさんあります。ヨロン島を訪れた際には、美しい自然と共に新しい魅力を楽しんでください。公式サイトやインスタグラムで詳細を確認できます。' where id = '6vrkViC0y7coKzSBcaEdC';
update content_bodies set title = 'Stargazing Tour Edition - Enjoy Yoron More', description = 'Yoron Island, surrounded by the beautiful sea known as ''Yoron Blue'', is rich in undiscovered history, culture, and activities. Visitors to Yoron Island can enjoy the stunning natural beauty while exploring the island''s unique attractions. For more information, visit the official website or Instagram.' where id = 'v050JHnU_FRK8tvpQmb6z';
update content_bodies set title = '【ヨロン島】沖縄からヨロン島へのフェリーの旅（ショート版）', description = '沖縄北部エリアは2021年に世界自然遺産に認定され、やんばるの森には美しい緑や清らかな水、希少な動植物が生息しています。本部港からフェリーで約2時間の距離にあるヨロン島は、美しい青い海を誇る南国の楽園です。ヨロン島では、青く輝くYORON BLUEの海を楽しむ様々なマリンレジャーがあり、歴史や郷土文化、美味しい食事、島の人々との出会いが旅の思い出を作ります。友達やカップル、ファミリーで訪れても、島の美しい海と優しい人々があなたを待っています。やんばるの緑とヨロン島の青い海という異なる魅力がフェリーで繋がり、特別な観光体験を提供します。' where id = 'Q7vA_sMFX4Re3C0-M4ZMV';
update content_bodies set title = 'Ferry Journey to Yorontou Island from Okinawa (Short Version)', description = 'The northern area of Okinawa was designated a UNESCO World Heritage site in 2021. The Yanbaru forest in northern Okinawa is home to lush greenery, clear streams, and numerous rare species of flora and fauna. Approximately two hours by ferry from Motobu Port in northern Okinawa lies Yorontou Island, known as a ''tropical paradise'' with its stunning blue sea. Yorontou offers various marine leisure activities to enjoy the beautiful YORON BLUE waters. Beyond the sea, visitors can experience the island''s history, local culture, delicious cuisine, and meet the friendly locals, creating unforgettable travel memories. Whether with friends, as a couple, or with family, the island''s beautiful sea and warm people are always waiting for you. The contrasting charms of Yanbaru''s greenery and Yorontou''s blue sea are connected by the ferry, providing a unique tourism experience.' where id = 'HigidMwfRPMfOhzvWaFmN';
update content_bodies set title = '【かき氷】南阿蘇のやさしい氷PR動画（2022年）', description = '夏本番が近づいてきました。暑い日やご褒美に、こだわりのかき氷を楽しんでみませんか？南阿蘇エリアでは、特別なかき氷が楽しめるお店が揃っており、「かき氷マップ 2022」が南阿蘇観光案内所や掲載店舗で配布されます。この夏は、南阿蘇でやさしい氷を食べ歩くのはいかがでしょうか？詳細は公式HPをご覧ください。' where id = 'rnLH6CT5nj0BIh9k4uhVo';
update content_bodies set title = 'Kakigori: Gentle Ice from Minami Aso PR Video (2022)', description = 'As summer approaches, it''s the perfect time to enjoy refreshing kakigori (shaved ice) as a treat on hot days. The Minami Aso area offers a selection of unique kakigori shops, and a ''Kakigori Map 2022'' will soon be distributed at the Minami Aso Tourist Information Center and participating stores. This summer, why not explore and savor the gentle ice of Minami Aso? For more information, visit the official website.' where id = 'OjmJHCz4GjclrI_Sgxe1K';
update content_bodies set title = '今こそ！南阿蘇エリアで「深呼吸」しよう！ ～高森町・山都町・南阿蘇村・西原村を巡る旅へ～', description = '南阿蘇エリアには、密を避けながら楽しめる絶景「深呼吸スポット」が多数存在します。道中にはお洒落なカフェや美術館、絶景のパワースポットが点在しており、1日中楽しむことができます。暖かな陽気の中、春のお出かけとして南阿蘇を巡るのはいかがでしょうか？' where id = 'EShCXoeUs4eOQz3XZppLq';
update content_bodies set title = 'Now is the Time! Let''s ''Breathe Deep'' in the Minami Aso Area! - A Journey through Takamori Town, Yamato Town, Minami Aso Village, and Nishihara Village', description = 'The Minami Aso area is filled with breathtaking ''breathing spots'' that allow you to avoid crowds. Along the way, you can find stylish cafes, art museums, and stunning power spots, ensuring a day full of enjoyment. With the warm weather, why not take a spring outing to explore the beautiful Minami Aso region?' where id = 'RshS39lSVEjATpHy5Rz_o';
update content_bodies set title = '【VR】南阿蘇 空から見た立野ダム360°（建設中 in April 2020）', description = '立野ダムは、阿蘇カルデラから熊本市へ流れる一級河川「白川」の治水を目的に建設が進められています。このダムは環境に配慮した流水型ダムで、2023年の完成を目指して工事が行われています。本動画は2020年4月時点の立野ダムの様子を映しています。' where id = 'weJ0u_5QnZJsX30HJXzxx';
update content_bodies set title = 'VR: 360° View of the Tateno Dam from Above in Minami-Aso (Under Construction in April 2020)', description = 'The Tateno Dam is being constructed to manage the flow of the Shirakawa River, a first-class river flowing from the Aso caldera to Kumamoto City. This environmentally friendly flow-type dam is under construction with a target completion date in 2023. The video showcases the dam''s status as of April 2020.' where id = 'fHhVYpTqVQ3S26N3MVFG9';
update content_bodies set title = '熊本県 南阿蘇温泉郷PRムービー「わく、みなみあそ」', description = '南阿蘇村温泉旅館組合の公式HPでは、南阿蘇温泉郷の魅力を紹介しています。この動画は、過去に訪れた人々やこれから訪れる人々に喜びと期待感を呼び起こすことを目的としています。温泉の自然の美しさや温かさを強調し、南阿蘇の独特の魅力を体験するように誘っています。また、距離を越えていつか南阿蘇で会いましょうというメッセージが込められており、五岳五湯の魅力を伝えています。' where id = 'QCoL8lpV8nbbU-nwYy1ev';
update content_bodies set title = 'Kumamoto Prefecture Minami Aso Onsen Resort PR Movie ''Waku, Minami Aso''', description = 'The official website of the Minami Aso Village Onsen Ryokan Association promotes the Minami Aso hot spring area. The video aims to evoke feelings of joy and anticipation for both past visitors and those planning to visit in the future. It emphasizes the natural beauty and warmth of the hot springs, inviting everyone to experience the unique charm of Minami Aso. The message encourages people to overcome distances and meet in Minami Aso someday, highlighting the area''s five mountains and five hot springs.' where id = 'jp-qN4mAQX8wrPf9eR2IX';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「南阿蘇TEA HOUSE」', description = '熊本県南阿蘇村にあるハーブティー専門店「南阿蘇TEA HOUSE」は、阿蘇の山々と穏やかな日差しのもとで、豊かな自然の中でハーブを栽培しています。世界各地から厳選したハーブを取り扱い、全てのブレンドを自社で行っています。良質な水と土、穏やかな日差し、心地よい風が揃った南阿蘇村で育てられたハーブは、香り豊かで美味しいハーブティーに仕上がります。農薬や化学肥料は使用せず、JAS認定を受けた安全な農地で栽培されています。' where id = 'Yvfs5zViiYHXE4v7E9IDm';
update content_bodies set title = 'Kumamoto Prefecture Minami-Aso Village Furusato Tax Donation and Return Gift PR Movie ''Minami-Aso TEA HOUSE''', description = 'Minami-Aso TEA HOUSE is a specialty herb tea shop located in Minami-Aso Village, Kumamoto Prefecture. Under the gentle sunlight and surrounded by the mountains of Aso, the shop cultivates herbs in rich nature and offers carefully selected herbs from around the world, blending all products in-house. The ideal conditions for herbs, including high-quality water, soil, gentle sunlight, and pleasant winds, contribute to the creation of aromatic and delicious herbal teas. The herbs are grown without pesticides or chemical fertilizers on JAS-certified safe farmland.' where id = 'z7oOM5wuvqVi_ArxRy4C1';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「オーガニック野菜のベビーフード」', description = '南阿蘇村の返礼品として人気の離乳食「くちどけ」シリーズは、栄養士が監修し、産婦人科で扱われる安心安全な商品です。このシリーズは、有名な産婦人科からの依頼を受けて始まり、専門医と相談しながら作られています。現在も多くの親子に愛されており、南阿蘇オーガニックが製造しています。この会社は10年以上にわたり化粧品やハーブの栽培を行っており、オーガニックと安全性にこだわってきました。赤ちゃんに最初から安心安全なものを与えたいという思いから、食品の安全性も追求しています。' where id = 'pt-aRa39zGq6RWLKE0p0J';
update content_bodies set title = 'Kumamoto Prefecture Minami-Aso Village Furusato Tax Return Gift PR Movie ''Organic Vegetable Baby Food''', description = 'The ''Kuchidoke'' series of baby food is a popular return gift from Minami-Aso Village. Supervised by nutritionists, this safe and secure baby food is used in obstetrics and gynecology. It began with a request from a well-known obstetrics clinic to create baby food. Developed in consultation with specialists, it ensures the highest safety standards. The ''Kuchidoke'' series is still available at renowned clinics and is loved by many parents and children. Minami-Aso Organic, the producer of the ''Kuchidoke'' series, has over ten years of experience in cultivating cosmetics and herbs, always prioritizing organic and safety. They have expanded their commitment to food safety, driven by the desire to provide the safest options for babies from the very beginning.' where id = 'i1z5NQqUTf5bw2ZBixNPa';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「南阿蘇の水」編', description = '阿蘇地域は世界最大級のカルデラを有し、阿蘇山から湧き出る豊かな天然水の宝庫です。南阿蘇には11箇所の水源があり、特に白川水源は毎分60トンのミネラルを適度に含んだ水が湧き出ており、南阿蘇を代表する水源です。白川水源を含む各湧水群からの水は南阿蘇村の田畑を潤し、美味しいお米や野菜、果物を育てています。「白川水源の水」は、ミネラルを適度に含んだ中軟水を非加熱処理でそのままお届けしています。' where id = 'm3E5bMcraQOXzUa_zA0Be';
update content_bodies set title = 'Furusato Tax Donation and Return Gift PR Movie from Minami-Aso Village: ''Water of Minami-Aso''', description = 'The Aso region, home to one of the world''s largest calderas, is a treasure trove of natural water sources, thanks to the abundant spring water from Mount Aso. Minami-Aso boasts 11 water sources, with the Shirakawa Spring being the most prominent, producing 60 tons of mineral-rich water per minute. This water nourishes the fields of Minami-Aso Village, contributing to the delicious growth of rice, vegetables, and fruits. The water from Shirakawa Spring is delivered as moderately mineralized, non-heated soft water, preserving its natural taste.' where id = 'amrMHFip4lM24YkwgHggF';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「南阿蘇菓舗・古今堂」編', description = '生チーズ饅頭一五九二（ひごくに）は、素材選定からこだわった生チーズ饅頭です。チーズ餡の原料は阿部牧場のASOMILKで、2013年には国際味覚審査機構で日本初の三ツ星を受賞しました。自社工場で自家製のクリームチーズを作り、熊本の地下水で育った小麦を使用しています。独自の製法でしっとりと焼き上げ、口の中でとろける生キャラメルのような食感を追求しました。「一五九二」の由来は、熊本県の阿蘇山の標高1592ｍと肥後の国から名づけられています。冷やしても凍らせても美味しくいただけます。' where id = 'zGgeWrny5yjY01OVP2oR3';
update content_bodies set title = 'Furusato Tax Donation and Return Gift PR Movie: ''Kokindo'' Edition', description = 'The ''Higokuni'' fresh cheese bun is a thoughtfully crafted product that begins with careful selection of ingredients. The cheese filling is made from ASOMILK, sourced from Abe Farm, which received a three-star rating from the International Taste Institute in 2013, marking it as the first milk in Japan to achieve this honor. The process starts with making homemade cream cheese in their factory using ASOMILK, and they also select wheat grown with Kumamoto''s underground water. Their unique baking method results in a moist texture that melts in the mouth, reminiscent of fresh caramel. The name ''Higokuni'' is derived from the height of Mount Aso in Kumamoto, which is 1592 meters, and the name of the region, Higo. It can be enjoyed chilled or frozen.' where id = 'BsIW07qy77ucmADrIA66c';
update content_bodies set title = '【かき氷】南阿蘇のやさしい氷PR動画 - 第二弾（2021年）', description = '夏本番が近づいてきました。暑い日やご褒美に、こだわりのかき氷を楽しんでみませんか？第一弾に続くこの第二弾では、さらに多くのかき氷が楽しめるお店を紹介します。「かき氷マップ2021」には南阿蘇村だけでなく、西原村や高森町のお店も掲載されており、南阿蘇観光案内所や掲載店舗で配布中です。この夏は、南阿蘇でやさしい氷を食べ歩いてみてはいかがでしょうか。紹介されたお店には、風流 kazaru cafe、ベリー樹ベリー、南阿蘇菓子処 蘇水があります。第三弾も近日公開予定です。' where id = 'LaDoD02OmKKIfPjmfkWba';
update content_bodies set title = 'Shaved Ice in Minami Aso - PR Video Part 2 (2021)', description = 'As summer approaches, it''s the perfect time to enjoy some special shaved ice on hot days or as a treat. Following the first installment, this second video introduces more shops where you can savor unique shaved ice. The ''Shaved Ice Map 2021'' includes not only Minami Aso Village but also shops in Nishihara Village and Takamori Town, and is available at the Minami Aso Tourist Information Center and participating stores. This summer, why not explore and enjoy gentle ice in Minami Aso? Featured shops include Kazaru Cafe, Berry Tree, and Asosui Confectionery. Stay tuned for the third installment coming soon!' where id = 'QiyvpVLqJvzfnYTTvIF0C';
update content_bodies set title = '【かき氷】南阿蘇のやさしい氷PR動画 - 第一弾(2021年)', description = '夏本番が近づいてきました。暑い日やご褒美に、こだわりのかき氷を楽しんでみませんか？南阿蘇エリアのかき氷を提供するお店をまとめた「かき氷マップ2021」が、南阿蘇観光案内所や掲載店舗で配布されます。この夏は、南阿蘇でやさしい氷を食べ歩くのはいかがでしょうか？動画では、てのはan、万福小屋どんぶらこ、久永屋などの店舗が紹介されており、それぞれのInstagramやGoogleマップのリンクも掲載されています。第二弾は7月15日に公開予定で、第三弾も順次公開される予定です。' where id = 'Ff08ySh7pb1I6b0PRzlqr';
update content_bodies set title = 'Shaved Ice in Minami Aso - Promotional Video Part 1 (2021)', description = 'As summer approaches, why not enjoy some carefully crafted shaved ice on hot days or as a little treat? A ''Shaved Ice Map 2021'' featuring shops in the Minami Aso area will be distributed at the Minami Aso Tourist Information Center and participating stores. This summer, consider exploring Minami Aso to taste the gentle ice. The video introduces several shops, including ''tenoha an'', ''Manpuku Goya Donburako'', and ''Hisnagaya'', each with their Instagram and Google Map links provided. Stay tuned for Parts 2 and 3 of the series, with Part 2 set to be released on July 15th.' where id = 'Bl3tC944z4W2CZyoLAAaP';
update content_bodies set title = '南阿蘇で深呼吸しよ（南阿蘇エリアの4大深呼吸スポット＋αの旅へ）', description = '南阿蘇エリアには、密を避けながら絶景を楽しめる「深呼吸スポット」が多数あります。ドライブに最適なテイクアウトフードやカフェ、いちご狩りやパワースポットなどのアクティビティも充実しており、1日中楽しむことができます。暖かな陽気の中、春のお出かけに南阿蘇で息抜きをしてみてはいかがでしょうか。動画で紹介されている4大深呼吸スポットは、高森殿の杉（高森町）、鳥の小塚公園（南阿蘇村）、通潤橋（山都町）、白糸の滝（西原村）です。また、熊本県民向けに宿泊補助も実施中で、1人1泊当たり最大5,000円の割引が受けられます。この企画は南阿蘇観光協会連絡協議会が行い、南阿蘇フィルムが制作しています。' where id = '9qw4IArGvgACepmvF_FqN';
update content_bodies set title = 'Breathe Deeply in Minami-Aso (A Journey to the Four Major Breathing Spots in the Minami-Aso Area + More)', description = 'The Minami-Aso area is home to many breathtaking ''breathing spots'' that allow you to avoid crowds. Enjoy a perfect drive with takeout food, cafes, and activities like strawberry picking and visiting power spots, ensuring a full day of fun. With the warm weather, why not take a spring outing to relax in Minami-Aso? The four major breathing spots featured in the video include Takamori''s Cedar (Takamori Town), Tori no Kozuka Park (Minami-Aso Village), Tsujun Bridge (Yamato Town), and Shiraito Falls (Nishihara Village). Additionally, there is a lodging subsidy for Kumamoto residents, offering up to 5,000 yen off per person per night. This initiative is organized by the Minami-Aso Tourism Association and produced by Minami-Aso Film.' where id = 'Ay97qZXUgKBJQcjDHueXp';
update content_bodies set title = '【デジタルデトックス×民泊】「スマホを"OFF"にしたら、ワタシが"ON"になった。」【長崎県佐世保市宇久町観光協会PR動画】', description = '長崎県佐世保市の宇久島で、九州初の「デジタルデトックス × 民泊」をテーマにした観光プロモーションが始まりました。このプロモーションでは、宇久島での体験を紹介する5分間のムービーが制作され、デジタル社会に疲れたサラリーマンが宇久島を訪れ、心が充電されていく様子が描かれています。自然や食、人々がもたらす癒やしの旅を通じて、デジタルから離れた生活の重要性が強調されています。' where id = 'MC5zFBCH8sGuxG-xE-SMH';
update content_bodies set title = 'Digital Detox x Minpaku: ''Turning My Phone OFF Made Me Turn ON'' - PR Video from Ukushima, Sasebo City, Nagasaki Prefecture', description = 'A new tourism promotion has launched in Ukushima, Sasebo City, Nagasaki Prefecture, focusing on the first ''Digital Detox x Minpaku'' experience in Kyushu. A five-minute video showcases the experiences available on Ukushima, highlighting a story of a weary salaryman who visits the island and rejuvenates his spirit. The video emphasizes the healing journey provided by the island''s nature, food, and people, encouraging viewers to explore this unique opportunity for a refreshing escape from the digital world.' where id = 'Rg85tfa39SKpZXJFSGT7O';
update content_bodies set title = 'THE ROOTS #08 田尻気候の答えはイタリア野菜', description = '福山市田尻町で、田中陽三郎さんが個性豊かなイタリア野菜を育てています。色鮮やかで甘いパプリカ「パレルモ」、ちりちりフリルの「カリーノケール」、とげとげ頭の「ロマネスコ」、宇宙人のような「コールラビ」など、見た目が個性的でありながら食べやすいのが特徴です。2年前に地元の仲間がつないだご縁で、これらの種が田尻に持ち込まれました。栽培技術の向上と品種の増加により、評判が広まり、今では地元の飲食店で人気の食材となっています。洒落たイタリア料理店だけでなく、ラーメン屋やカレー屋でも使われ、料理人の好奇心を刺激し、料理を鮮やかに彩っています。まずは塩とオリーブオイルで楽しむのがおすすめです。' where id = 'giaAxq9JnA6E17w_z5_L3';
update content_bodies set title = 'THE ROOTS #08: The Answer to Tajiri''s Climate is Italian Vegetables', description = 'In Tajiri Town, Fukuyama, Yozaemon Tanaka cultivates unique Italian vegetables. These include vibrant and sweet ''Palermo'' peppers, frilly ''Carino Kale'', spiky ''Romanesco'', and alien-like ''Kohlrabi''. Each vegetable is visually striking yet easy to eat with minimal unpleasant flavors. Two years ago, a connection made by local friends brought these Italian vegetable seeds to the area. As cultivation techniques improved and varieties expanded, their popularity soared, leading local restaurants to embrace them. Not only upscale Italian eateries but also ramen and curry shops are now using these vegetables, which stimulate the curiosity of chefs and add vibrant colors to their dishes. They are best enjoyed simply with salt and olive oil.' where id = 'Wz8V_tCKnDeXPMaLLC7YX';
update content_bodies set title = 'EN', description = '「EN」というプロジェクトは、福井県高浜町の制作で、高浜観光協会がスポンサーを務めています。このプロジェクトは、人生における予期しない出会いの美しさを強調し、各出会いが新たな経験へとつながることを示唆しています。出演者にはメアリー・ポペオとショーン・ツキダが、監督は楠木健太郎が務めています。また、JR小浜線や青海神社、地元の企業や団体など、プロジェクトに貢献した多くの関係者に特別な感謝が捧げられています。' where id = 'ns6d1CPLsxYxeKGDzrGlx';
update content_bodies set title = 'EN', description = 'The project titled ''EN'' is a production from Takahama Town in Fukui Prefecture, sponsored by the Tourism Association of Takahama. It emphasizes the beauty of unexpected encounters in life, suggesting that each meeting leads to new experiences. The production features actors Mary Popeo and Sean Tsukida, directed by Kentaro Kusunoki. Special thanks are given to various local entities, including the JR Obama Line, Seikai Shrine, and several local businesses and organizations that contributed to the project.' where id = 'eZFFfvx10bOcpbEiUt2YV';
update content_bodies set title = 'EAT & LEAD', description = 'EAT & LEADは、食を通じて個々の生き方を考えさせるプラットフォームです。食材と向き合い、喜びや笑いを共有し、人々のつながりを育むことを目指しています。この取り組みは、さまざまな食の側面を探求する機会を提供し、個々の本来的な幸せと成長へと導くことを目的としています。今、私たちが自分自身の生き方を見つめ直すことが重要な時期だからこそ、EAT & LEADは「食べること」の価値を強く信じています。' where id = 'eIABWqm_GCT3Yx9jmOA0I';
update content_bodies set title = 'EAT & LEAD', description = 'EAT & LEAD is a platform that emphasizes the value of food and its connection to individual lives. It encourages people to engage with food, fostering joy, laughter, and connections among individuals. The initiative aims to create opportunities for people to explore various aspects of food, leading them towards their inherent happiness and personal growth. In a time when reflection on one''s way of life is essential, EAT & LEAD believes strongly in the significance of eating and the experiences that come from it.' where id = 'sjCWk1JQU4nGzPaviTOVm';
update content_bodies set title = 'いま、わたしにできること。', description = '2021年5月、新型コロナウイルスの感染拡大による未曾有の事態の中、ある女性が新型コロナ宿泊療養施設のキッチンで軽症患者への食事提供を自ら志願しました。彼女は家族や部下を巻き込むことに申し訳なさを感じつつも、隔離生活を送る人々に心のケアを届けたいという想いを抱いていました。食事の時間を楽しみにしてもらうことで、少しでも心を癒したいと考えたのです。彼女の熱意に触発され、地域の仲間たちもそれぞれの方法で支援を始めました。新鮮な食材を大切に扱い、味覚や嗅覚がない方にも楽しんでもらえるように工夫し、心を込めて調理しました。患者が元気になり、明日を楽しみにしてもらえるように、彼女の想いと仲間たちの想いが届くことを願っています。' where id = 'hsXEL0WD4H1KZ3oaiDrNq';
update content_bodies set title = 'What I Can Do Now', description = 'In May 2021, amidst the unprecedented situation caused by the COVID-19 pandemic, a woman volunteered to provide meals for mild patients at a COVID-19 accommodation facility. Despite feeling guilty about involving her family and subordinates, she was driven by a desire to bring comfort to those isolated from their loved ones. She aimed to make meal times something to look forward to, offering emotional support through food. Inspired by her passion, many in the community began to contribute in their own ways. They prepared fresh ingredients with care, ensuring that even those who had lost their sense of taste and smell could enjoy the colors and textures of the meals. The goal was to help patients look forward to tomorrow and to leave the facility feeling better, with the hope that their collective efforts would reach those in need.' where id = 'In1gUVYs9HHtHFDc7dm3s';
update content_bodies set title = 'THE ROOTS #06 山の神から恵まれたジビエ', description = '福山市熊野町に住む岡田臣司さんは、狩猟、農業、養蜂を通じてサスティナブルな暮らしを実践しています。彼は「食べることは環境を考えることと同義」と語り、私たちが口にする食材は自然環境と密接に結びついていると強調します。狩猟採集を通じて身体性を取り戻すことを目指し、11月15日からの可猟期間に猟銃を持って里山へ出かけます。天候や気温に応じて変わる鳥獣の行動を読み取り、五感を頼りにその痕跡を追います。流し猟は自然との対話であり、鹿肉はエネルギー源として最適です。しかし、猟師にとって“ジビエ”は命の循環を意味し、静かに祈りを捧げて山の神の恵みに感謝しながら食事を楽しみます。' where id = 'RCThMGgePxegQsdXskOso';
update content_bodies set title = 'THE ROOTS #06 Gifts from the Mountain God: Sustainable Game', description = 'In Kumano-cho, Fukuyama, close to the Seto Inland Sea, Shinji Okada lives a sustainable lifestyle through hunting, farming, and beekeeping. He believes that eating is synonymous with considering the environment. The food we consume is intertwined with the natural environment that nurtures it. Okada emphasizes the importance of not polluting the sea and starting agriculture with soil preparation. His journey into hunting and gathering began as a way to reconnect with his physicality. During the hunting season starting November 15, he ventures into the mountains with a shotgun, tracking wildlife by reading their behavior patterns influenced by weather and temperature. This practice, known as ''nagashi-ryo,'' is a dialogue with nature, requiring deep knowledge of the mountains and animals. The deer meat, rich in glycogen, is ideal for energy, but for hunters, ''game'' signifies the cycle of life and death. Today, he quietly disciplines himself with a prayer, expressing gratitude for the blessings of the mountain god before enjoying his meal.' where id = '_hV4dK4mSbLaheGcKNsDq';
update content_bodies set title = '1825', description = 'このウェブサイトは https://etooto.jp/ というURLを持っています。サイトの内容や目的に関する詳細は提供されていません。' where id = 'TLYDr5pYHw8pjATtNXaJD';
update content_bodies set title = '1825', description = 'This is a website with the URL https://etooto.jp/. Further details about the content or purpose of the site are not provided.' where id = 'EoE-NOyuKchLdTb75GdTR';
update content_bodies set title = 'KAKU', description = 'KAKUは、2018年のHADC TV/CM/モーショングラフィック部門賞を受賞した作品です。書家の角が登場し、日本の漢字文化を世界に広めることを目指しています。角はニューヨークのJCATに所属しており、現在、ヒホン市の旧王立博物館で開催中の第50回記念スペイン美術賞展に参加しています。この展覧会は6月10日まで行われます。また、角はJapan Expo Paris 2018にも出展することが決定しています。' where id = 'EDD9Fj1IdDgEVan4oMqSO';
update content_bodies set title = 'KAKU', description = 'KAKU is a work that won the 2018 HADC TV/CM/Motion Graphics Award. It features the calligrapher Kaku, who aims to promote Japanese kanji culture globally. Kaku is affiliated with JCAT in New York and is currently participating in the 50th Anniversary Spain Art Award Exhibition at the old Royal Museum in Gijón, which runs until June 10. Additionally, Kaku is set to exhibit at Japan Expo Paris 2018.' where id = '-fjqTnPQ5zUCg8wV6I_gy';
update content_bodies set title = '津軽あかつきの会「故郷の味を100年先まで」', description = '青森県弘前市で、津軽地方の郷土料理と食文化を伝える「伝承料理」活動を行っている女性だけの料理研究ユニット「津軽あかつきの会」のオリジナルショートムービーです。この活動は、母の味を食べたいという思いから、代表の工藤良子さんによって始められました。映像では、伝承料理の重要性や、未来の世代にこの味を伝えることの大切さが表現されています。いつか現地でこの味を味わっていただける日を楽しみにしています。' where id = 'kwQLgHe-MKq4oMSMk3EYn';
update content_bodies set title = 'Tsugaru Akatsuki Association: ''Preserving Hometown Flavors for 100 Years''', description = 'This is an original short film featuring the Tsugaru Akatsuki Association, a women-only culinary research unit dedicated to preserving the traditional cuisine and food culture of the Tsugaru region in Hirosaki City, Aomori Prefecture. The initiative was started by the president, Yoshiko Kudo, who was inspired by the desire to taste her mother''s cooking. The film captures the essence of this activity, highlighting the importance of passing down these flavors for future generations. The association looks forward to the day when people can experience these traditional tastes in person.' where id = 'G5Ao3rlkDfkSrtk65iIm0';
update content_bodies set title = 'ドローン空撮　青森の紅葉（城ヶ倉大橋、中野もみじ山、蔦沼）', description = '新型コロナウイルス感染症の収束後、国内外から多くの方々に青森県を訪れていただきたいという願いを込めて、ドローンで撮影した青森県の紅葉映像を公開します。映像は城ヶ倉大橋、中野もみじ山、蔦沼の紅葉を紹介しています。蔦沼は紅葉シーズンに非常に混雑するため、路上駐車対策や混雑対策が行われています。また、蔦沼以外にも魅力的な観光地が多く、四季を通じて美しい景観を楽しむことができるため、混雑時期以外の訪問もお勧めします。' where id = 'M-KgXqPgJmgkSYDSZtBt4';
update content_bodies set title = 'Drone Aerial Photography of Aomori''s Autumn Foliage (Jogakura Bridge, Nakano Momiji Mountain, Tsutanuma)', description = 'After the resolution of the COVID-19 pandemic, we hope to welcome many visitors from both domestic and international locations to Aomori Prefecture. We are pleased to share drone footage showcasing the autumn foliage in Aomori, specifically at Jogakura Bridge, Nakano Momiji Mountain, and Tsutanuma. Please note that Tsutanuma can become very crowded during the autumn season, and measures are taken each year to manage roadside parking and congestion. There are many other attractive locations around Tsutanuma, allowing visitors to enjoy beautiful scenery throughout the year, so we recommend visiting during less crowded times as well.' where id = 'TQTVVYTezV7Fig2TNS8nq';
update content_bodies set title = '2020 蔦沼の朝焼け ドローン映像', description = '青森県では、地域の関係者の協力のもと、美しい蔦沼の朝焼けを自宅で楽しめるドローン映像を公開しています。紅葉シーズンの蔦沼は非常に混雑するため、毎年路上駐車対策や混雑対策が行われています。蔦沼周辺には他にも魅力的な観光地が多数あり、四季を通じて美しい景観を楽しむことができるため、混雑時期以外の訪問もお勧めです。' where id = 'wUUvi89XXJG6w-RyRjfaU';
update content_bodies set title = '2020 Tsutanuma Sunrise Drone Footage', description = 'In Aomori Prefecture, drone footage showcasing the beautiful sunrise at Tsutanuma is being released with the cooperation of local stakeholders, allowing you to enjoy this view from home. During the autumn foliage season, Tsutanuma becomes very crowded, prompting annual measures for roadside parking and congestion management. There are many other attractive locations around Tsutanuma, and visitors can enjoy beautiful scenery throughout the four seasons, making it advisable to consider visiting during less crowded times.' where id = 'wrmjShIGZGN3SlVrFv8Qj';
update content_bodies set title = 'ドローンで見る五所川原立佞武多2020 PART２', description = '今年は新型コロナウイルス感染症の拡大防止のため、五所川原立佞武多の運行が中止となりました。青森県では地域の協力のもと、ドローンを使用して高さ23mの立佞武多の迫力映像をライブ配信しました。ライブ配信された映像は再編集されて公開されています。新型コロナウイルスの収束後には、国内外から多くの方々に青森県を訪れていただきたいと願っています。' where id = 'yZEqbMq3gWRXLYhNHb0LH';
update content_bodies set title = 'Viewing Goshogawara Tachineputa 2020 with Drones PART 2', description = 'This year, the Goshogawara Tachineputa festival was unfortunately canceled due to the spread of COVID-19. In Aomori Prefecture, with the cooperation of the local community, a powerful live broadcast of the 23-meter tall Tachineputa was captured using drones. The live footage has been re-edited and is now available for viewing. We hope that after the resolution of the COVID-19 pandemic, many people from both Japan and abroad will visit Aomori Prefecture again.' where id = 'yLhzcddxDZNsO0sIFOE6t';
update content_bodies set title = 'ドローンで見る五所川原立佞武多2020　PART１', description = '今年は新型コロナウイルス感染症の拡大防止のため、五所川原立佞武多の運行が中止となりました。青森県では地域の協力のもと、ドローンを使って高さ23mの立佞武多の迫力映像をライブ配信しました。ライブ配信された映像は再編集されて公開されています。新型コロナウイルスの収束後には、国内外から多くの方々に青森県を訪れていただきたいと願っています。' where id = '1NjcYiUVhQ__wH9Vn8qrs';
update content_bodies set title = 'Viewing Goshogawara Tachineputa 2020 with Drones Part 1', description = 'This year, the Goshogawara Tachineputa festival was unfortunately canceled due to the spread of COVID-19. In Aomori Prefecture, with the cooperation of the local community, a powerful live broadcast of the 23-meter tall Tachineputa was captured using drones. The footage from the live stream has been re-edited and is now available for viewing. We hope that after the resolution of the COVID-19 pandemic, many people from both Japan and abroad will visit Aomori Prefecture again.' where id = 'EgY7bPL6YEf1BrQsaCQKe';
update content_bodies set title = '透明な海、左右からの波　～尻屋埼灯台～1', description = '日本で唯一無二の絶景が解禁されました！2018年6月1日、尻屋埼灯台が一般公開され、左側には津軽海峡、右側には太平洋の美しい景色を楽しむことができます。' where id = '7OTFa99K2zvcXVu1Gl8rO';
update content_bodies set title = 'Transparent Sea, Waves from Both Sides - Shiriya Cape Lighthouse 1', description = 'A unique scenic view in Japan has been unveiled! On June 1, 2018, the Shiriya Cape Lighthouse opened to the public, offering breathtaking views of the Tsugaru Strait on the left and the Pacific Ocean on the right.' where id = 'PY84OGZ88eiMODf4ja3CG';
update content_bodies set title = 'DELISH AOMORI「風間浦村のあんこうのベーコン巻き」', description = '「Delish Aomori」のレシピ動画シリーズは、今回の第12弾で最終回を迎えます。最後の食材は風間浦村の新鮮な鮟鱇です。風間浦村は鮟鱇の漁場が近く、特に新鮮な鮟鱇が水揚げされます。鮟鱇といえば、鮟鱇鍋が思い浮かびますが、今回は洋風の「あんこうのベーコン巻き」を紹介します。淡白な鮟鱇の身とベーコンの旨味、塩気の組み合わせが絶妙です。また、風間浦村で年に一度開催される風間浦鮟鱇感謝祭の賑わいもお届けします。' where id = 'e2e9Vj2GTkZVJWbaz7Nof';
update content_bodies set title = 'Delish Aomori: Bacon-Wrapped Anko from Kazamaura Village', description = 'The recipe video series ''Delish Aomori'' presents its final episode, featuring the fresh anko (anglerfish) from Kazamaura Village, known for its proximity to rich fishing grounds. While anko is often associated with traditional dishes like anko nabe (hot pot), this episode introduces a Western-style recipe: bacon-wrapped anko. The delicate flavor of the anko pairs perfectly with the savory and salty taste of bacon. Additionally, the video showcases the lively atmosphere of the annual Kazamaura Anko Festival, celebrating this unique local delicacy.' where id = 'U7TTVKgqnlDQFanF1-GY_';
update content_bodies set title = 'DELISH AOMORI「南部太ねぎのグラタンスープ」', description = '青森のレシピ動画「DELISH AOMORI」の第５弾では、青森県南部地方の伝統野菜「南部太ねぎ」を紹介します。この野菜は驚くほどの太さと、とろけるような食感、甘さが特徴です。その「南部太ねぎ」を使ったグラタンスープは絶品で、ぜひ味わってみてください。「DELISH AOMORI」はまるごと青森のFacebookで随時公開されています。' where id = 'mxiGspDnt8ZQEhOPkyXJr';
update content_bodies set title = 'DELISH AOMORI ''Nambu Green Onion Gratin Soup''', description = 'The fifth installment of the recipe video series ''DELISH AOMORI'' showcases the traditional vegetable from the Nambu region of Aomori Prefecture, the ''Nambu Green Onion.'' Known for its remarkable thickness, melt-in-your-mouth texture, and sweetness, this green onion is the star ingredient in a delicious gratin soup. ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = 'qqGMfb4Fm3VimgrcCiIMv';
update content_bodies set title = 'DELISH AOMORI「いたや毛豆のレアチーズムース」', description = '「DELISH AOMORI」の第４弾では、青森在来の「毛豆」である「いたや毛豆」を使用したスイーツのレシピ動画が紹介されています。この毛豆は板柳町で栽培されており、ほっくりとした食感と強い甘味が特徴です。このレシピは毛豆の特性を生かしたもので、青森の魅力を伝える内容となっています。「DELISH AOMORI」は、まるごと青森のFacebookで随時公開されています。' where id = 'LNkVfHon1hRm0aFl8IVsh';
update content_bodies set title = 'DELISH AOMORI ''Itaya Edamame Rare Cheese Mousse''', description = 'The fourth installment of the recipe video series ''DELISH AOMORI'' showcases a dessert made using the sweet and rich Itaya edamame, which is cultivated in Itayanagi Town, Aomori. This recipe highlights the unique characteristics of this local variety of edamame. ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = 'Mob5zhB2xkVdUESbqdd2k';
update content_bodies set title = 'DELISH AOMORI「田舎館村のイチゴフィズ」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第2弾では、田舎館村産のいちごを使用したおしゃれで甘酸っぱい「イチゴフィズ」を紹介します。この動画は、まるごと青森のFacebookページで随時公開されます。' where id = 'xqPZPSBNHvWr3QZIjOEvW';
update content_bodies set title = 'DELISH AOMORI ''Inakadate Village Strawberry Fizz''', description = 'The second installment of the recipe video series ''DELISH AOMORI'' presents a stylish and sweet-sour ''Strawberry Fizz'' made with strawberries from Inakadate Village. ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = 'J-PHc5MmAL9nJM3qE_Br9';
update content_bodies set title = '寒立馬の横断', description = '尻屋崎灯台へ向かう途中、一時通行止めに遭遇しました。通行止めの影響で、予定していたルートを変更せざるを得ず、周囲の景色を楽しむことができました。寒立馬の存在を感じながら、自然の美しさを再確認する良い機会となりました。' where id = 'ZqewWm1S7XoPKPw-c1whe';
update content_bodies set title = 'Crossing the Cold Standing Horse', description = 'On the way to Shiriya Cape Lighthouse, I encountered a temporary road closure.' where id = 'hfFdWmCTKpzuYX898vAuZ';
update content_bodies set title = '下北の酒と風間浦鮟鱇、め～よ～（うまいよー）！', description = '作家・大岡玲さん、浦風親方、カメラマン・松隈直樹さん、紀行作家・山内史子さんの4人が参加する「冬の青森旅」シリーズの第4回目で、風間浦の鮟鱇（あんこう）をテーマにした内容です。彼らは風間浦の鮟鱇と地元の酒の魅力を探求し、この地域の独特な食文化を紹介します。' where id = 'aQd9Ze0YmrUxya4YIvDZN';
update content_bodies set title = 'Delicious Sake from Shimokita and Kazamaura Anko', description = 'This is the first part of the ''Kazamaura Anko'' edition of the ''Winter Aomori Trip'' series, featuring writer Rei Ooka, sumo wrestler Ura Kaze, photographer Naoki Matsukuma, and travel writer Fumiko Yamauchi. The group explores the unique flavors of Kazamaura''s anko (anglerfish) and the local sake, highlighting the culinary delights of the region.' where id = 'neVIDKG5Mmst-aWvyBQFx';
update content_bodies set title = 'イサバのカッチャ（魚市場のかあちゃん）', description = '戦後から八戸の人々の生活に根付いている「いさば」は、魚市場を指します。陸奥湊駅前の朝市は毎朝多くの人々で賑わい、活気に満ちています。イサバのカッチャは、暗いうちから働き始める勤勉な母親です。このドキュメンタリーは、カッチャを通じて、彼女が生まれてからずっと通っている朝市の様子や、浜の暮らしを紹介します。' where id = 'lB_M9QRm1JSPxJrSe8jnN';
update content_bodies set title = 'Isaba no Katcha (Mother of the Fish Market)', description = 'Since the post-war period, ''Isaba'' has been rooted in the lives of people as the kitchen of Hachinohe. Isaba refers to the fish market, and the morning market in front of Mutsu-Minato Station is bustling with many visitors every morning. Katcha, the hardworking mother of the fish market, starts her day before dawn. This documentary introduces the life of the coastal community through Katcha, who has been shopping at the morning market since she was born.' where id = 'PhCtxlB9PHXGK-VHA8wN9';
update content_bodies set title = 'べこもち', description = 'べこもちは青森県下北半島に伝わる伝統的な郷土菓子です。かつては節句などの行事の際に振る舞われていましたが、現在では日常的に多くの人に愛されています。この作品は、べこもちが作られる過程を映像のみで表現しており、切り口に現れる美しい花模様を楽しむことができます。べこもちの職人技と文化的な意義を強調した作品です。' where id = '8LL54QmMCftoAk8s2_P-f';
update content_bodies set title = 'Bekomochi', description = 'Bekomochi is a traditional local sweet from the Shimokita Peninsula in Aomori Prefecture, Japan. Originally served during seasonal festivals and events, it is now enjoyed daily by many. This work presents the process of making bekomochi solely through visuals, showcasing the beautiful floral patterns that appear on its cut surface. The film highlights the craftsmanship and cultural significance of this beloved treat.' where id = 'tIhLEn4mraQEn9AWIkXWK';
update content_bodies set title = 'サナブリ', description = '青森県津軽地方では、田植えが終わると農休みに入り、集落の人々は安堵とともに豊作を願う儀礼として「サナブリ」と呼ばれる祭事を行います。津軽地方の五所川原市相内の人々は、この祭事が昔から地域の人々の憩いのひと時であり、どれだけ心待ちにしていたかを語ります。苗を植えたばかりの田んぼに飛び込む場面も見られます。' where id = 'tIj7OL4zmcFBXQatevNcM';
update content_bodies set title = 'Sanaburi', description = 'In the Tsugaru region of Aomori Prefecture, after the rice planting is completed, the community enters a farming break and holds a ritual called ''Sanaburi'' to express their relief and hope for a bountiful harvest. The people of Ainu in Goshogawara City have long cherished this event as a moment of relaxation and eagerly anticipate it. The festival includes scenes of participants jumping into the newly planted rice fields.' where id = 'P7eJ7WiHTZrH6S-AAvHOX';
update content_bodies set title = 'ホワイトインパルス', description = '青森空港は日本でも有数の豪雪地帯であり、特に雪の多い年には累計降雪量が10メートルを超えることがあります。民間航空機の定期便が発着する空港の中で、10メートルを超える降雪量を記録する空港は全国的に見ても稀です。このような豪雪に対応するため、青森空港では複数の企業が共同で構成する除雪団体「ホワイトインパルス」が活動しています。' where id = '9u-jUEJVyjy53mAkffScv';
update content_bodies set title = 'White Impulse', description = 'Aomori Airport is one of Japan''s major heavy snowfall areas, with annual snowfall exceeding 10 meters in particularly snowy years. Among airports with regular commercial flights, it is rare to find one that accumulates over 10 meters of snowfall. Supporting Aomori Airport''s operations in such heavy snow conditions is the Aomori Airport Snow Removal Consortium, known as ''White Impulse,'' which is formed by multiple companies working together.' where id = 'gfXadW42g7Ad4xDC8tRsk';
update content_bodies set title = 'はるえさん最高！ by浦風親方', description = '作家の大岡玲さん、浦風親方、カメラマンの松隈直樹さん、紀行作家の山内史子さんの4人が参加する「冬の青森旅」の第3弾です。この巻では、青森市の古川市場にある「はるえ食堂」に焦点を当てています。' where id = 'nr3iaf_EHf7k297677Blx';
update content_bodies set title = 'Haru-e is the Best! by Urakaze Oyakata', description = 'This is the third volume of the ''Winter Aomori Trip'' featuring four individuals: writer Rei Ooka, Urakaze Oyakata, photographer Naoki Matsukuma, and travel writer Fumiko Yamauchi. The focus of this volume is on ''Haru-e Shokudo'' located in Aomori City''s Furukawa Market.' where id = 'IFWiSdOlvjxfoG16qwvxd';
update content_bodies set title = '【新島・式根島 】民宿ご飯　式根鯛平君で乾杯', description = '新島村の養殖事業は1990年に始まり、30年以上が経過しました。この事業を新島在住の人々に知ってもらうため、動画制作が企画されました。島外への販売はコストがかかり、丸ごとの鯛を捌くのが難しいため、島内で「育て」「調理し」「食べる」循環を作る必要があります。また、「島の魚が手に入らない」という声に対する解決策として、安定供給が可能な養殖の鯛「式根鯛平君」が提案されています。飼育環境のアップデートと独自の配合飼料の開発により、ほどよく脂ののった美味しい鯛が実現しました。伝統的な真鯛は鮮やかな赤色が特徴ですが、式根鯛平君は無骨な色合いです。身近にいる真鯛に、あなたの色を加えてみませんか。『あなたといっしょに育てタイ！』' where id = 'eGyEQ8kWKAATaXq0j5kUu';
update content_bodies set title = 'Cheers with Shikine Taihei-kun at Shikine Island and Niijima Island', description = 'Since the start of the aquaculture business in Niijima Village in 1990, over 30 years have passed. To raise awareness among local residents, a video project was initiated. The challenge of selling fish outside the island due to high costs and the difficulty of processing whole fish has led to the need for a sustainable cycle of ''growing, cooking, and eating'' fish on the island. One solution to the common complaint of ''not being able to obtain local fish'' is the stable supply of farmed sea bream, ''Shikine Taihei-kun.'' Over the years, the rearing environment has been updated, and a unique blended feed has been developed, resulting in delicious sea bream with just the right amount of fat. While traditional sea bream is often associated with vibrant red colors, Shikine Taihei-kun has a more rustic appearance. Why not add your own color to this familiar sea bream? ''Let''s grow together with you!''' where id = 'FPFNiaTyBH--jeoQdFOWz';
update content_bodies set title = '【秋田市プロモーションビデオ①】自然の彩と隣人の温もりに富む「新波」', description = '「新波」は雄物川が運んだ文化が花開く場所であり、秋には黄金色の絨毯が広がる「式田」として知られています。この映像は、秋田市のシティプロモーションモデル事業の一環として行われたワークショップを通じて、地域住民がそれぞれの地区の魅力を見つけ出し、詰め込んだものです。「新波」では、雨の日に「洗濯もの入れておいて」と頼める隣人がいて、何があっても助け合う温かい関係が描かれています。春には緑が広がり、秋には黄金の波が心を明るくします。秋田市雄和・新波で見つけた大切なことを伝える映像です。' where id = 'CJTbcSyVlm-D_gx2oAX8q';
update content_bodies set title = 'Akita City Promotion Video ①: ''Shinba'' Rich in Nature''s Colors and Neighborly Warmth', description = 'The video showcases ''Shinba,'' where the culture brought by the Omorogawa River flourishes, and ''Shikida,'' a village adorned with a golden carpet in autumn. This film is a product of a workshop conducted as part of Akita City''s city promotion model project, where local residents identified and captured the unique charms of their respective areas. In ''Shinba,'' neighbors help each other, whether it''s asking to take in laundry during rain or supporting one another in times of need. The vibrant green of spring and the golden waves of autumn bring joy to the heart. This video highlights the important values discovered in Akita City''s Yuwa and Shinba.' where id = 'pCeAAJF6JNqpx-IexIz9L';
update content_bodies set title = '【秋田市プロモーションビデオ③】よそものを大切にしてくれるまち「式田」', description = '雄物川が運んだ文化が花開く「新波」と、秋にはこがね色の絨毯が広がる里「式田」を紹介する映像です。秋田市のシティプロモーションモデル事業の一環として、地域住民が主体となってそれぞれの地区の魅力を見つけ出しました。お金より大事な何かを探しに来た写真家や、長年の夢を追いかけるサラリーマン、笑顔を運ぶ学生たちが、まちに受け入れられ、大切にされる様子が描かれています。秋田市河辺・式田で、大切なことを見つけることができます。' where id = 'XODb0OuvI3vm1z90JGHsp';
update content_bodies set title = 'Akita City Promotion Video ③: A Town That Values Outsiders - Shikida', description = 'Shikida, where the culture brought by the Omorogawa River flourishes, is depicted in this video as part of Akita City''s city promotion model project. Through workshops led by local residents, the video captures the unique charms of the area. Photographers seeking something more valuable than money, salarymen chasing long-held dreams, and students bringing smiles are all welcomed and cherished by the town. In Akita City''s Kabe and Shikida, important discoveries await.' where id = '3JEFKLCdqGV14DbjyspVq';
update content_bodies set title = 'ダリアと菊の魅力をお届け！', description = '秋田中央地域地場産品活用促進協議会（通称「農家のパーティ」ネットワーク）は、JA秋田なまはげと秋田市、男鹿市、潟上市が連携し、地場産品の活用促進と3市の農林水産業及び食品関連産業の振興を目指して活動しています。このPRビデオでは、3市で生産されるダリアと菊の生産現場の様子を紹介し、3市の市長とJA秋田なまはげの組合長がその魅力を直接PRしています。' where id = 'EyWnzoGlFuWn8a_PRRR34';
update content_bodies set title = 'The Charm of Dahlias and Chrysanthemums!', description = 'The Akita Central Region Local Product Utilization Promotion Council, also known as the ''Farmers'' Party Network,'' collaborates with JA Akita Namahage and the cities of Akita, Oga, and Katagami to promote the utilization of local products and to enhance the agricultural, forestry, and fisheries industries, as well as food-related industries in these three cities. This PR video showcases the production sites of dahlias and chrysanthemums grown in these cities, with the mayors of the three cities and the head of JA Akita Namahage personally promoting their appeal.' where id = 'E8joI802HgmBVJcqpCHLa';
update content_bodies set title = '秋田市観光プロモーション動画「ライフ・イズ・ジャーニー」短編', description = '秋田市に住む夫婦の目線で描かれた観光プロモーション動画「ライフ・イズ・ジャーニー」の短編版は、約30秒のドラマ仕立てで、秋田市の魅力を祭りや自然、飲食店などを通じて凝縮しています。この短編は、本編につながる内容で、3月29日（水）13時頃に公開予定の本編では、秋田市内の40か所以上の観光地が紹介されます。短編版に登場するスポットには、千秋公園、あきた芸術劇場ミルハス、秋田市文化創造館、秋田県立美術館、伏伸の滝などが含まれ、秋田竿燈まつりや千秋公園桜まつりなどの祭りも取り上げられています。制作は秋田市と株式会社ヴィジュアルスペースが行い、地元市民の協力も得ています。' where id = 'r2yPn7MhsKz5fdkuN1wTH';
update content_bodies set title = 'Akita City Tourism Promotion Video ''Life is Journey'' Short Version', description = 'The short version of the tourism promotion video ''Life is Journey'' is a drama depicting the perspective of a couple living in Akita City. Lasting about 30 seconds, it encapsulates the attractions of Akita City, including festivals, nature, and restaurants, and serves as a prelude to the full version set to be released on March 29th at around 1 PM. The full version features over 40 tourist spots in Akita City. Some of the locations highlighted in the short version include Chuo Park, Akita Arts Theater, Akita Cultural Creation Center, Akita Prefectural Museum of Art, and various festivals such as the Akita Kanto Festival and the Chuo Park Cherry Blossom Festival. The video is produced by Akita City and Visual Space Co., with the participation of local citizens.' where id = 'xNB2cVC3L0PWwicj8JfZc';
update content_bodies set title = 'EEGANE! あなたの名古屋を見つけに来て！ ~神社', description = '名古屋観光コンベンションビューローは、日本に住むフィリピン人向けに名古屋を紹介するプロモーションビデオを制作しました。タイトルは「EEGANE! あなたの名古屋を見つけに来て！」です。マニラ出身のテレビ愛知アナウンサー、岡田めぐみが、フィリピン人のステファニーさんとアリサさんと共に名古屋の魅力を案内します。「EEGANE!」は名古屋弁で「素晴らしい！」という意味です。ビデオは「名古屋の食」と「神社」の2つのテーマを取り上げています。名古屋独特の食文化「モーニング」を味わったり、山田天満宮でお金を洗ったりする様子が紹介されており、名古屋での幸運を見つけることができることを強調しています。ビデオのテーマは、名古屋の魅力を「体験」として伝えることです。' where id = '3hEqpsDesGZvIEhdx7jBS';
update content_bodies set title = 'EEGANE! Come and Find, Your NAGOYA! ~Shrines', description = 'The NAGOYA Convention & Visitors Bureau has created a promotional video aimed at Filipinos living in Japan, titled ''EEGANE! Come and Find, Your NAGOYA!''. The video features Megumi Marie Okada, a TV Aichi announcer from Manila, who guides viewers through the attractions of Nagoya alongside two Filipino residents, Stephanie and Alisa. The term ''EEGANE!'' translates to ''NICE!'' in the local Nagoya dialect. The video showcases two themes: ''Nagoya food'' and ''Shrines''. It highlights unique aspects of Nagoya''s food culture, such as the local ''Morning'' cuisine, and activities like washing money at Yamada Tenmangu shrine, emphasizing the idea of finding good luck in Nagoya. The overall theme of the video is to convey the experiential charm of Nagoya.' where id = 'xJbvKtCNkGGUUHy1WANMy';
update content_bodies set title = 'めでたいでんしゃで行く。加太さかな線の旅。', description = '「めでたいでんしゃ」は、カラフルで縁起の良いデザインが特徴の観光列車です。車内には楽しい仕掛けがたくさんあり、乗るだけでしあわせな気分になります。加太さかな線のめでたいでんしゃに乗って、特別な旅を楽しんでみませんか？めでたい一日を、めでたいでんしゃと共に過ごしましょう！' where id = 'YaQDCYKKpfp5sJdqQ3Xv0';
update content_bodies set title = 'A Joyful Journey on the Medetai Train: The Kada Sakana Line', description = 'The ''Medetai Train'' is a colorful and auspiciously designed sightseeing train that offers a delightful experience. The interior is filled with fun features that elevate your mood just by riding it. Why not enjoy a special journey on the Kada Sakana Line aboard the Medetai Train? Make your day memorable with this joyful train!' where id = 'D0A2p3IXJ7fGFqEhkea74';
update content_bodies set title = '【南海電鉄】特急ラピートCM「シュッと、ラピート。ビジネス編」', description = '特急ラピートは、なんばと関西国際空港を結ぶ空港特急であり、デザインコンセプトは「レトロフューチャー」です。力強いフォルムとゆとりのある車内空間が特徴で、快適に移動できるように設計されています。おトクでスムーズな移動を提供し、なんばと関空を結ぶ重要な交通手段となっています。' where id = '0pGxP3shffcO-P9e0u7eI';
update content_bodies set title = 'Nankai Electric Railway Limited Express Rapi:t CM ''Shut, Rapi:t. Business Edition''', description = 'The Limited Express Rapi:t connects Namba and Kansai International Airport, featuring a powerful design concept of ''retro-future'' and a spacious interior. It offers a convenient and smooth journey to Namba and Kansai Airport.' where id = 'wliNotA_4_modqb77_obp';
update content_bodies set title = '【南海電鉄】特急ラピートCM「シュッと、ラピート。30秒編」', description = '特急ラピートは、なんばと関西国際空港を結ぶ空港特急であり、デザインコンセプトは「レトロフューチャー」です。力強いフォルムとゆとりある車内空間が特徴で、利用者におトクでスムーズな移動を提供します。' where id = '_vmAT6jzfORQG9nE1wDvU';
update content_bodies set title = 'Nankai Electric Railway Limited Express Rapi:t CM ''Shutto, Rapi:t. 30-Second Version''', description = 'The Limited Express Rapi:t connects Namba and Kansai International Airport, featuring a powerful design concept of ''retro-future'' and a spacious interior. It offers a convenient and smooth journey to Namba and Kansai Airport.' where id = 'q48DHEbyzsVKBvCL1DDzy';
update content_bodies set title = '泉北ニュータウンの魅力的なコミュニティ', description = '大阪府堺市南区に位置する泉北ニュータウン地域の紹介動画です。この動画では、泉北ニュータウンでの1日の暮らしや、実際に住んでいる人や働いている人の様子を紹介しています。また、期間限定でアンケートに答えると、1,000円分のQUOカードが当たるチャンスがあります。抽選で10名様にプレゼントされる予定です。アンケートの回答期限は2023年6月30日で、主催は南海電気鉄道株式会社、独立行政法人都市再生機構、大阪府住宅供給公社です。皆様のご回答をお待ちしております！' where id = '4XRQwXjUX7kaCMw8ij8vl';
update content_bodies set title = 'The Attractive Community of Senboku New Town', description = 'This is an introduction video about the Senboku New Town area located in Minami Ward, Sakai City, Osaka Prefecture. Viewers can see what a day in the life is like in Senboku New Town, along with the experiences of the residents and workers in the area. Additionally, there is a limited-time survey where participants can answer questions about the promotional video for a chance to win a 1,000 yen QUO card. Ten winners will be selected from the responses. The survey deadline is June 30, 2023, and it is organized by Nankai Electric Railway Co., Ltd., the Urban Renaissance Agency, and the Osaka Housing Supply Corporation. We look forward to your responses!' where id = 'tk-jYMNUiw-NsqzYdxAE1';
update content_bodies set title = '泉北ニュータウンで見つける心地良い暮らし', description = '大阪府堺市南区に位置する泉北ニュータウン地域の紹介動画です。この動画では、泉北ニュータウンでの1日の暮らしや、実際に住んでいる人や働いている人の様子を紹介しています。また、期間限定でアンケートに答えることで1,000円分のQUOカードが当たるチャンスもあります。泉北ニュータウンの魅力に関するアンケートに回答した方の中から抽選で10名様にプレゼントされます。アンケートの回答期限は2023年6月30日で、主催は南海電気鉄道株式会社、独立行政法人都市再生機構、大阪府住宅供給公社です。皆様のご回答をお待ちしております！' where id = 'kCpyUZSVeCbU0aCza6STF';
update content_bodies set title = 'Discovering Comfortable Living in Senboku New Town', description = 'This is an introduction video about the Senboku New Town area located in Minami Ward, Sakai City, Osaka Prefecture. Viewers can see what a day in the life is like in Senboku New Town, along with the experiences of those who live and work there. Additionally, there is a limited-time opportunity to participate in a survey to win a 1,000 yen QUO card. By answering the survey regarding the charm of Senboku New Town, 10 lucky participants will be selected to receive the card. The survey deadline is June 30, 2023, and it is organized by Nankai Electric Railway Co., Ltd., the Urban Renaissance Agency, and the Osaka Housing Supply Corporation. We look forward to your responses!' where id = 'uLH4lLGPU5Z0b7YYIojZW';
update content_bodies set title = '南海電鉄「心、やすらぐ旅 高野山。」15秒Ver.', description = '世界遺産である高野山へは南海電車でアクセスできます。高野山は弘法大師・空海によって開かれ、1200年以上の歴史を持つ聖地です。現代においてもその教えは受け継がれています。都会の喧騒を離れ、高野山とそのふもとで心やすらぐひとときをお楽しみください。' where id = 'Cm8-E6P4uF8rH_EnWMt48';
update content_bodies set title = 'Nankai Electric Railway: A Soothing Journey to Mount Koya - 15 Seconds Version', description = 'Travel to the World Heritage Site of Mount Koya via Nankai Electric Railway. Founded by the monk Kukai, Mount Koya has been a spiritual center for over 1200 years, continuing to pass down its teachings. Experience a moment of tranquility away from the hustle and bustle of the city at Mount Koya and its foothills.' where id = 'mLtqQnRevcAWsYjWvXVZ1';
update content_bodies set title = '【南海電鉄】「心、やすらぐ旅 高野山。」300秒Ver.', description = '南海電車で世界遺産・高野山へ。高野山は弘法大師・空海によって開かれ、1200年以上の歴史を持つ聖地です。現代においてもその教えは受け継がれ、まさに「天空の聖地」と呼ばれています。都会の喧騒を離れ、高野山とそのふもとで心やすらぐひとときをお楽しみください。' where id = '330zfHY6FnrUhSHERR-Ze';
update content_bodies set title = 'Nankai Electric Railway: A Journey to the Tranquil Heart of Koyasan - 300 Seconds Version', description = 'Travel to the World Heritage site of Koyasan via Nankai Electric Railway. Founded by the monk Kukai, Koyasan has been a spiritual center for over 1200 years, continuing to pass down its teachings. This sacred place, often referred to as the ''Heavenly Sanctuary,'' offers a peaceful retreat away from the hustle and bustle of the city. Enjoy a serene moment in Koyasan and its foothills.' where id = 'Rv5R5PDK3kvkUegskORTO';
update content_bodies set title = '南海電気鉄道 × モントルー・オーベルラン・ベルノワ鉄道　 祝！姉妹鉄道協定記念ムービー', description = '南海電気鉄道とモントルー・オーベルラン・ベルノワ鉄道（MOB鉄道）は、友好関係を深めるため、平成29年10月24日に「姉妹鉄道協定」を締結しました。この協定は、両沿線が国際観光地として発展し、地域活性化に寄与することを目的としています。詳細は南海高野ほっとねっとをご覧ください。' where id = 'xdyOdQRcdUHqOtvwfD-G6';
update content_bodies set title = 'Nankai Electric Railway × Montreux-Oberland Bernois Railway: Celebrating the Sister Railway Agreement', description = 'Nankai Electric Railway and the Montreux-Oberland Bernois Railway (MOB) signed a ''Sister Railway Agreement'' on October 24, 2017, aimed at deepening their friendly relations. The agreement focuses on the development of both railway lines as international tourist destinations and contributing to regional revitalization. For more details, check the Nankai Koya Hot Net!' where id = '-yuHTFOUeSUtnNYL1Z3zg';
update content_bodies set title = 'なんばHISTORY（2017年公開）', description = '大阪は古くから様々な文化と融合し続けてきた都市であり、その中心地である難波はかつて広大なネギ畑が広がっていました。形を変えながらも、常に歴史を作り続けてきた難波の歴史を紹介する作品です。' where id = '-9f39_Y4tx8_Wb1-rex5c';
update content_bodies set title = 'Namba HISTORY (Released in 2017)', description = 'Osaka has continuously blended various cultures throughout history, with Namba being its central hub. Once characterized by sprawling fields of green onions, Namba has transformed over time while consistently shaping its own history. This work introduces the rich historical narrative of Namba.' where id = 'DmaSxv187VD4F75ogb59U';
update content_bodies set title = '「ＮＡＮＫＡＩ鉄子の部屋」南海クイズ・ダイジェスト', description = '「南海愛」を自称する人々を対象にした「南海クイズ」が開催され、激レア賞品を争うイベントです。問題は、南海に対する深い愛情と豊富な知識を試すもので、初心者向けの簡単なものから、マニアックなものまで多岐にわたります。このイベントは2016年8月6日に開催され、鉄道アイドルの斉藤雪乃さんをゲストに迎え、鉄道好きの女性たちが参加しました。' where id = 'nnbh1-VMsQ5_PvL3bs-RJ';
update content_bodies set title = 'NANKAI Train Enthusiast Room: Nankai Quiz Digest', description = 'A rare prize competition, the ''Nankai Quiz'' is held for those who claim to love Nankai. The quiz features questions ranging from easy ones for casual fans to more obscure ones for die-hard enthusiasts, testing participants'' deep affection and extensive knowledge of Nankai. The event took place on August 6, 2016, and featured guest railway idol Yukino Saito, welcoming female train enthusiasts, known as ''Tetsuko.''' where id = 'a_HUGPdRAUaQTryER430H';
update content_bodies set title = '岐南イラストアート展', description = 'ぎふチャンの「めっちゃぎふわかるてれび」では、現在開催中の「岐南イラストアート展」を紹介しています。この展覧会は、令和7年3月1日から3月31日まで行われ、イラストレーター集団「岐阜新文化会」のメンバー15人が参加しています。作品は岐南町図書館、ホテルルートイン岐南、岐南町役場の3か所で展示されており、スタンプラリーも実施中です。すべての会場のスタンプを集めた方には、先着300名にイラストカード5枚セットがプレゼントされます。スタンプを集めた方は、岐南町役場または図書館で早めに引き換えをお願いします。このイベントは岐南町の提案型協働事業補助金を活用しています。' where id = 'OHtBkD3ymiyeFOuHQtKBH';
update content_bodies set title = 'Ginan Illustration Art Exhibition', description = 'The Gifu Channel''s program ''Meccha Gifu Wakaru Television'' introduces the ongoing ''Ginan Illustration Art Exhibition'' from March 1 to March 31, 2025. This exhibition features works from 15 members of the illustrator group ''Gifu New Cultural Association,'' organized by the ''Ginan Illustration Art Town Development Committee.'' The artworks are displayed at three locations: Ginan Town Library, Hotel Route Inn Ginan, and Ginan Town Hall. A stamp rally is also taking place, where participants can collect stamps from all three venues. Those who collect all stamps will receive a set of five illustration cards, limited to the first 300 participants. To redeem the cards, participants should visit Ginan Town Hall or the library promptly after collecting all stamps. This event is supported by a collaborative project subsidy from Ginan Town.' where id = 'ZMXFJ6cXnopO-EXBh9qCP';
update content_bodies set title = '第71回岐阜県消防操法大会　岐南町消防団5位入賞！', description = '令和4年8月7日、山県市伊自良総合グラウンドで「消防感謝祭」として第71回岐阜県消防操法大会が開催され、岐南町消防団が県内20の消防団の中で5位に入賞しました。小型ポンプ操法での入賞は24年ぶりの快挙です。この大会は消防団の技術向上と士気の高揚を目的としており、出場選手は約4カ月間の厳しい訓練を経て参加しました。出場しない団員も選手を支えるために共に訓練に参加しました。美しい規律と速さが際立ち、選手同士が抱き合う姿に感動を覚えました。岐南町消防団の活躍をぜひご覧ください。' where id = 'gHr-IeXXx-NvqA161DT9H';
update content_bodies set title = 'Ginan Town Fire Brigade Wins 5th Place at the 71st Gifu Prefecture Firefighting Skills Competition!', description = 'On August 7, 2022, the 71st Gifu Prefecture Firefighting Skills Competition was held at the Ijira General Ground in Yamagata City as part of the Firefighting Appreciation Festival. The Ginan Town Fire Brigade achieved an impressive 5th place among 20 fire brigades from across the prefecture. This marks the first time in 24 years that they have placed in the small pump operation category. The competition aims to enhance firefighting skills and boost morale among fire brigade members. Participants underwent rigorous training for about four months, with non-competing members also supporting the training efforts. The discipline and speed displayed during the competition were remarkable, and the emotional moment of team members embracing after completing their performance was truly moving. The Ginan Town Fire Brigade''s outstanding performance is worth celebrating.' where id = 'Dmcz_7ghSrK-ljFprUX4R';
update content_bodies set title = '【金沢・能登】観光プロモーション動画　- Farm to Table -', description = '石川県金沢市と能登半島の観光プロモーション動画が制作されました。旅のテーマは「Farm to Table」で、金沢・能登エリアの豊かな自然が育む食材がどのように生産され、消費者に届けられるのかを探ります。生産現場や伝統工芸の工房、料亭を訪れ、この地域のサステナブルな食文化や、そこで生きる人々の想いを知ることができます。ぜひ実際に訪れて、金沢・能登の魅力を体感してみてください。' where id = '_WZJ_ZTLj4sCJZFwklRh6';
update content_bodies set title = 'Kanazawa and Noto Tourism Promotion Video - Farm to Table -', description = 'A tourism promotion video has been produced for Kanazawa City and the Noto Peninsula in Ishikawa Prefecture. The theme of the journey is ''Farm to Table.'' The video explores how the rich ingredients, nurtured by the magnificent nature of the Kanazawa and Noto area, are produced and delivered to consumers. It features visits to production sites, traditional craft workshops, and restaurants, providing insights into the sustainable food culture of the region and the thoughts of the people living there. We encourage you to visit and experience the charm of Kanazawa and Noto firsthand.' where id = 'IgC3Ho0JglcIlwbLOr8gG';
update content_bodies set title = '鬼の住まう場所ー福知山・京都【大江町・観光PR動画】', description = '京都府福知山市の北部に位置する大江町は、古くから鬼の伝説が残る町として知られています。この動画では、大江町に残る鬼の痕跡を辿る旅を紹介します。鬼が住むとされる大江山や、地元の方々から聞いた文化や神話についても触れています。迫力あるモニュメントや美味しい食事、歴史ある伝統工芸など、魅力的なスポットがたくさんあり、神秘的な鬼伝説と地元の人々の温かい人情を体感できる町です。福知山市を訪れた際には、ぜひ大江町にも足を運んでみてください。' where id = 'QA6ktRacsEFH86xkRXfnU';
update content_bodies set title = 'The Home of Demons - Fukuchiyama, Kyoto | Oe Town Tourism PR Video', description = 'Oe Town, located in the northern part of Fukuchiyama City, Kyoto Prefecture, is known for its ancient legends of demons. In this video, we embark on a journey to trace the many remnants of these demons in Oe Town. We explore the legendary Oe Mountain, where it is said that demons still reside, and learn about the local culture and myths from the residents. The town offers impressive monuments, delicious food and sake, and traditional crafts, providing a rich experience of the mysterious demon legends and the warm hospitality of the locals. If you visit Fukuchiyama City, be sure to stop by Oe Town!' where id = 'R14jH5v7u8cnI5Q8AsrI9';
update content_bodies set title = '東北で大自然を満喫！【トレッキング】', description = '東北の三陸海岸一帯は「三陸復興国立公園」として、日本の国立公園に指定されています。この地域では大自然の中でトレッキングを楽しむことができ、新鮮な魚や地元のユニークな文化を満喫することができます。まだあまり知られていないエリアですが、自然や田舎が好きな方にはぜひ訪れてほしい場所です。' where id = 'JJekpmAtDsOMh8VWmcFHT';
update content_bodies set title = 'Enjoy the Great Outdoors in Tohoku! 【Trekking】', description = 'The Sanriku Coast area in Tohoku is designated as the ''Sanriku Reconstruction National Park,'' a national park in Japan. Here, you can enjoy trekking amidst stunning natural landscapes, as well as savor fresh fish and unique local culture. Although this area is still relatively unknown, it is a must-visit for those who love nature and rural settings!' where id = '2gdwv65ZNNEbretpU0MPd';
update content_bodies set title = '観光客のいない嵐山・京都：竹林散策と祇王寺 4K動画 by iPhone 11 Pro（2020年7月10日撮影）', description = 'この動画では、京都の代表的な観光名所である嵐山の美しい景色を紹介します。特に竹林が人気で、毎年多くの観光客が訪れますが、新型コロナウィルスの影響で観光が大幅に減少しました。緊急事態宣言が解除された6月以降も、多くの人が旅行を控え、観光地は大きな打撃を受けました。7月10日に撮影されたこの動画では、梅雨の時期で人がほとんどいない嵐山の静けさを捉えています。9月には旅行者が戻りつつありますが、今後このような静かな嵐山を撮影する機会は少ないかもしれません。コロナの早期終息と観光客の賑わいを願っています。' where id = 'X9F5w8mY2E0PulP6H2oN6';
update content_bodies set title = 'Arashiyama, Kyoto Without Tourists: Bamboo Grove Walk and Gio-ji Temple - 4K Video by iPhone 11 Pro (Filmed on July 10, 2020)', description = 'This video showcases the beautiful scenery of Arashiyama, a popular tourist destination in Kyoto, known for its bamboo grove. Due to the COVID-19 pandemic, tourism drastically declined after the state of emergency was declared in Japan from April to May. Even after the emergency was lifted in June, many people remained hesitant to travel, leading to a significant impact on tourist spots. The filming on July 10 occurred shortly after the emergency declaration was lifted and during the rainy season, resulting in a nearly deserted Arashiyama. As of September, with government campaigns encouraging travel, tourists are gradually returning. This video captures the rare tranquility of Arashiyama during this unique time, and the creator hopes for a swift end to the pandemic and a return to bustling tourism.' where id = '-yVZzDg_U6Z5c0Uo-g6Rt';
update content_bodies set title = '『FUKUI Style 東京番外編』', description = '福井市のイメージアップPR動画『FUKUI Style 美食美酒編』の公開を記念して、2024年11月29日（金）からLDH kitchen THE TOKYO HANEDAで『福いいネ！ランチフェア』が開催されます。このフェアでは、福井市食のPR大使である橘ケンチさん（EXILE／EXILE THE SECOND）と料理の達人澤本夏輝さん（FANTASTICS）が登場し、『越前おろしそばセット』と『福井名物ソースカツ丼セット』を味わいます。フェアは2024年11月29日（金）から12月13日（金）まで開催されるので、ぜひお立ち寄りください。また、PR動画は11月29日（金）に公開され、EXILEやFANTASTICSのコンサート情報もあります。' where id = 'i_gkdQ8U0t2N0eXCL95d6';
update content_bodies set title = 'FUKUI Style Tokyo Special Edition', description = 'This is a promotional video for Fukui City, celebrating the release of ''FUKUI Style Gourmet and Sake Edition.'' Starting from November 29, 2024, the ''Fukui Good Lunch Fair'' will take place at LDH kitchen THE TOKYO HANEDA. The fair features Fukui City’s food PR ambassador Kenchi Tachibana (EXILE/EXILE THE SECOND) and renowned chef Natsuki Sawamoto (FANTASTICS), who will enjoy the ''Echizen Oroshi Soba Set'' and ''Fukui Specialty Sauce Katsu Don Set.'' The fair runs from November 29 to December 13, 2024, and visitors are encouraged to stop by and enjoy the offerings. Additional information includes the release of the promotional video on November 29, 2024, and upcoming concerts by EXILE and FANTASTICS.' where id = 'xiw8I48uOSWA40XlH47MG';
update content_bodies set title = 'BEHIND THE STORY OF #4 NEMURO', description = '#4 NEMUROは、北海道根室市の観光PR動画です。「BEHIND THE STORY OF」シリーズでは、制作したディレクターや制作チームの想いや裏話を紹介しています。この動画には、プロデューサー兼編集者の岡内翔、ディレクターの須田桃香、ドローンオペレーターの大場昇、モデルの岩本美咲など、さまざまなメンバーが参加しています。このプロジェクトは、北海道179市町村の魅力を伝えることを目的としたKAI北海道ムービーメディアの一環で、観光PR映像や地域ドキュメンタリー、まちづくりPR映像など多様な表現方法を用いています。EzoExplorerプロジェクトは、地域のクリエイターの視点から北海道の魅力を発信することに焦点を当てています。' where id = 'YICcd2DPpv5HqgZeJpozs';
update content_bodies set title = 'BEHIND THE STORY OF #4 NEMURO', description = '#4 NEMURO is a promotional video for tourism in Nemuro City, Hokkaido. The series ''BEHIND THE STORY OF'' shares insights and behind-the-scenes stories from the director and production team. The video features various contributors, including producer and editor Shogo Okauchi, director Momoka Suda, drone operator Noboru Oba, and model Misaki Iwamoto. The project is part of KAI Hokkaido Movie Media, which aims to showcase the charm of all 179 municipalities in Hokkaido through diverse visual media, including tourism promotion, regional documentaries, and community development videos. The EzoExplorer project focuses on highlighting the attractions of Hokkaido''s regions through the lens of local creators.' where id = 'Hz8mLgA2_ZZkPzciLChni';
update content_bodies set title = '#4 NEMURO / 北海道根室市観光PR動画 / さんま祭り', description = '#4 NEMUROは、北海道根室市の魅力を紹介する動画です。制作・編集は岡内翔吾、監督は須田桃香が担当しています。Bカメラとドローンオペレーターは大庭昇、モデルは岩本美咲です。制作チームのKAIは、観光PR映像や地域ドキュメンタリー、まちづくりPR映像などを通じて、北海道179市町村の魅力を発信しています。プロジェクト「EzoExplorer」は、観光、文化、地域活性化など多様な視点から各地の魅力を伝えることを目的としています。音楽はArtlistから提供されています。制作依頼はezo.explorer@gmail.comまで。' where id = 'P-ZnfNseMn6iSqiWzP0Ro';
update content_bodies set title = '#4 NEMURO / Hokkaido Nemuro City Tourism PR Video / Sanma Festival', description = '#4 NEMURO showcases the beauty of Nemuro City in Hokkaido, Japan. The video is produced and edited by Shogo Okauchi, with direction by Momoka Suda. The team includes Noboru Oba as the B Cam and drone operator, and model Misaki Iwamoto. KAI, the production team, focuses on promoting the attractions of Hokkaido''s 179 municipalities through various forms of media, including tourism PR videos, regional documentaries, and community development films. The EzoExplorer project aims to highlight the unique aspects of each area, covering tourism, culture, and local initiatives. The music used in the video is sourced from Artlist. For production inquiries, contact ezo.explorer@gmail.com.' where id = 'L72xLyjTecCY1Ayp--H7U';
update content_bodies set title = 'BEHIND THE STORY OF #2 YAKUMO', description = '#2 YAKUMOは、北海道八雲町の観光PR動画で、ディレクターの佐々木亮が制作を担当しています。「BEHIND THE STORY OF」シリーズでは、制作の裏話や想いを紹介しています。この動画には、熊友工房の小熊秀夫さんが出演し、共演者には大和宏志さん、井上望さん、永井雅人さんがいます。プロデューサーは岡内翔吾さんで、ディレクター兼編集者は佐々木亮さんです。地元の企業や団体の協力も得て制作されています。KAI北海道ムービーメディアは、観光PR映像や文化ドキュメンタリーなど多様な表現を通じて、北海道179市町村の魅力を伝えることを目指しています。プロジェクト「EzoExplorer」は、各地域の独自の魅力を強調することに焦点を当てています。' where id = 'XI3SRnSwc6Li-YSUzpZvW';
update content_bodies set title = 'BEHIND THE STORY OF #2 YAKUMO', description = '#2 YAKUMO is a promotional video for Yakumo Town in Hokkaido, directed by Ryo Sasaki. The series ''BEHIND THE STORY OF'' shares insights and behind-the-scenes stories from the director. The video features Hideo Koguma from Kumamoto Workshop, along with co-stars Hiroshi Yamato, Nozomi Inoue, and Masato Nagai. The production team includes producer Shogo Okauchi and director/editor Ryo Sasaki, with contributions from various local businesses and organizations. KAI Hokkaido Movie Media aims to showcase the charm of all 179 municipalities in Hokkaido through diverse video expressions, including tourism promotion and cultural documentaries. The project, EzoExplorer, focuses on highlighting the unique aspects of each area, supported by local creators.' where id = 'IkrJb728qN5fPTcXSzPqG';
update content_bodies set title = '#2 YAKUMO / 北海道八雲町観光PR動画 / 木彫り熊', description = '#2 YAKUMOは、北海道八雲町の魅力を紹介する動画で、熊友工房の木彫り熊・小熊秀夫さんが主演し、山本宏、井上望、永井雅人が共演しています。制作は岡内翔吾、監督は佐々木亮が担当し、地域の文化や観光名所を強調しています。特別協力として、地元のカフェや工房、資料館などが紹介され、八雲町の独自のアイデンティティに寄与しています。このプロジェクトは、KAI北海道ムービーメディアの一環で、北海道179市町村の魅力を観光、文化、地域振興の視点から多様な映像表現で発信しています。音楽はArtlistから提供されています。制作依頼はメールで受け付けています。' where id = 'l_jzJpwQxhDaaTPUq9bxp';
update content_bodies set title = '#2 YAKUMO / Hokkaido Yakumo Town Tourism PR Video / Wood Carving Bear', description = '#2 YAKUMO showcases the charm of Yakumo Town in Hokkaido, featuring Hideo Koguma from Kumamoto Workshop and co-stars Hiroshi Yamato, Nozomi Inoue, and Masato Nagai. The video is produced by Shogo Okauchi and directed by Ryo Sasaki, highlighting the local culture and attractions. Special thanks are given to various local businesses and institutions, including cafes, workshops, and museums that contribute to the town''s unique identity. The project is part of KAI Hokkaido Movie Media''s initiative to promote all 179 municipalities in Hokkaido through diverse visual storytelling, focusing on tourism, culture, and community development. Music is sourced from Artlist. For production inquiries, contact via email.' where id = 'Zen-ZWY9ju9WguwqWqMfU';
update content_bodies set title = '#1 HAKODATE / 北海道函館市観光PR動画 / 五稜郭 桜', description = 'この動画は、北海道函館市の美しさを紹介し、特に五稜郭とその桜に焦点を当てています。制作・監督は岡内翔吾氏、ドローン操作は鳥谷雅樹氏が担当しています。このプロジェクトは、北海道179市町村の魅力を発信するKAI北海道ムービーメディアの一環です。KAIは観光PR映像や地域PR映像、人物や文化に関するドキュメンタリー、まちづくりPR映像など多様な映像コンテンツを制作しています。EzoExplorerプロジェクトは、地元のクリエイターの視点から北海道の各地域の魅力を伝えることを目的としています。音楽はArtlistから提供されています。制作依頼はezo.explorer@gmail.comまで。' where id = 'LBbU7JrASJmeOvnqBExGm';
update content_bodies set title = '#1 HAKODATE / Hokkaido Hakodate City Tourism PR Video / Goryokaku Cherry Blossoms', description = 'This video showcases the beauty of Hakodate, Hokkaido, focusing on the iconic Goryokaku and its cherry blossoms. Produced and directed by Shogo Okauchi, with drone operations by Masaki Toriya, the project is part of KAI Hokkaido Movie Media''s initiative to promote the attractions of all 179 municipalities in Hokkaido. KAI creates various types of visual content, including tourism and regional PR videos, documentaries on people and culture, and town development promotions. The EzoExplorer project aims to highlight the charm of Hokkaido''s diverse regions through the lens of local creators. Music for the video is sourced from Artlist. For production inquiries, contact ezo.explorer@gmail.com.' where id = 'kOSkQ_Af9UkDY0cl-A2rX';
update content_bodies set title = '星空保護区に認定された奇跡の星空', description = 'ここにしかない沖縄の楽園、''はいむるぶし''は南十字星にちなんだリゾートで、八重山諸島の小浜島に位置しています。沖縄本島から400km南にあり、国内最大のサンゴ礁と西表石垣国立公園に囲まれたこのアイランドリゾートは、自然愛好者や星空観賞者にとって完璧な休日を提供します。' where id = 'sqpqCUCgCPCM4-kk1_5oy';
update content_bodies set title = 'Miraculous Starry Sky Designated as a Starry Sky Protection Area', description = 'Okinawa is home to a unique paradise. ''Haimurubushi'' is a resort named after the Southern Cross, located on Kohama Island in the Yaeyama Islands, 400 km south of Okinawa''s main island. This island resort is nestled within Japan''s largest coral reef and the Iriomote-Ishigaki National Park, offering a perfect getaway for nature lovers and stargazers.' where id = 'xT14MoaXgiyG130hoGVf7';
update content_bodies set title = '【かごしまサイクルツーリズム】ダイナミックな自然、豊かなグルメを楽しむ！大隅（おおすみ）ルートver2', description = '垂水港を拠点にした大隅ルートは、壮大な8の字の周遊コースです。大隅半島は豊かな自然に恵まれ、農業や漁業、畜産などの第一次産業が盛んな地域です。地域資源を活用した体験や学習コンテンツがあり、近海の鮮魚や黒毛和牛など、地元ならではのグルメも楽しめます。緑深い高隈連山を背景に広がる大平原は、ダイナミックな自然の魅力を感じさせるエリアです。' where id = '8BpO3LcnPYIRwyu0Y7W5P';
update content_bodies set title = 'Kagoshima Cycle Tourism: Enjoy Dynamic Nature and Rich Gourmet! Osumi Route ver2', description = 'The Osumi Route is a grand loop centered around Tarumizu Port. The Osumi Peninsula is blessed with rich nature and is an active region for primary industries such as agriculture, fishing, and livestock. It offers experiences and learning content utilizing local resources, along with gourmet food unique to the area, including fresh seafood and black wagyu beef. The area is characterized by its dynamic landscapes, with lush Takakuma Mountains in the background and expansive plains.' where id = '-EeQx33v5h9AsBtyWB22y';
update content_bodies set title = '【かごしまサイクルツーリズム】日本の原風景を走る！北薩ルートをサイクリング！', description = '熊本県との県境に位置する北薩は、懐かしい里山の風景や風光明媚な温泉が楽しめる場所です。白い砂浜が続く美しい海岸線では、東シナ海に沈むオレンジ色の夕日に癒されます。また、海の幸や山の幸が豊かな北薩地域のご当地グルメも楽しみの一つです。' where id = 'DlQtMH_RmQAF8i94rgKkh';
update content_bodies set title = 'Kagoshima Cycle Tourism: Cycling Through Japan''s Scenic Landscapes on the North Satsuma Route!', description = 'Located at the border with Kumamoto Prefecture, North Satsuma offers nostalgic rural landscapes and beautiful hot springs. The stunning coastline, with its white sandy beaches, provides a soothing view of the orange sunset over the East China Sea. Additionally, visitors can enjoy the local gourmet cuisine, rich in both seafood and mountain delicacies, making it a delightful experience for cyclists.' where id = 'lclaTZySOtwSB9QPPtiEz';
update content_bodies set title = '【かごしまサイクルツーリズム】薩摩藩が誇る武家の歴史と絢爛な文化が薫る街並みを走る！南薩ルート', description = '「サイクリングターミナルりんりん」を起点とするこのルートでは、南さつま市、日置市、鹿児島市、指宿市、南九州市、枕崎市の各地の特徴的な風景を楽しむことができます。リアス式海岸線を背景にした東シナ海の美しい夕日や、桜島、開聞岳がそびえる錦江湾の景色は特に素晴らしいです。また、武家屋敷群や薩摩焼の窯元、焼酎の酒蔵、鰹本枯れ節の工場など、魅力的なスポットが点在しています。' where id = 'GS8Qw8FNTAaRr51dRWva2';
update content_bodies set title = 'Kagoshima Cycle Tourism: Ride Through the Historic Streets of the Satsuma Clan', description = 'This cycling route starts and ends at the ''Cycling Terminal Rinrin'' and takes you through the scenic areas of Minamisatsuma City, Hioki City, Kagoshima City, Ibusuki City, Minamikyushu City, and Makurazaki City. Cyclists can enjoy the beautiful landscapes, including the stunning sunset over the East China Sea with its ria coastline, as well as the majestic views of Sakurajima and Kaimondake mountains overlooking Kinko Bay. The area is rich in attractions, featuring samurai residences, Satsuma pottery kilns, shochu distilleries, and katsuobushi (dried bonito) factories.' where id = '7AKvZmr3FkwEAKFteGOGJ';
update content_bodies set title = '【かごしまサイクルツーリズム】ダイナミックな自然、豊かなグルメを楽しむ！大隅（おおすみ）ルート', description = '垂水港を拠点にした大隅ルートは、壮大な8の字の周遊コースです。大隅半島は豊かな自然に恵まれ、農業や漁業、畜産などの第一次産業が盛んな地域です。地域資源を活用した体験や学習コンテンツに加え、近海の鮮魚や黒毛和牛など、地元ならではのグルメも楽しめます。緑深い高隈連山を背景に広がる大平原は、ダイナミックな自然が魅力のエリアです。' where id = 'TeZj7ZAq1Esq1IfglLhPT';
update content_bodies set title = 'Kagoshima Cycle Tourism: Enjoy Dynamic Nature and Rich Gourmet! Osumi Route', description = 'The Osumi Route is a grand loop centered around Tarumizu Port. The Osumi Peninsula is blessed with abundant nature and is an active region for primary industries such as agriculture, fishing, and livestock farming. In addition to experiences and learning content utilizing local resources, the area offers gourmet delights, including fresh seafood from nearby waters and black wagyu beef, characteristic of the region. Surrounded by the lush Takakuma Mountains, this area is rich in nature and aptly described as dynamic.' where id = 'ttHK_7Wtqk7QQSZmz8sr-';
update content_bodies set title = '【かごしまサイクルツーリズム】霧島連山から豊かに流れ出す川沿いの風景を楽しむ！川内川流域ルート', description = '吉松駅をスタート地点とし、川内川沿いに高速船ターミナル（川内港）へ向かうサイクリングルートです。途中、湧水池や「東洋のナイアガラ」と称される迫力ある曽木の滝、夏の風物詩であるほたるなど、さまざまな見どころがあります。霧島山系の豊かな水に支えられた稲穂の田園風景や、銘茶を生産する茶畑が広がり、河口までの川沿いの景色を楽しむことができます。' where id = '6fl-JwWHpIwIpWIonmvaT';
update content_bodies set title = 'Kagoshima Cycle Tourism: Enjoy the Scenic Views Along the Sendai River Basin Route!', description = 'Starting from Yoshimatsu Station, this cycling route leads along the Sendai River to the high-speed boat terminal at Sendai Port. Cyclists can enjoy various attractions, including bubbling spring water pools, the dynamic Sogi Falls, known as the ''Niagara of the East,'' and the summer spectacle of fireflies. The route continues along the river to the estuary that connects to the East China Sea, showcasing the rich rice fields supported by the abundant waters of the Kirishima mountain range and the picturesque tea plantations.' where id = 'sy3l5PQsdctNehk6ak_Tc';
update content_bodies set title = '【かごしまサイクルツーリズム】歴史ロマンあふれる！甑島ルート', description = '上甑島・中甑島・下甑島といちき串木野市を周遊するルートで、サイクリングの醍醐味である橋を渡る爽快感を存分に味わえます。甑島の断崖には8000年前の地層が残り、薩摩の武士が生きた町「麓」の武家屋敷群や、日本の近代化に貢献した薩摩スチューデントに学ぶ「薩摩藩英国留学生記念館」など、歴史ロマンあふれるスポットが点在しています。ぜひこの旅を楽しんでください。' where id = 'TlDJE481H_5vRZMPosmG9';
update content_bodies set title = 'Kagoshima Cycle Tourism: A Romantic Journey Through History on the Koshikijima Route', description = 'The Koshikijima route offers a cycling experience around Upper, Middle, and Lower Koshikijima Islands and Ichiki-Kushikino City. Cyclists can enjoy the exhilarating feeling of crossing bridges. The route features stunning cliffs with geological layers dating back 8,000 years, and historical sites such as the samurai town of ''Fumoto'' with its traditional samurai residences, recognized as a Japanese heritage site. Additionally, visitors can learn about the Satsuma Students who contributed to Japan''s modernization at the Satsuma Domain British Student Memorial Museum. This journey is rich in historical romance.' where id = '5wHBcLBvVDApbDLjcAfDk';
update content_bodies set title = '世界トップバーテンダーが語る本格焼酎', description = 'この動画では、世界のトップバーテンダーの視点から、鹿児島・宮崎県産の本格焼酎の魅力や、焼酎を使ったカクテルを紹介しています。焼酎の独自の風味や、カクテルとしての楽しみ方が語られ、視聴者に新たな飲み方を提案しています。' where id = 'AzLd2fGnpu7kpi0c8crnI';
update content_bodies set title = 'World''s Top Bartenders Discuss Authentic Shochu', description = 'This video showcases the appeal of authentic shochu produced in Kagoshima and Miyazaki Prefectures from the perspective of world-class bartenders. It also introduces various shochu cocktails.' where id = 'dgjEeYMaERmpR6BHveWZ4';
update content_bodies set title = '世界トップバーテンダーが語る本格焼酎', description = 'この動画では、世界トップバーテンダーの視点から、鹿児島県産の本格焼酎の魅力や焼酎を使ったカクテルを紹介しています。焼酎の特性やその楽しみ方について、専門的な知識を持つバーテンダーが解説し、視聴者に新たな飲み方を提案します。' where id = '96tClTLYQusySb9bLOwCp';
update content_bodies set title = 'World''s Top Bartender Talks About Authentic Shochu', description = 'This video introduces the appeal of authentic shochu produced in Kagoshima Prefecture from the perspective of a world-class bartender, along with shochu cocktails.' where id = '2BDaIZAmTc1dxAbKEJi5p';
update content_bodies set title = '温泉編【どんどん癒されたくなる　かごしまの温泉】', description = '鹿児島県には100以上の温泉地があり、2700カ所以上の源泉を有し、全国で2位の温泉王国です。1日に2億2,500万リットル以上の温泉が湧出し、世界的に珍しい砂むし温泉もあります。県内各地には魅力的な温泉が点在し、様々な泉質を楽しむことができます。動画では、鹿児島出身のスポーツキャスターで薩摩大使の宮下純一氏が霧島温泉郷で癒される様子が描かれ、鹿児島の温泉の魅力が伝えられています。鹿児島の温泉で心と身体をリフレッシュしましょう。' where id = 'SuRvf84jSHwsoeL5X0MFZ';
update content_bodies set title = 'Kagoshima''s Hot Springs: A Place to Relax', description = 'Kagoshima Prefecture boasts over 100 hot spring areas and ranks second in Japan with more than 2,700 hot spring sources. It produces over 225 million liters of hot spring water daily, making it one of the top hot spring regions in the country. Among its unique offerings is the rare sand bath hot spring, along with a variety of attractive hot springs throughout the prefecture, allowing visitors to enjoy different types of mineral waters. The video features Junichi Miyashita, a sports caster from Kagoshima and Satsuma ambassador, as he experiences the healing effects of the Kirishima hot spring area, showcasing the allure of Kagoshima''s hot springs. Take time to relax in Kagoshima''s hot springs for both mental and physical well-being.' where id = 'st9v_Y1tU_q5q2kqw90Ep';
update content_bodies set title = '長洲神社葵祭り', description = '長洲葵祭りは、毎年5月3日から5日まで行われる長洲地区加茂神社のお祭りで、山の幸と海の幸を祝う祭りです。祭りの期間中、コンコンチキリン♪の太鼓や笛の音に合わせて、山車が長洲の町を練り歩きます。この祭りの起源は、宝暦11年（1761年）に豊前の国で疫病が発生し、それを鎮めるために踊車として山車が奉納されたことにあります。全盛期には7基の山車が存在しましたが、現在は近年復活した「大西車組」と江戸時代からの伝統を受け継ぐ「上町車組」の2基が山車を引き回し、無病息災や五穀豊穣を願っています。' where id = 'I4c0HsRz4-9Jx2QAQ4BbS';
update content_bodies set title = 'Nagasu Shrine Aoi Festival', description = 'The Nagasu Aoi Festival is held annually from May 3rd to 5th at the Kamo Shrine in the Nagasu area, celebrating both mountain and sea blessings. During the festival, floats parade through the town of Nagasu, accompanied by the sounds of drums and flutes. The festival originated in 1761 when an epidemic struck Buzen Province, prompting the offering of a dance float to quell the disease. At its peak, there were seven floats, but currently, two floats are paraded: the ''Onishi Float Group,'' which was recently revived, and the ''Uemachi Float Group,'' which carries on traditions from the Edo period, both wishing for good health and bountiful harvests.' where id = 'A89B3hsiJvtLDQyMgRdJJ';
update content_bodies set title = 'よっかいち「ひな祭り」', description = 'よっかいちのひな祭りは、桜岡神社での神事から始まります。その後、市内の園児によるパレードが行われ、子どもたちがひな人形に扮して訪れた人々を楽しませます。さらに、餅まきやカレー、お餅の販売も行われ、期間中は四日市商店街や桜岡神社でひな人形が飾られます。' where id = 'hh39SlsqeFACW-IqPu5Ik';
update content_bodies set title = 'Yokkaichi Hina Matsuri', description = 'The Yokkaichi Hina Matsuri begins with a ceremonial event at Sakuraka Shrine, followed by a parade featuring local preschool children. The children dress as traditional hina dolls, delighting visitors with their charming appearances. Additionally, there will be a mochi throwing event, and food stalls selling curry and rice cakes. Throughout the festival period, hina dolls will be displayed around the Yokkaichi shopping district and Sakuraka Shrine.' where id = '4UUNqB8dfCiUUgxB9THba';
update content_bodies set title = 'カチがあるまち宇佐「宇佐御勝印」完成までの手順', description = '宇佐市は、不滅の69連勝を成し遂げた昭和の大横綱双葉山や、全国4万社余りある八幡社の総本宮宇佐神宮がある「勝ちがあるまち」です。昨年度は、コロナ禍でも勝利のために一生懸命努力した学生たちの青春に寄り添い「一勝に賭けた青春」プロジェクトを実行し、今年の夏にはオリンピック・パラリンピック選手への必勝祈願をメッセージカードにして届けました。現在、宇佐に来て身近な人の必勝祈願をし「御勝印」を完成させることが奨励されています。完成には双葉の里と観光協会の2ヵ所を巡る必要があり、期間は令和3年10月1日から令和4年2月28日までです。さらに、69名に5,000円相当のプレゼントが当たるキャンペーンも実施中で、完成した「宇佐御勝印」を提示し応募券をもらい、SNSに投稿することで応募口数が増えるチャンスもあります。' where id = 'dFgBsV0nYrWy8m_gtF0sD';
update content_bodies set title = 'Steps to Complete the Usa Gokatsu Stamp in the Winning Town of Usa', description = 'Usa City, known as the ''town of victory,'' is home to the legendary sumo wrestler Futabayama, who achieved an unprecedented 69 consecutive wins, and the Usa Shrine, the head shrine of over 40,000 Hachiman shrines nationwide. Last year, despite the challenges posed by the COVID-19 pandemic, the city supported students'' aspirations through the ''Youth Betting on a Win'' project, delivering message cards for victory prayers to Olympic and Paralympic athletes this summer. Now, residents and visitors are encouraged to come to Usa and offer prayers for their loved ones'' victories by completing the ''Usa Gokatsu Stamp.'' To complete the stamp, participants will visit two locations: Futaba no Sato and the Usa Tourism Association. The event runs from October 1, 2021, to February 28, 2022, and includes a limited-time campaign where 69 participants can win prizes worth 5,000 yen. To enter, participants must show their completed stamp to staff and submit an application form. Additionally, posting on social media with specific hashtags can double their chances of winning.' where id = 'HnEqXg_hfV21-j9Mkq47I';
update content_bodies set title = '宇佐麦秋観光誘客プロジェクト成功祈願　ダンス動画（OAB「れじゃぐる」抜粋）', description = '令和6年2月24日に、宇佐麦秋観光誘客プロジェクトの成功を祈願するイベントが開催され、EXILE ÜSAさんが地元のダンスチームと共に「麦踏みダンス」をOABの番組「れじゃぐる」で披露しました。このパフォーマンスでは、楽しく心弾むような動きが見られ、観客を楽しませる内容となっています。' where id = 'pRsG-X2uAYVnq4UgHF05P';
update content_bodies set title = 'Success Prayer for Usamugi Autumn Tourism Project - Dance Video (Excerpt from OAB ''Rejaguru'')', description = 'On February 24, 2024, a prayer for the success of the Usamugi Autumn Tourism Project was held, featuring EXILE ÜSA performing the ''Mugi Fumi Dance'' alongside a local dance team on OAB''s program ''Rejaguru.'' Enjoy the lively and cheerful movements showcased in the performance.' where id = 'vGHUeoFbfOL4YNvp93oTO';
update content_bodies set title = '旅する宇佐 宇佐神宮＆飲食巡り編', description = '今回、モデルコースのPR動画を作成しました。観光や飲食など、魅力が溢れる宇佐市を訪れてみてはいかがでしょうか。市に関する詳しい情報は、こちらのリンクからご確認いただけます。' where id = 'KWRnBzF65lj8BwoQ3LfIA';
update content_bodies set title = 'Traveling Usa: Usa Jingu and Food Tour', description = 'This time, we have created a promotional video for a model course. Why not visit Usa City, which is full of attractions such as sightseeing and dining? For more detailed information about the city, please check here: https://www.city.usa.oita.jp/tourist/index.html' where id = 'PLjAYEbcCHX5Eil58rikF';
update content_bodies set title = '旅する宇佐 サイクリング編', description = '宇佐市ではレンタサイクルが利用でき、市内の街並みや風情を自転車で楽しむことができます。サイクリングを通じて、宇佐の魅力を体感することができるため、観光客にとって魅力的なアクティビティです。詳しい情報は、公式サイトで確認できます。' where id = 'kQcRZa3AyUHnxq9nJUmx_';
update content_bodies set title = 'Cycling in Usa', description = 'Usa City offers rental bicycles, allowing visitors to enjoy the city''s streets and atmosphere while cycling. For more details, please check the link.' where id = 'olt2hZHiWQ4vjAR4poSFG';
update content_bodies set title = '宇佐市観光アンバサダー自己紹介動画', description = '昨年の秋から活動を開始した5名の観光アンバサダーによる自己紹介動画です。彼らはイベントやメディアへの出演を通じて、宇佐市の魅力を全国に発信していきますので、どうぞよろしくお願いいたします。' where id = 'Hh0twNm1M5KZXgNO7C94k';
update content_bodies set title = 'Usa City Tourism Ambassador Introduction Video', description = 'This is an introduction video featuring five tourism ambassadors who began their activities last autumn. They will promote the charm of Usa City nationwide through appearances at events and various media. We appreciate your support.' where id = '3PZ96QsnHdFNJqCeB28JE';
update content_bodies set title = '宇佐高生制作動画「宇佐の偉人 南一郎平って？？？」', description = '宇佐高等学校では、総合的な探求の時間において、創造力を生かした課題解決手法「デザインシンキング」を学んでいます。その一環として、宇佐市や宇佐高等学校の魅力を伝えるショート動画を制作しました。動画の中には南一郎平に関するものもあり、NHK朝ドラ「南一郎平」誘致推進協議会から資料を受け取り、宇佐の歴史を学びながら制作が行われました。とても楽しい動画に仕上がっていますので、ぜひご覧ください。' where id = 'Q_DlCWuWdkVJ72xg6yhq1';
update content_bodies set title = 'Usa High School Video Production: Who is Ichirohei Minami?', description = 'At Usa High School, students are learning about ''design thinking,'' a method for problem-solving that emphasizes creativity, during their comprehensive inquiry time. As part of this initiative, they have created short videos to showcase the attractions of Usa City and Usa High School. Among these videos is one focused on Ichirohei Minami, for which they received materials from the NHK morning drama promotion committee. The students learned about the history of Usa while producing the video, resulting in a very enjoyable final product. Be sure to check it out!' where id = '7gDhzuvOAkNP4VaAwcAXC';
update content_bodies set title = '宇佐神宮ユニバーサルツーリズム動画', description = '宇佐市では、高齢者や障害者を問わず、誰もが気軽に安心して観光を楽しめる「ユニバーサルツーリズム」の推進に取り組んでいます。今回、ＮＰＯ法人自立支援センターおおいたと連携し、宇佐神宮御鎮座1300年観光振興プロジェクトの一環として、車いすなどを利用して参拝する際のコースや観光ポイントをまとめた動画を作成しました。' where id = 'TJmJZstnC-LVP2hToJ3fb';
update content_bodies set title = 'Universal Tourism Video of Usa Jingu', description = 'Usa City is promoting ''Universal Tourism'' to ensure that everyone, regardless of age or disability, can enjoy sightseeing comfortably and without hesitation. In collaboration with the NPO Oita Support Center, a video has been created as part of the Usa Jingu 1300th Anniversary Tourism Promotion Project. This video summarizes the routes and sightseeing points for visitors who use wheelchairs or have other mobility needs.' where id = '8_2lhLr4tC7vwHzzP9Nul';
update content_bodies set title = '白浜温泉 献湯祭＜お湯の恵みに感謝する＞', description = '献湯祭は、町内の源泉を持つ温泉会社8社と観光関係者が、朝一番にくみ上げた「一番湯」を入れた樽を担いで温泉街を練り歩き、山神社に移動する祭りです。神社では、巫女から神職へと水を手渡し、奉納する神事が行われます。令和6年度の第38回献湯祭では、奈良時代の衣装を着た参加者が白浜温泉街から山神社まで行列します。祭りの最後には和歌山名物の「餅まき」もあり、地域の文化を深く理解し、地元の人々とのつながりを感じる素晴らしい機会となります。' where id = 'ieWCgKNLQzDBuL7E2to34';
update content_bodies set title = 'Shirahama Onsen Kentyusai: A Festival of Gratitude for Hot Springs', description = 'The Kentyusai festival involves eight local hot spring companies and tourism officials carrying barrels filled with the first hot spring water of the day through the hot spring town to the Yama Shrine. At the shrine, a ceremonial offering is made, where the water is passed from a shrine maiden to the priests. In the 38th Kentyusai festival of 2024, participants will wear costumes from the Nara period as they walk from Shirahama Onsen to the Yama Shrine. The event concludes with a traditional ''mochi-maki'' (rice cake throwing), providing a wonderful opportunity to engage with local culture and connect with the community.' where id = 'EOU8SIMm36KEdVUUjTGlo';
update content_bodies set title = '2024年6月14日', description = '中国に行く前に知っておくべきことは、Googleやラインなど普段使っているサービスが利用できないということです。規制を知らないと、現地に着いて何もできなくなる可能性があります。そんな時に役立つのがVPNですが、特に優れた選択肢はVPN付きのeSIMです。これを使えば、いつも通りインターネットが利用でき、データも無制限で使えます。私が使用したのはHolaflyというeSIMで、非常に便利でした。興味がある方のためにクーポンコード「shumpei-trip」もあります。' where id = '-hGEO9FjjBCYGfzKSFRDf';
update content_bodies set title = 'June 14, 2024', description = 'Before traveling to China, it''s crucial to know that popular services like Google and Line are not accessible due to regulations. Without this knowledge, you may find yourself unable to do anything upon arrival. A solution to this issue is using a VPN, and the best option is a VPN-enabled eSIM. This allows you to access the internet as usual with unlimited data. I used Holafly eSIM, which worked perfectly for my needs. There''s also a coupon code available for those interested: ''shumpei-trip''.' where id = 'Ok5tw9J-luXs1ytuqw9OC';
update content_bodies set title = '静岡県浜松市 プロモーション動画', description = 'このプロモーション動画は、浜松市の魅力を1分半で紹介しています。1ヶ月間のプロジェクトを通じて、自然が豊かで人々が温かい浜松の素晴らしさを再確認しました。制作者は、日本の美しさをもっと知り、世界に伝えたいという気持ちが強くなり、7月から2、3ヶ月かけて自転車で日本を縦断する計画を立てています。この旅を通じて、他の人々に挑戦する勇気を与えたいと考えています。「後悔のない生き方」を大切にし、クラウドファンディングにも挑戦する予定です。動画をシェアし、コメントやアドバイスを待っているとのことです。' where id = 'gBElO_LUKtGUlapXD7ywQ';
update content_bodies set title = 'Hamamatsucity Promotion Video', description = 'This promotion video showcases the charm of Hamamatsu City in just one and a half minutes. The project, which lasted a month, highlighted the beauty of Hamamatsu, a city known for its natural surroundings and warm people, making it a great place to live. The creator expresses a newfound desire to explore Japan''s beauty and share it with the world, planning to cycle across Japan for two to three months starting in July. Through this journey, they aim to inspire others to take on challenges, emphasizing the importance of living without regrets. A crowdfunding campaign is also planned for June to support this endeavor. The creator encourages viewers to share the video and engage with comments and advice, expressing gratitude for their support.' where id = '8aDgrjFWVeT2YC_WoGcmB';
update content_bodies set title = '【福岡Vlog】バックパッカーの旅開始！いきなり徒歩で日本縦断中の人に出会った！', description = 'こんにちは、河合舜平です！バックパッカーの旅の日常をシネマティックに発信しています。チャンネル登録していただけると嬉しいです！最初の旅は福岡から始まり、福岡に向かう過程や、2日目にゲストハウスで仲良くなった人たちとのんびり過ごす様子を収めた動画です。うすくさんのTwitterや私のInstagramもぜひチェックしてください。メインカメラはa6600を使用し、Adobe Premiere Proで編集しています。音楽はArtlistからのもので、Fassoundsの「Hold Me」やFine Linesの「New Years Eve」が含まれています。' where id = 'GJk09821aUZCu94qwLb5i';
update content_bodies set title = 'Fukuoka Vlog: Backpacker''s Journey Begins! Encounter with a Person Walking Across Japan!', description = 'Hello, I''m Shunpei Kawai! I share my daily life as a backpacker in a cinematic style. Please consider subscribing to my channel! My first journey starts in Fukuoka. This video captures my journey to Fukuoka and my relaxing time with new friends I met at a guesthouse on the second day. You can find more about us on Twitter and Instagram. The main camera used is the a6600, and the video is edited with Adobe Premiere Pro. Music is sourced from Artlist, featuring tracks like ''Hold Me'' by Fassounds and ''New Years Eve'' by Fine Lines.' where id = 'LTDSl60EFc3c038Y727mT';
update content_bodies set title = 'SHIKOKU‐四国のクールスポット‐（キーーーンと四国！しこくーる）', description = '四国には、涼しさを感じられるクールスポットが数多く存在します。これらのスポットを巡ることで、涼しく快適に四国を楽しむことができます。香川県の妖怪美術館や時の納屋、かき氷カフェひむろと父母ヶ浜、徳島県の穴吹川や黒沢湿原、童学寺のまけまけ風鈴祭り、高知県の伊尾木洞窟や三樽権現の滝、愛媛県の観音水と名水亭のそうめん流し、御禊の滝打たれ（紅葉ヶ滝）、UFOライン、石鎚山ロープウェイなど、訪れるべきおすすめスポットが紹介されています。' where id = 'hC3J58Th73fxaTh0chYdb';
update content_bodies set title = 'Cool Spots in Shikoku', description = 'Explore the cool spots in Shikoku and enjoy a refreshing experience! Shikoku is home to many places where you can feel the coolness. This guide introduces recommended spots to visit, including the Yokai Museum and Toki no Naya in Kagawa, Kakigori Cafe Himuro and Chichibugahama, Anabuki River, Kurozawa Wetland, Dogakuji Temple''s Wind Chime Festival, Ioki Cave, Mitataru Gongen Falls, Kannon Water and Meisuitei''s Somen Nagashi in Ehime, and the UFO Line and Ishizuchi Mountain Ropeway in Kochi.' where id = '9EGuQfqg8m9ba1x98sniu';
update content_bodies set title = '「THE FACES OF SHIKOKU」', description = 'この動画は、四国の「人々」、「自然」、そして「巡礼」をテーマにしています。徳島の小松海岸、香川の善通寺、そして高知の安居渓谷など、さまざまな場所が紹介されています。藍染や和三盆糖のような伝統的な工芸品、酒造りや真珠養殖といった文化体験も取り上げられています。また、祖谷渓や四国カルストなどの美しい自然景観も強調されており、四国の観光資源を示しています。高知のサンデーマーケットや高知城などの歴史的な名所も紹介され、四国の豊かな文化遺産を垣間見ることができます。' where id = 'pOdPYDkRVmQVjyvMju4ar';
update content_bodies set title = 'THE FACES OF SHIKOKU', description = 'This video showcases the diverse aspects of Shikoku, focusing on its people, nature, and pilgrimage. It features various locations such as Komatsu Beach in Tokushima, Zentsuji Temple in Kagawa, and the Yasui Valley in Kochi. The video highlights traditional crafts like indigo dyeing and Wasanbon sugar production, as well as cultural experiences such as sake brewing and pearl cultivation. It also includes scenic spots like the Iya Valley and the Shikoku Karst, emphasizing the region''s natural beauty. The Sunday Market in Kochi and historical sites like Kochi Castle are also presented, offering a glimpse into the rich cultural heritage and tourism potential of Shikoku.' where id = 'RSAhXDch1vT95EpRSWmkc';
update content_bodies set title = '奄美群島周遊キャンペーン（奄美群島しまめぐり割）（海篇）', description = '奄美群島しまめぐり割は、奄美群島が世界自然遺産に登録されたことに伴い、観光客の増加を見込んでいます。この効果を奄美群島全体に波及させるため、旅行会社が販売する奄美群島への旅行商品に対して割引助成を行います。また、旅行者には各島で利用できる電子クーポンも付与されます。割引額はお一人様一泊あたり最大5,000円で、宿泊者には2,000円分の旅クーポンが付いてきます。対象期間は令和5年7月1日から令和6年2月1日までです。お問い合わせは奄美群島しまめぐり割事務局（TEL：0570-000-255）まで、営業時間は平日・土日祝の10：00～17：00です。' where id = 'efvlU956OFqcAb_VEOMkv';
update content_bodies set title = 'Amami Islands Tour Campaign (Amami Islands Island Tour Discount) - Marine Edition', description = 'The Amami Islands Island Tour Discount aims to promote tourism in the Amami Islands following their registration as a UNESCO World Natural Heritage site. To enhance the benefits of this increase in visitors, discounts will be provided for travel products sold and created by travel agencies to the Amami Islands. Additionally, travelers will receive electronic coupons usable on each island. The discount is up to 5,000 yen per person per night, along with a 2,000 yen travel coupon for overnight guests. The campaign runs from July 1, 2023, to February 1, 2024. For inquiries, contact the Amami Islands Island Tour Discount Office at 0570-000-255, available from 10:00 AM to 5:00 PM on weekdays and weekends, excluding the New Year holidays.' where id = 'hsvHLTmdUijJ5zjH7eiHN';
update content_bodies set title = '奄美群島周遊キャンペーン（奄美群島しまめぐり割）', description = '奄美群島しまめぐり割は、奄美群島が世界自然遺産に登録されたことに伴い、観光客の増加を見込んでその効果を地域全体に波及させることを目的としています。旅行会社が販売する奄美群島への旅行商品に対して割引助成を行い、旅行者には各島で利用できる電子クーポンが付与されます。割引額はお一人様一泊あたり最大5,000円で、宿泊者には2,000円分の旅クーポンも提供されます。対象期間は令和5年7月1日から令和6年2月1日までです。お問い合わせは奄美群島しまめぐり割事務局（TEL：0570-000-255）まで、営業時間は平日・土日祝の10：00～17：00（年末年始を除く）です。' where id = 'Ia5txswJrvB1-iob1F_qy';
update content_bodies set title = 'Amami Islands Tour Campaign (Amami Islands Island Tour Discount)', description = 'The Amami Islands Island Tour Discount aims to promote tourism in the Amami Islands following their registration as a UNESCO World Natural Heritage site. To enhance the benefits of this increase in visitors, travel companies will offer discounts on travel packages to the Amami Islands. Additionally, travelers will receive electronic coupons that can be used on each island. The discount is up to 5,000 yen per person per night, along with a 2,000 yen travel coupon for overnight guests. The campaign runs from July 1, 2023, to February 1, 2024. For inquiries, contact the Amami Islands Island Tour Discount Office at 0570-000-255, available from 10:00 AM to 5:00 PM on weekdays and weekends, excluding the New Year holiday period (December 29 to January 3).' where id = 'ph7b0nd-1tDMrVFVAxShp';
update content_bodies set title = '奄美群島周遊キャンペーン（奄美群島しまめぐり割）（食篇）', description = '奄美群島しまめぐり割は、奄美群島が世界自然遺産に登録されたことに伴い、観光客の増加を見込んでいます。この効果を奄美群島全体に波及させるため、旅行会社が販売する奄美群島への旅行商品に対して割引助成を行います。また、各島で利用できる電子クーポンも旅行者に提供されます。割引額はお一人様一泊あたり最大5,000円で、宿泊者には2,000円分の旅クーポンが付与されます。対象期間は令和5年7月1日から令和6年2月1日までです。お問い合わせは奄美群島しまめぐり割事務局（TEL：0570-000-255）まで、営業時間は平日・土日祝の10：00～17：00です。' where id = 'RyEO3LuSQEqX6zyDW-PUJ';
update content_bodies set title = 'Amami Islands Tour Campaign (Amami Islands Island Tour Discount) - Food Edition', description = 'The Amami Islands Island Tour Discount aims to promote tourism in the Amami Islands following their registration as a UNESCO World Natural Heritage site. To enhance the benefits of this increase in visitors, travel companies will offer discounted travel packages to the Amami Islands, along with electronic coupons for use on each island. The discount is up to 5,000 yen per person per night, and guests will also receive a travel coupon worth 2,000 yen. The campaign runs from July 1, 2023, to February 1, 2024. For inquiries, contact the Amami Islands Island Tour Discount Office at 0570-000-255, available from 10:00 AM to 5:00 PM on weekdays and weekends, excluding the New Year holiday period.' where id = 'YR5d5mtSUCcyfrtr7bQaB';
update content_bodies set title = '中津川＆下呂PR動画 「Wonderful winter days」長編【4K】', description = 'この動画は冬の下呂市と中津川市の観光スポットを紹介するPR映像です。中津川市では、地歌舞伎や芝居小屋、中山道の馬籠宿、ストーンミュージアム博石館、かしも明治座、常盤座、産地直売所、加子母森林組合のモクモクセンターなどが紹介されています。下呂市では、小坂なリバーベース、巌立峡、下呂温泉街、JR東海のワイドビューひだ、森水無八幡神社、下呂温泉合掌村、金山の筋骨めぐり、馬瀬での五平餅作り体験、小坂の冬の滝めぐりなどが登場します。' where id = 'W6DcTNb2qbHAEcHKhQe2n';
update content_bodies set title = 'Nakatsugawa & Gero PR Video ''Wonderful Winter Days'' Long Version [4K]', description = 'This video is a promotional film showcasing the winter attractions of Gero City and Nakatsugawa City. It features various tourist spots in the following order: In Nakatsugawa City, highlights include the local Kabuki theater, Nakayama Road''s Magome-juku, the Stone Museum, and the Kashiwa Meijiza theater. Other attractions include the Tokiwaza theater, a direct sales shop, and the Kashimo Forest Association''s Mokumoku Center. In Gero City, the video presents the Osakanari River Base, Gandate Gorge, and the Gero Onsen area, along with the JR Tokai Wide View Hida train. It also features the Morimizu Hachiman Shrine, Gero Onsen Gassho Village, and experiences like making Gohei-mochi and winter waterfall tours in Osakanari.' where id = 'z3QQWcp04QGB0xGFyI_v5';
update content_bodies set title = '【喜界島】奄美群島認定エコツアーガイド  喜界町編', description = '奄美広域事務組合による奄美群島エコツーリズム魅力体験事業の一環として、喜界島の喜界町に住む認定エコツアーガイドの武田さんに密着したエコツアー動画が作成されました。この動画では、地域の自然の美しさや生物多様性が紹介されています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。詳細は喜界島総合情報サイト「喜界島ナビ」をご覧ください。' where id = 'inzG3lMD0mluJnzjNXszY';
update content_bodies set title = 'Eco tourism in Kikai Town Kikaijima Island', description = 'This project focuses on the Amami Islands Eco-Tourism Experience, featuring a certified eco-tour guide, Mr. Takeda, who lives in Kikai Town on Kikaijima Island. A video showcasing eco-tours has been created to highlight the natural beauty and biodiversity of the area. For inquiries about tours and guides, please contact the local tourism association of each island. More information can be found on the Kikaijima Tourism Association website.' where id = 'DXkWYXycnZrxgySMpPgD4';
update content_bodies set title = '中津川＆下呂PR動画 「Wonderful winter days」短編【4K】', description = 'この動画は冬の下呂市と中津川市の観光スポットを紹介するPR映像です。中津川市では、めぐりーん産地直売所、中山道馬籠宿、ストーンミュージアム博石館、かしも明治座、加子母森林組合モクモクセンターが紹介されています。下呂市では、小坂なリバーベース、巌立峡、下呂温泉街、JR東海のワイドビューひだ、森水無八幡神社、下呂温泉合掌村、筋骨めぐり、五平餅作り体験、小坂な冬の滝めぐりが登場します。詳細は各リンクを参照してください。' where id = '1jEjMfkem_db29LDwqnRC';
update content_bodies set title = 'Nakatsugawa & Gero PR Video ''Wonderful Winter Days'' Short Film [4K]', description = 'This video is a promotional film showcasing the winter attractions of Gero City and Nakatsugawa City. It features various tourist spots in the following order: Nakatsugawa City includes Megurin Direct Sales Office, Nakayama Road Magome-juku, Stone Museum Hakusekikan, Kashimo Meijiza, and Kashimo Forest Association Mokumoku Center. Gero City highlights include Osakanari River Base, Gandate Gorge, Gero Onsen Town, JR Tokai Wide View Hida train, Morimizu Hachiman Shrine, Gero Onsen Gassho Village, Kinkotsu Meguri, and a Gohei Mochi making experience in Mase. For more details, visit the respective links provided.' where id = 'fH9SRAGP61DCLG3DhjF1Z';
update content_bodies set title = '中津川の桜【四ツ目川の桜】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。こちらは中津川市街地に位置する四ツ目川の桜で、2021年3月28日にドローンで撮影されました。中津川の桜をぜひ4K映像でお楽しみください。詳細は中津川観光協会のホームページをご覧ください。' where id = 'h_KXAlyNhSAXrtlswXTMD';
update content_bodies set title = 'Cherry Blossoms in Nakatsugawa: Yotsume River Cherry Blossoms', description = 'This is a series introducing famous cherry blossom spots in Nakatsugawa City, Gifu Prefecture. The cherry blossoms along the Yotsume River, located in the city center of Nakatsugawa, were captured in a drone video on March 28, 2021. Enjoy the cherry blossoms of Nakatsugawa in stunning 4K resolution. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'TBCF7G8SPr5mJmSy9Mzj7';
update content_bodies set title = '中津川の桜【中山道 子野の地蔵堂石仏群】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。中山道の中津川宿から落合宿へ向かう道中に位置する「子野の地蔵堂石仏群」の中心に立つしだれ桜が特集されています。この桜は2021年3月28日にドローンで撮影されました。中津川の桜を4K映像でお楽しみください。詳細は中津川観光協会のホームページをご覧ください。' where id = 'zYiqTrsbPYGjn_3srv7dC';
update content_bodies set title = 'Cherry Blossoms in Nakatsugawa: Jizo-do Stone Buddha Group on the Nakasendo', description = 'This series introduces famous cherry blossom spots in Nakatsugawa City, Gifu Prefecture. Featured is a weeping cherry tree located in the center of the Jizo-do Stone Buddha Group, situated along the route from Nakatsugawa-juku to Ochiai-juku on the Nakasendo. The tree was captured in a drone video on March 28, 2021. Enjoy the cherry blossoms of Nakatsugawa in stunning 4K resolution. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'u5KE6WvshYNg2dadVnnT1';
update content_bodies set title = 'けふの下呂温泉', description = '2月25日（土）に行われた『冬の下呂温泉花火物語』の様子です。当日は雨や風もなく、絶好の花火日和で、テーマは『合格祈願花火』でした。5段打上花火が夜空に広がり、毎週の恒例行事として親しまれていますが、気づけば3月25日（土）の最後の打ち上げまであと4回となりました。終わってしまうのは寂しいですが、1回1回を大切に見届けたいと思います。今後とも下呂温泉をよろしくお願いいたします。' where id = 'rn0VKDxYQuY2gP5V3FUGv';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On February 25th (Saturday), the ''Winter Gero Onsen Fireworks Story'' was held. The weather was perfect for fireworks, with no rain or wind, and the theme was ''Fireworks for Success Prayers.'' Five-tiered fireworks lit up the night sky. As this weekly event continues, there are only four more displays left until the final one on March 25th (Saturday). While it is sad to see it end, each display is a moment to cherish. We look forward to your continued support for Gero Onsen.' where id = 'ZHWEeGofcqUJV-K3pNnRF';
update content_bodies set title = 'けふの下呂温泉', description = '2月4日（土）に行われた『冬の星座花火』の様子をお伝えします。当日は厳しい寒さでしたが、雨や雪はなく、花火には絶好の条件でした。澄んだ夜空に星をイメージした花火が打ち上がり、その美しさでお客様を魅了しました。三寒四温の言葉通り、少しずつ暖かい日が増えてきているように感じます。今後とも下呂温泉をよろしくお願いいたします。' where id = 'bHV_UfekohhUgRcvC06Wq';
update content_bodies set title = 'Gero Onsen Today', description = 'On February 4th (Saturday), the ''Winter Constellation Fireworks'' event took place. Despite the harsh cold, there was no rain or snow, making it a perfect day for fireworks. Fireworks inspired by stars lit up the clear night sky, captivating the audience with their beauty. As the saying goes, ''three cold days followed by four warm days,'' it seems that warmer days are gradually increasing. We look forward to your continued support for Gero Onsen.' where id = 'ipmfagJU_xaD_JxEN9bTk';
update content_bodies set title = 'けふの下呂温泉', description = '5月21日（土）に「ラブレター花火」をテーマとした『天壌無窮　悪疫退散　下呂温泉花火』が開催されました。当日は雨が降りましたが、開始時間には小ぶりになり、無事に花火が打ち上がりました。情熱的な花火にお客様たちは歓声を上げ、終わりには盛大な拍手が巻き起こりました。来週も多くのお客様に来ていただきたいと思います。もちろん、温泉もお楽しみください。アルカリ性のお湯で、すべすべのお肌を手に入れてください。下呂温泉をよろしくお願いいたします！' where id = 'sh43SBAmPRy7Lsfnum_G5';
update content_bodies set title = 'Gero Onsen Today', description = 'On May 21st (Saturday), the ''Gero Onsen Fireworks: Eternal Heaven and Earth, Epidemic Dispersal'' event was held, themed around ''Love Letter Fireworks.'' Although it rained on the day of the event, the rain lightened up by the start time, allowing the fireworks to be launched successfully. The passionate fireworks delighted the audience, who cheered and applauded enthusiastically towards the end. We hope to welcome even more visitors next week. Don''t forget to enjoy the hot springs as well; the alkaline water will give you smooth skin. We appreciate your support for Gero Onsen!' where id = 'qFjMwPNbzWfs39nMQRLM8';
update content_bodies set title = 'けふの下呂温泉', description = '5月14日（土）、『天壌無窮　悪疫退散　下呂温泉花火』が久しぶりに開催されました。やや肌寒い夜風が吹く中、多くのお客様が花火を見に集まり、躍動感あふれる『こいのぼり花火』に歓声が上がり、下呂温泉の夜は活気に満ちていました。天候が不安定なこの頃ですが、来週も雨に見舞われずに花火を楽しみたいものです。もちろん、花火見物の後は温泉もお忘れなく。しらさぎ緑地公園内の『噴泉池』の足湯に浸かるのも良いですね。下呂温泉をよろしくお願いいたします！' where id = '64KS3DMt0gYvOvyTLlMpi';
update content_bodies set title = 'Gero Onsen Today', description = 'On May 14th (Saturday), the ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks'' event was held for the first time in a while. Despite the slightly chilly night breeze, many guests gathered to enjoy the fireworks. The vibrant ''Koinobori Fireworks'' drew cheers from the crowd, filling the night at Gero Onsen with excitement. Although the weather has been unstable lately, we hope to enjoy the fireworks next week without rain. Of course, don''t forget to relax in the hot springs after watching the fireworks. Soaking in the footbath at the ''Funsen Pond'' in Shirakagi Green Park is also a great option. We appreciate your support for Gero Onsen!' where id = 'fQHv-OFbxXjng6IcuPieG';
update content_bodies set title = 'けふの下呂温泉', description = '4月2日（土）に行われた『新生活応援花火』をテーマにした『天壌無窮　悪疫退散　下呂温泉花火』の様子をお伝えします。新年度初の花火は、多くのお客様を魅了し、新生活への応援のようでした。気温も春らしくなり、暖房ともお別れの時期が近づいていますが、温泉は四季を通じて楽しみたいものです。この変化の時期にこそ、温泉に浸かって体調を整えましょう。下呂温泉をよろしくお願いいたします！' where id = '6RKeMhm-R-MliOeqaS1Po';
update content_bodies set title = 'Gero Onsen Today', description = 'On April 2nd (Saturday), the ''Gero Onsen Fireworks'' themed ''Eternal Heaven and Earth, Expelling Epidemics'' took place, showcasing the first fireworks of the new fiscal year. The event captivated visitors, serving as a warm encouragement for the new beginnings ahead. With temperatures rising, it seems we may soon say goodbye to heating. However, while we part with heating, we hope to continue enjoying the hot springs throughout the seasons. This transitional period in life is the perfect time to relax in the onsen and take care of our health. We appreciate your support for Gero Onsen!' where id = 'psNAoMlLAoZHNAuy-qIGH';
update content_bodies set title = '中津川＆下呂PR動画 「Wonderful summer days」【4K】長編', description = 'この動画は、夏の中津川市と下呂市の観光スポットを紹介するPR映像です。中津川市では、付知峡、不動滝ひろづき、宮島キャンプ場、付知峡上田屋ブルーベリー園、苗木城跡、HillBilly Coffee Company、馬籠宿、東濃サイクリングが紹介されています。下呂市では、杤本農園、LA VITA e bella、火振り漁、慈雲院、下原八幡神社、下呂温泉素肌美人スイーツ、下呂温泉街、足湯、DAiseN TouRsが登場します。詳細は各観光協会のウェブサイトをご覧ください。' where id = 'XVqlDjTskBr5Pzh4I3d1O';
update content_bodies set title = 'Nakatsugawa & Gero PR Video ''Wonderful Summer Days'' [4K] Long Version', description = 'This video is a promotional film showcasing the summer attractions of Nakatsugawa City and Gero City. It features various tourist spots in the following order: In Nakatsugawa, highlights include Tsukechi Gorge, Fudo Falls, Miyajima Campground, Ueda Blueberry Farm, Naegi Castle Ruins, HillBilly Coffee Company, and the Nakasendo Trail at Magome-juku, along with cycling in the Tono area. In Gero, the video presents Tochimoto Farm, LA VITA e bella, firefly fishing, Jiuin Temple, Gero Onsen''s beautiful skin sweets, Gero Onsen town, foot baths, and DAiseN TouRs. For more details, visit the respective tourism association websites.' where id = 'SAivW7kfwEdaYeYJYgfyo';
update content_bodies set title = '中津川＆下呂PR動画「Wonderful summer days」 短編 【4K】', description = 'この動画は、夏の下呂市と中津川市の観光スポットを紹介するPR映像です。中津川市では、付知峡、不動公園、付知峡上田屋ブルーベリー園、苗木城跡、HillBilly Coffee Company、中山道馬籠宿、東濃サイクリングが紹介されています。下呂市では、下呂温泉街、足湯、杤本農園、LA VITA e bella、火振り漁、DAiseN TouRsが登場します。観光スポットの詳細は、各リンクを参照してください。' where id = 'q1M9AivoPQ8SkduLg6jKt';
update content_bodies set title = 'Nakatsugawa & Gero PR Video ''Wonderful Summer Days'' Short Film [4K]', description = 'This video is a promotional film showcasing the summer attractions of Gero City and Nakatsugawa City. It highlights various tourist spots in the following order: In Nakatsugawa City, it features Tsukechi Gorge, Ueday Blueberry Farm, Naegi Castle Ruins, HillBilly Coffee Company, Nakasendo Magome-juku, and Tono Cycling. In Gero City, it showcases Gero Onsen Town, foot baths, Tochimoto Farm, LA VITA e bella, firefly fishing, and DAiseN TouRs. For more details about the attractions, please refer to the provided links.' where id = '3HIwlpC5qaiB5qZD1c63l';
update content_bodies set title = 'けふの下呂温泉', description = 'まれにみる大雪の下呂温泉を訪れ、雪化粧をした合掌村を見に行きました。いつも見慣れた合掌村は一面の銀世界で、まるで別の場所のように感じました。手湯と足湯で体を暖めながら雪道を歩き、雪に覆われた合掌家屋の雰囲気を堪能しました。すべり台は使用できませんでしたが、たまにはこうした姿の合掌村に触れるのも楽しいものです。雪の日には温泉が一番で、下呂温泉の湯船に浸かって新年への英気を養いましょう！下呂温泉をよろしくお願いいたします！' where id = 'Z1qX465rUyPDVbCRDGUv6';
update content_bodies set title = 'Today in Gero Onsen', description = 'Gero Onsen is experiencing an unusual heavy snowfall, prompting a visit to see the snow-covered Gassho Village. The familiar village transforms into a silver wonderland, resembling a completely different place. While warming up in the hand and foot baths, I walked along the snowy paths. The snow-covered Gassho houses created a fantastic atmosphere, allowing for an even more enjoyable experience than usual. Although the slide was unusable due to the snow, it’s fun to occasionally experience the village in this snowy state, despite the challenges of snow shoveling. On such snowy days, there’s nothing better than soaking in the hot springs of Gero Onsen to rejuvenate for the new year! Please continue to support Gero Onsen!' where id = 'JZS4fcNoTTgTTXqzukYdB';
update content_bodies set title = 'けふの下呂温泉', description = '12月11日（土）に、「歳末感謝花火」がテーマの『天壌無窮悪疫退散　下呂温泉花火物語』が開催されました。寒い中、多くのお客様が訪れ、打ち上がる花火に歓声を上げていました。今年も残すところあと少しで、来年に向けた準備が進められています。花火物語が行われている緑地公園では、ウィンターイルミネーションも点灯し、ロマンティックな雰囲気が漂っていました。寒さが増す中、温泉がますます恋しくなります。下呂温泉をよろしくお願いいたします！' where id = 'UYEd042iZs2CSPVGaDr15';
update content_bodies set title = 'Gero Onsen Today', description = 'On December 11th (Saturday), the ''End-of-Year Appreciation Fireworks'' themed event, ''Tenjo Mukyu: Fireworks Story of Gero Onsen for the Elimination of Evil,'' was held. Despite the cold weather, many visitors gathered to enjoy the fireworks, cheering as they lit up the sky. With only a little time left in the year, preparations for the new year are underway. The event took place in the green park where winter illuminations were also lit, creating a romantic atmosphere that attracted more visitors. As the cold intensifies, the desire for hot springs grows stronger. We look forward to your continued support for Gero Onsen!' where id = 'AXDPm-l3JKXuY10tPbr9I';
update content_bodies set title = 'けふの下呂温泉', description = '11月27日（土）に行われた『スイーツ花火』の様子をお伝えします。多くのお客様が訪れ、スイーツをテーマにしたパステルカラーの花火に歓声が上がりました。花火を見ていると、スイーツが食べたくなりますね。下呂温泉には美味しいスイーツがたくさんありますので、ぜひ味わってみてください。気づけば11月も終わり、12月が近づいています。『天壌無窮悪疫退散 下呂温泉花火物語』は3月まで開催予定で、まだまだ楽しむことができます。下呂温泉をよろしくお願いいたします！' where id = 'zccNMiYPhmSYYPtOcLUq4';
update content_bodies set title = 'Gero Onsen Today', description = 'On November 27th (Saturday), the ''Sweets Fireworks'' event took place, attracting many visitors who were delighted by the pastel-colored fireworks themed around sweets. Watching the display made me crave some sweets, and Gero Onsen offers a variety of delicious options to try. As November comes to an end and December approaches, the ''Tenjo Mukyu Akki Taisan Gero Onsen Fireworks Story'' will continue until March, providing more opportunities for enjoyment. We hope you continue to support Gero Onsen!' where id = 'kuYdo8AzLNMyo1BwWPTyy';
update content_bodies set title = 'けふの下呂温泉', description = '先週、岩屋ダム周辺、孝子ヶ池公園、玉龍寺の紅葉を撮影しました。晴れた空の下、色鮮やかな紅葉が楽しめましたが、同時に落葉も目立ち始めていました。寒くなると葉が一気に落ちると言われており、最近の冷え込みで紅葉も落ちてしまったかもしれません。温泉街から見える山々の頂上には雪が見え、秋から冬への移り変わりを感じさせます。こんな時こそ温泉で体を温めて、寒さに備えましょう！下呂温泉をよろしくお願いいたします！' where id = 'rTGkC0jmsdlwN-kQBulBp';
update content_bodies set title = 'Today’s Gero Onsen', description = 'Last week, I captured the autumn leaves around Iwaya Dam, Takako Pond Park, and Gyokuryuji Temple. Under clear skies, the vibrant colors of the leaves were visible, but the falling leaves were also becoming noticeable. It is said that leaves fall rapidly as the temperature drops, and recent cold weather may have caused the leaves to drop even more. Snow can be seen on the mountaintops visible from the hot spring town, signaling the transition from autumn to winter. Now is the perfect time to warm up in the hot springs and prepare for the colder season! Please enjoy Gero Onsen!' where id = 'oAr8vetfourAWsr1l08-T';
update content_bodies set title = 'けふの下呂温泉', description = '11月20日（土）に開催された「天壌無窮　悪疫退散　下呂温泉花火物語」は、『勤労感謝花火』がテーマでした。これは、11月23日（火）の勤労感謝の日を先取りしたもので、勤労・生産に感謝する盛大な花火が打ち上げられました。この日は新嘗祭に由来し、五穀豊穣に感謝するお祝いが元とされています。収穫への感謝が勤労へのものに変わった経緯には諸説ありますが、花火を楽しむことで先人への感謝の気持ちが湧き上がります。勤労をねぎらうには温泉が一番です！次回の花火では、温泉に浸かりながら楽しめるといいですね。下呂温泉をよろしくお願いいたします！' where id = 'PupXxnfj6nAV13qVj333Z';
update content_bodies set title = 'Gero Onsen Today', description = 'On November 20th, a fireworks event titled ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' was held, themed around ''Labor Thanksgiving Fireworks.'' This event was a pre-celebration for Labor Thanksgiving Day on November 23rd, expressing gratitude for labor and production. The day is believed to have originated from the Niiname-sai, a festival celebrating the harvest. While there are various theories about the shift from harvest gratitude to labor appreciation, the enjoyment of fireworks today evokes a sense of gratitude towards our ancestors. To truly appreciate labor, there’s nothing better than a hot spring! It would be wonderful if the next fireworks could be enjoyed while soaking in the onsen. We appreciate your support for Gero Onsen!' where id = '7QEy4loEG-rbI6iFCCl3h';
update content_bodies set title = 'けふの下呂温泉', description = '11月12日（金）から温泉寺で「温泉寺周辺ライトアップ」が始まりました。夜にも紅葉を楽しむことができ、お寺と紅葉の美しい景観が心を落ち着かせてくれます。写真を撮ったり散策を楽しむお客様も多く、静かな時間が流れています。残念ながら、コロナ感染予防のためにいくつかの恒例イベントは中止となりましたが、『190歳の作品展‼』や『草木染のある暮らし展』などの催し物は開催されています。ぜひご覧にいらしてください。紅葉ライトアップを楽しんだ後は、温泉でリラックスしましょう！下呂温泉をよろしくお願いいたします！' where id = '0NZn_WIcJ_Sri_1jjjPVo';
update content_bodies set title = 'Gero Onsen Today', description = 'From November 12 (Friday), the ''Light Up Around Onsenji Temple'' has started. Visitors can enjoy the beautiful autumn leaves at night, creating a serene atmosphere with the temple''s majestic scenery. Many guests have come to take photos and stroll, experiencing a peaceful time. Unfortunately, some regular events have been canceled due to COVID-19 prevention measures, but exhibitions such as ''190-Year-Old Art Exhibition'' and ''Living with Natural Dyes'' are still being held. After enjoying the autumn light-up, don''t forget to relax in the hot springs! We look forward to welcoming you to Gero Onsen!' where id = 'eolb-tBlKDmQhJWm2c-h2';
update content_bodies set title = 'けふの下呂温泉', description = '11月6日（土）に行われた「天壌無窮　悪疫退散　下呂温泉花火物語」では、飛騨の山々を彩る紅葉をイメージした花火が打ち上げられました。寒さが増す中でも多くのお客様が訪れ、花火に歓声を上げていました。紅葉の起源は奈良～平安時代にさかのぼると言われ、今も多くの人々を楽しませています。夜風で冷えた体を温めるには温泉が最適で、全身をつかるよりも半身浴から始めるとより効果的だそうです。下呂温泉をよろしくお願いいたします！' where id = 'uT91GOl5RjWMF8quuSRH3';
update content_bodies set title = 'Gero Onsen Today', description = 'On November 6th, the ''Tenjo Mukyu - Epidemic Extermination - Gero Onsen Fireworks Story'' showcased fireworks inspired by the autumn leaves adorning the Hida mountains. Despite the increasing cold, many visitors enjoyed the event, cheering for the fireworks. The tradition of admiring autumn leaves dates back to the Nara and Heian periods, continuing to bring joy to many. To warm up from the chilly night air, soaking in the hot springs is ideal. It is suggested to start with a half-body bath for better effects rather than immersing the whole body at once. Please enjoy Gero Onsen!' where id = 'xNR2asEFbZ1a5LcxJ6Klc';
update content_bodies set title = 'けふの下呂温泉', description = '飛騨小坂にある『がんだて公園』へ、紅葉が見ごろだと聞き、訪れました。公園の名前にもある『がんだて』は、県指定の天然記念物である溶岩の絶壁で、その迫力に圧倒されました。山々には赤や黄色の紅葉が広がり、遊歩道を歩きながらその美しい風景を楽しむことができました。途中には滝もあり、陽光が差し込む滝を間近で見ることができ、その迫力に感動しました。森林浴も楽しみながら、秋の風情を満喫しました。今がちょうど見頃なので、紅葉を楽しみたい方はお早めに訪れることをお勧めします。下呂温泉もぜひよろしくお願いいたします！' where id = 'Ep-vZ6ZUIpTWLVyIDbW-0';
update content_bodies set title = 'Today’s Gero Onsen', description = 'I visited ''Gandate Park'' in Hida-Kosaka, having heard that the autumn leaves are at their peak. The park features ''Gandate'', a cliff made of lava that is designated as a natural monument by the prefecture, which is truly impressive. The mountains are adorned with vibrant red and yellow foliage, and I enjoyed walking along the paths to take in the scenery. There is also a waterfall along the way, and witnessing the sunlight streaming through it was a breathtaking experience. I was able to enjoy forest bathing and fully appreciate the autumn atmosphere. Since the leaves are currently at their best, I recommend visiting soon if you want to enjoy the autumn colors. Please also consider Gero Onsen!' where id = 'Ic4hMbrfgy4kfPEdfmX6A';
update content_bodies set title = 'けふの下呂温泉', description = '2021年10月28日、下呂温泉の紅葉スポットの一つである合掌村を訪れました。まだ紅葉の見ごろには早いようで、色づいている木々は少なかったですが、既に色づき始めた木々はとても美しかったです。全体が見事に紅葉している光景を早く見たいと思います。合掌村には足湯があり、紅葉の中で温泉を楽しむのも良いですね。もちろん、下呂温泉には他にも多くの足湯や温泉がありますので、ぜひ訪れてみてください。下呂温泉をよろしくお願いいたします！' where id = 'aXEWkzyPk1tjhDbbZgsRh';
update content_bodies set title = 'Today at Gero Onsen', description = 'On October 28, 2021, I visited one of the autumn foliage spots in Gero Onsen, the Gassho Village. It seems that it is still a bit early for the peak of autumn colors, as there weren''t many trees fully changed. However, the trees that have started to change are quite beautiful. I look forward to seeing the entire area in full autumn splendor soon. Gassho Village also features a foot bath, allowing visitors to enjoy the hot springs amidst the autumn leaves. Don''t forget to explore other foot baths and hot springs available throughout Gero Onsen. Thank you for your support of Gero Onsen!' where id = 'O6bQWIEkiwziG_DjgyGvl';
update content_bodies set title = 'けふの下呂温泉', description = '最近は秋の訪れを感じる涼しさがありましたが、今日は日差しが強く、まるで夏が戻ってきたかのような下呂温泉です。冷たいものが欲しくなりますね。縄文公園から約30分歩いて歴史の森みはらし台に登りました。山道ではまだ葉が青く、蝉の声が聞こえ、夏の気候を感じます。みはらし台からの絶景は、街や山々が夏そのものに映ります。しかし、道には栗のイガが落ちており、秋の気配も漂っています。紅葉の時期が楽しみです。絶景を楽しんだ後は温泉を堪能しましょう！下呂温泉をよろしくお願いいたします！' where id = 'Jt9NRY2m0bg-i87orW2EN';
update content_bodies set title = 'Today at Gero Onsen', description = 'Recently, the coolness of autumn was felt, but today at Gero Onsen, the strong sunlight makes it feel like summer has returned. It makes one crave something cold. After a 30-minute walk from Jomon Park, I climbed to Mihara Shidai in the Historical Forest. The leaves along the mountain path are still green, and the sound of cicadas indicates a summer climate. The breathtaking view from Mihara Shidai showcases the town and mountains, still reflecting the essence of summer. However, signs of autumn are also present, such as chestnut husks scattered along the path. I look forward to the autumn foliage season. After enjoying the stunning views, let''s indulge in the hot springs! Please enjoy Gero Onsen!' where id = '8hyWlwHgn28jgsPVXRT2y';
update content_bodies set title = 'けふの下呂温泉', description = '夕暮れの飛騨川に足を踏み入れました。日差しは強いものの、夏の暑さは感じられず、秋の訪れを実感します。涼しい風が吹き、川に手を入れると、これまでのひんやりした感覚よりも冷たさが先に感じられました。川面に映る夕陽も落ち着いて見えました。美しい紅葉が見られる頃に撮影に行きたいと思います。秋の下呂温泉も紹介していければと思います。秋を感じながらの温泉は格別です！春夏秋冬、いつでも極上の湯を楽しめる下呂温泉をよろしくお願いいたします！' where id = 'Xfxwx7vowBrEYbkLFCmHb';
update content_bodies set title = 'Today at Gero Onsen', description = 'I stepped into the Hida River at dusk. Although the sun was strong, it didn''t feel as hot as summer, indicating that autumn is approaching. The breeze was cool, and when I dipped my hand into the river, I felt a coldness that was more pronounced than the refreshing chill I had experienced before. The sunset reflecting on the river''s surface appeared calm. I look forward to capturing the beautiful autumn foliage soon and sharing more about Gero Onsen in the fall. Soaking in the hot springs while feeling the arrival of autumn is truly special! Gero Onsen offers exquisite baths year-round!' where id = 'izjtk7sri8iWVL9Y_Jkaf';
update content_bodies set title = 'けふの下呂温泉', description = 'けふの『にゃらんグルメ』は、合掌村の『萬古庵』さんの看板スイーツ『ばんこにゃんみつ』を紹介します。トマトジュースやよもぎで作った白玉、こんにゃくなど、下呂の特産品を活かしたこのスイーツには、にゃらんとげろぐるくんが登場します。ホイップクリーム、あんこ、抹茶アイスに黒蜜をたっぷりかけて楽しめます。1日先着5食限定で、価格は700円（ソフトドリンク1杯サービス付き）です。『にゃらんグルメ』の販売期間は今年の11月30日までなので、ぜひお見逃しなく！甘味と温泉の王道を楽しんでください。' where id = 'zbG4foGQMN32n8JgaGlbP';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today''s ''Nyarang Gourmet'' features ''Bankoan'' from Gassho Village, showcasing their signature dessert ''Banko Nyan Mitsu''! This delightful treat incorporates local specialties from Gero, such as white balls made from tomato juice and yomogi, along with konnyaku. Nyarang and Gerogurukun greet you as you enjoy this dessert topped with whipped cream, red bean paste, matcha ice cream, and plenty of black syrup. Limited to the first five servings each day, it is priced at ¥700, which includes a complimentary soft drink. Don''t miss out on the ''Nyarang Gourmet'' available until November 30 this year! Indulge in the perfect combination of sweets and hot springs at Gero Onsen!' where id = 'A5UXtb9CTRBvG-OG6Y-hg';
update content_bodies set title = 'けふの下呂温泉', description = 'けふも、『にゃらんグルメ』を探しに下呂温泉を散策しましょう！下呂温泉に新たにオープンしたプリン専門店『下呂プリン』では、下呂牛乳と厳選された卵やバニラビーンズを使った手作りプリンに、ソフトクリームをトッピングした『にゃらんプリンソフト』が楽しめます。なめらかで上品な甘さのプリンとひんやりしたソフトクリームの組み合わせは絶品です。また、にゃらんの顔と手を模した米粉の焼き菓子も可愛らしく、サクサクとした食感で美味しいです。1日先着5食限定で、価格は600円。『にゃらんグルメ』の販売は11月30日までなのでお見逃しなく！近くの『鷺の足湯』に浸かりながら楽しむのも良いですね。グルメと温泉のコラボレーションをお楽しみください！' where id = '-V-Gycs5YGQyd9sbdbiuZ';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today, let''s explore Gero Onsen in search of ''Nyarang Gourmet''! A new pudding specialty shop, ''Gero Pudding'', has opened in Gero Onsen. They offer a special treat called ''Nyarang Pudding Soft'', made with Gero milk, carefully selected eggs, and vanilla beans, topped with soft serve ice cream. The smooth and subtly sweet pudding pairs perfectly with the cool soft serve. Additionally, there are adorable rice flour baked goods shaped like Nyarang''s face and hands, which are crispy and delicious. Only five servings are available each day for ¥600. The ''Nyarang Gourmet'' is available until November 30 this year, so don''t miss out! Enjoying ''Nyarang Pudding Soft'' while soaking in the ''Sagi Foot Bath'' nearby adds to the experience. This is a delightful collaboration of gourmet food and hot springs! Gero Onsen welcomes you!' where id = 'uhbJ-mkC6WabFfGkX40pl';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉は連日の晴れ模様で、夏真っ盛りの気候です。蝉の声も響き渡っています。再び合掌村を訪れ、萬古庵で「萬古あんみつ」を楽しみました。こんにゃくやトマトを使ったユニークなあんみつで、梅干しと黒蜜が添えられています。最初はそのまま味わい、途中から黒蜜をかけることで味の変化を楽しむことができます。餡子とこんにゃく、クリームと白玉、トマトと抹茶アイスクリームなど、様々な組み合わせを試すのも楽しいです。あんみつを堪能した後は温泉へどうぞ！夏の暑さを吹き飛ばす爽快感が待っています。どの季節にも合う温泉が揃っている下呂温泉をよろしくお願いいたします！' where id = 'ogUw-ewpMVeiATp-FD2w4';
update content_bodies set title = 'Today in Gero Onsen', description = 'Gero Onsen is experiencing consecutive sunny days, with summer in full swing as the sun shines brightly and the temperature rises. The cicadas are chirping energetically. I visited the Gassho Village again and enjoyed ''Bankoan Mitsu'' at Bankoan. This unique dessert features ingredients like konjac and tomato, served with a side of pickled plum and black syrup. It''s delightful to taste it plain at first and then add the syrup for a flavor change. Combining red bean paste with konjac, cream with shiratama, and tomato with matcha ice cream adds to the fun. After enjoying the dessert and exploring Gassho Village, be sure to visit the hot springs! A refreshing experience awaits to blow away the summer heat! Gero Onsen offers a variety of hot springs suitable for any season!' where id = 'jGjjdDmoa3swgWCdysPiB';
update content_bodies set title = 'けふの下呂温泉', description = 'けふは温泉街から歩いて約10分、雨情公園へゆきました。連日の暑さの中でも、川の流れと木々の木陰のおかげで、涼しく過ごすことができます。せせらぎを聞きながら、のんびりと寝転んでみたいですね。川に足を浸してみると、その冷たさにますます清涼の思いです。さて、暑さを吹き飛ばすにはやはり温泉が一番！太陽を浴びながらの入浴も新鮮で楽しいものです！夏こそ温泉に入って暑気払い！下呂温泉をよろしくお願いいたします！' where id = '0tjIiM3pWIFkeiF5uhnm5';
update content_bodies set title = 'Today at Gero Onsen', description = 'Today, I visited Ujō Park, which is about a 10-minute walk from the hot spring town. Despite the continuous heat, the coolness provided by the river''s flow and the shade of the trees makes it comfortable. I would love to relax and lie down while listening to the babbling of the stream. Dipping my feet in the river adds to the refreshing feeling. To beat the heat, nothing beats a hot spring! Bathing under the sun is a fresh and enjoyable experience. Summer is the perfect time to enjoy hot springs and cool off! I highly recommend Gero Onsen!' where id = 'ZuDNtX1mBVIwyoATXtCS9';
update content_bodies set title = 'けふの下呂温泉', description = '『とちの実煎餅　千寿堂』さんへ、素肌美人スイーツを目指していきましょう。店内は栃の実づくしで、注文後すぐに『栃の実シフォンのチョコパフェ』が運ばれてきました。チョコと栃の実、シフォンケーキのハーモニーが楽しめる贅沢なパフェです。添えられた煎餅もぱりぱりとした食感で美味しいです。栃の実にはポリフェノールが含まれ、抗酸化作用で肌の張りを保つ効果があります。食べ終わった後、肌に張りが出たように感じました。さらなる素肌美人を目指して温泉へ行きましょう！栃の実と温泉の相乗効果で、肌はますます美しくなります。素肌美人と温泉の聖地、下呂温泉をよろしくお願いいたします！' where id = 'UT7i5R2SMMiF91EU44PBJ';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Let''s head to ''Tochinomi Senbei Senjudou'' for some skin-beautifying sweets. The shop is filled with products made from tochi nuts. Right after ordering, I received the ''Tochi Nut Chiffon Chocolate Parfait.'' This chocolate parfait, rich in tochi nuts, creates a luxurious and deep sweetness with a harmonious blend of chocolate and chiffon cake. The accompanying senbei has a delightful crunch. Tochi nuts contain polyphenols, which have antioxidant properties that help maintain skin elasticity. After finishing the parfait, I felt an immediate improvement in my skin''s firmness. Now, let''s head to the onsen for even more skin benefits! The combination of tochi nuts and the hot spring will enhance our beauty even further. Gero Onsen, the sacred place for beautiful skin, is highly recommended!' where id = 'PYc4KPJw9Ap-B5AhR_G48';
update content_bodies set title = 'けふの下呂温泉', description = '素肌美人スイーツを求めて、『自家焙煎珈琲工房ペリゴール』さんへ行きました。注文したのは『とちの実クラッシュアイス』で、バニラアイスとフレンチトースト、抗酸化作用のある栃の実を使った下呂銘菓『栃の実せんべい』が添えられています。バニラアイスの上品な甘み、フレンチトーストの優しい食感、栃の実せんべいの歯ごたえが絶妙に混ざり合い、あっという間に食べ終えました。暑さも吹き飛び、心身ともにリフレッシュ。ついつい2杯目が欲しくなるおいしさです。余韻を忘れずに温泉へGO！さらなるリフレッシュが期待できます！お肌に優しい温泉とスイーツの街、下呂温泉をよろしくお願いいたします！' where id = '5zyud2OYz_18gQashnfJY';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Let''s head to ''Périgord Coffee Roastery'' in search of beautiful skin sweets. I ordered the ''Tochi Nut Crush Ice,'' which comes with vanilla ice cream and French toast, accompanied by the Gero specialty ''Tochi Nut Senbei'' made with plenty of antioxidant-rich tochi nuts. The elegant sweetness of the cold vanilla ice cream, the gentle texture of the French toast, and the crunchiness of the tochi nut senbei blended together to create an exquisite dish that I finished in no time. The heat was blown away, and I felt refreshed both physically and mentally, making me crave a second serving. Without forgetting the aftertaste, it''s time to go to the hot springs! More refreshment awaits! Gero Onsen, a town of skin-friendly hot springs and sweets, is highly recommended!' where id = '5R4wd9ewZ4uR968Q-QDuv';
update content_bodies set title = 'けふの下呂温泉', description = '今日も暑い下呂温泉です。涼しさを求めて、自然に飛騨川へ向かいました。清流を見ていると泳ぎたくなり、深いところは美しい青色で海のようでした。以前見つけられなかった塚田の渡しの碑にたどり着き、飛騨川の大きさを考えると、橋がなければ舟が重要な交通手段になるのも納得です。もし舟が今もあったら、飛騨川を進んでみたいです。暑気払いには温泉が一番！汗を流して快適な夜を迎えましょう。飛騨川と温泉の街、下呂温泉をよろしくお願いいたします！' where id = 'QlCxYGiW0XCeXVU46AA-W';
update content_bodies set title = 'Today in Gero Onsen', description = 'It is another hot day in Gero Onsen. Seeking coolness, I found myself naturally heading towards the Hida River. The clear stream made me want to swim, with its deep blue areas resembling the sea. I was able to reach another monument of Tsukada''s ferry, which I had not discovered before. Considering the size of the Hida River, it makes sense that boats would be an important means of transportation without bridges. If boats still existed, I would love to navigate the river. The best way to beat the heat is with a hot spring! Let''s wash away the sweat and enjoy a comfortable evening. Gero Onsen, a town of the Hida River and hot springs, is truly wonderful!' where id = 'o3qDLHMl77gP0ErcS0V_S';
update content_bodies set title = 'けふの下呂温泉', description = '小川地区にある竹原川に降りてみました。緑の木々が映えていて、せせらぎが耳に心地よいです。水がとてもきれいで、手を入れてみるとひんやりとし、暑い日差しの中の清涼の気分でした。この竹原川は飛騨川にも合流していて、あの大きな流れの一部になっているかと思うと不思議な気分になりました。暑い日が続く今こそ温泉で暑気払い！下呂温泉をよろしくお願いいたします！' where id = 'fJqL2n1Q5ia6cX_ImYAPu';
update content_bodies set title = 'Today at Gero Onsen', description = 'I visited Takehara River in the Ogawa area. The green trees are vibrant, and the sound of the flowing water is pleasant to the ears. The water is very clear, and when I dipped my hands in, it felt cool, providing a refreshing sensation under the hot sun. It''s fascinating to think that this Takehara River merges with the Hida River, becoming part of that larger flow. With the ongoing hot days, now is the perfect time to cool off in the hot springs! I highly recommend Gero Onsen!' where id = 'vFZEBNmmwoqAgK3TG58it';
update content_bodies set title = 'けふの下呂温泉', description = '今日は縄文公園を散策しました。この公園は、縄文時代の集落があった峰一合遺跡、室町時代の森城跡、そして10万年前の噴火に関連する湯ヶ峰が一体となっています。公園内は緑にあふれ、縄文時代と弥生時代の竪穴住居跡が復元されており、内部に入ることもできました。のんびりと散策するには最適な場所です。また、小さな池にはコイが集まり、エサを求めて近づいてきました。古代の人々も温泉を楽しんでいたのかもしれません。そう考えると、今日訪れる温泉にも歴史を感じます。今も昔も温泉の街、下呂温泉をよろしくお願いいたします！' where id = '5wjXvq3k9ymAOnZSnaDsa';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today, I explored Jomon Park, which encompasses the Mineichigo ruins from the Jomon period, the Mori Castle ruins from the Muromachi period, and Yuga Peak, which is linked to the history of Gero Onsen and Gero stone due to a volcanic eruption 100,000 years ago. The park is lush with greenery and features reconstructed pit dwellings from the Jomon and Yayoi periods, allowing visitors to enter them. It is an ideal place for a leisurely stroll. A small pond attracted koi fish, likely hoping for food. One wonders if ancient people also enjoyed the hot springs. Reflecting on this, the hot springs I plan to visit today seem to carry a sense of history as well. Gero Onsen has been a hot spring town both in the past and present!' where id = 'WB4t5QHLWJLYvFLCHcLiu';
update content_bodies set title = 'けふの下呂温泉', description = 'つかの間の雨上がりの下呂温泉の様子をお伝えします。散策路を歩いてみましたが、すぐに雨が降り出しました。飛騨川の水位が上がり、普段は見えているブロックも水の中に隠れてしまいました。梅雨の時期なので仕方がないことですが、太陽が恋しくなります。そんな湿っぽい気分を吹き飛ばすには温泉が最適です。体を温めることで心も温かくなります。梅雨の時期こそ下呂温泉を楽しんでください！' where id = 'JhHNZK38eU3WRG-I4429o';
update content_bodies set title = 'Today’s Gero Onsen', description = 'This is a brief moment after the rain at Gero Onsen. I took a walk along the trail, but it started raining again soon after. The water level of the Hida River has risen, and blocks that are usually fully visible are now submerged. It''s understandable during the rainy season, but I find myself longing for the sun. To shake off this damp feeling, there''s nothing better than a hot spring! Warming the body also warms the heart. Gero Onsen is perfect during the rainy season!' where id = '70FvaIiv0modLvMniUXpJ';
update content_bodies set title = 'けふの下呂温泉', description = 'いでゆ朝市に行ってきました。地元の特産品が手頃な価格で手に入るため、どれを買おうか迷ってしまいます。お店の方も親切で、のんびりとショッピングを楽しむには最適な場所です。朝8時から正午まで営業しており、12月5日まで無休で開催されています。ショッピングの後は温泉に浸かり、手に入れたお土産をどうするか考えるのが最高の楽しみです。温泉とショッピングが楽しめる下呂温泉、ぜひ訪れてみてください！' where id = 'vAuUxBlKJSwwmTyl6pJb-';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I visited the morning market at Gero Onsen, where a variety of local specialties are available at reasonable prices. There are so many tempting items that it''s hard to decide what to buy. The shopkeepers are very friendly, making it a perfect place for leisurely shopping. The market is open from 8 AM to noon and runs without breaks until December 5th. After shopping, soaking in the hot springs while thinking about what to do with the souvenirs is the best part! Gero Onsen is the place for both hot springs and shopping!' where id = 'pU0TrLRY665qNND_4Nee7';
update content_bodies set title = 'けふの下呂温泉', description = 'けふ訪れた合掌村では、手湯と足湯が同時に楽しめました。中に入ると、かえるが番をしている手湯が目に入り、温かいお湯で手をリラックスさせました。次に向かったのは、鷺が番をする合掌の足湯です。広々として屋根もあり、腰を落ち着けて足湯につかりながら、日本の原風景に浸りました。手と足をお湯につけると、全身を温泉につかりたくなり、せっかくなので2か所3か所と入りたいと思いました。温泉めぐりといえばここ、下呂温泉をよろしくお願いいたします！' where id = 'ijVAgrLqlK2z79V6pWSKR';
update content_bodies set title = 'Today at Gero Onsen', description = 'Today, I visited the Gassho Village, where I could enjoy both hand and foot baths simultaneously. Upon entering, I noticed a hand bath being watched over by a frog. The warm water helped me relax my hands, and next, I moved to the foot bath, overseen by a heron. The spacious area had a roof, allowing me to sit comfortably while soaking my feet and immersing myself in the picturesque scenery of Japan''s rural landscape. After enjoying the hand and foot baths, I naturally wanted to experience a full-body soak in the hot springs! Since I was there, I thought it would be great to visit not just one, but two or three places! Gero Onsen is the perfect destination for hot spring hopping!' where id = 'rUH9cH1Nf3GKYog1vupV_';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉は晴れとくもりが交互に訪れています。晴れた日は日差しが強く、帽子が欲しくなるほどです。散策中にビーナスの足湯で一休みし、洋風の腰かけやビーナス像に囲まれて異国情緒を感じました。熱めの足湯で足を温めると、汗を流してさっぱりします。散策を続けた後、再び足湯に浸かり、今度は温泉を楽しむ予定です。ビーナスが常駐する下呂温泉をよろしくお願いいたします！' where id = 'Q5986BQjY-VBM_QZDDCws';
update content_bodies set title = 'Today at Gero Onsen', description = 'Gero Onsen is experiencing alternating sunny and cloudy weather. The sunlight can be quite strong during sunny moments, making a hat desirable. While exploring, I took a break at the Venus foot bath, where the Western-style seating and the Venus statue create a feeling of being in a foreign land. Soaking my feet in the hot foot bath warms me up and refreshes me after sweating. After this, I plan to continue my exploration. Once finished, I will return to the foot bath and then enjoy the hot springs! Please take care of Gero Onsen, where Venus is always present!' where id = 'AgRNw_hLMgCvWls9sd1nS';
update content_bodies set title = 'けふの下呂温泉', description = 'けふの下呂温泉はくもり時々晴れで、過ごしやすい一日です。こんな日は自然に足湯へ行きたくなります。田の神の足湯は市役所の近くにあり、お湯は熱すぎず、のんびりとくつろげるスポットです。足湯には美肌効果があり、むくみの予防やデトックスにも効果があると言われています。足湯でリラックスした後は、温泉に浸かって全身美肌を目指しましょう。美肌と言えば下呂温泉です！' where id = 'Lb8j6O6yC5VHXDMlbEELv';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today in Gero Onsen, the weather is cloudy with occasional sunshine, making it a comfortable day. Such weather naturally draws one to the foot baths. The Tanokami foot bath, located near the city hall, offers a pleasantly warm experience, allowing visitors to relax and unwind. Foot baths are said to have beauty benefits, helping to prevent swelling and promote detoxification. After enjoying the foot bath, it''s a great idea to soak in the hot springs for a full-body beauty treatment, leaving your skin radiant and glowing. When it comes to beautiful skin, Gero Onsen is the place to be!' where id = 'fWEZyzDB8HFCLv_48_OGl';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉はカラッとした快晴に恵まれています。強い日差しは森の木陰で和らぎ、川の近くでは涼しさを感じることができます。澄んだ空気も相まって、リフレッシュした気分になります。感染防止対策はまだ必要ですが、岐阜県の「まん延防止等重点措置」が解除され、少しずつ明るい兆しが見えてきました。さあ、温泉に入りに行きましょう！太陽を浴びながらの露天風呂は最高です！日本三名泉の一つ、下呂温泉をよろしくお願いいたします！' where id = 'FzKIHoy4p6Br3wrupPgwP';
update content_bodies set title = 'Today in Gero Onsen', description = 'Gero Onsen is experiencing clear and sunny weather. The strong sunlight is softened by the shade of the trees in the forest, and near the river, one can even feel a refreshing coolness. The clear air adds to the feeling of rejuvenation. Although infection prevention measures are still necessary, the lifting of Gifu Prefecture''s ''Priority Measures for Prevention of Spread'' indicates a glimmer of hope. Therefore, let''s head to the hot springs right away! Enjoying an outdoor bath under the sun is the best! Gero Onsen, one of Japan''s three famous hot spring areas, is highly recommended!' where id = 'NLaaniEbjVGuvLryWwtxa';
update content_bodies set title = 'けふの下呂温泉', description = '前回の続きとして、デジタルフォトラリーのスポットのひとつ、合掌村へと足を運びました。白川郷などから移築した合掌造りの民家で集落を形成し、日本の原風景を再現しています。資料館、食事処、体験施設等や自然の美しさが広がり、タイムスリップしたような感覚になりました。散策した後は、足湯に入ってほっと一息。そのまま、今度は温泉へ全身をひたしにいきましょう！下呂温泉をよろしくお願いいたします！' where id = '3LeFpr_p7UTErTnbG6Pf0';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Continuing from the previous entry, I visited Gassho Village, one of the spots for the digital photo rally. This village is formed by traditional Gassho-style houses relocated from places like Shirakawa-go, recreating Japan''s original landscape. It features a museum, dining options, experiential facilities, and the beauty of nature, giving a sense of time travel. After exploring, I relaxed in a foot bath. Next, let''s immerse ourselves fully in the hot springs! Please enjoy Gero Onsen!' where id = 'l0htHaiJLxsEASjwAHgwe';
