update content_bodies set title = 'ナイトツアー4k日本語3分', description = 'この動画は、奄美大島で楽しめるエコツアーの一環として「夜間観察（ナイトツアー）」を紹介しています。視聴者は、島で体験できるユニークな夜のアクティビティを垣間見ることができます。' where id = 'JfQG8fLD4MOf9bzscj8n7';
update content_bodies set title = 'Night Tour 4K Japanese 3 Minutes', description = 'This video showcases a part of the eco-tour experience available on Amami Oshima, specifically focusing on the ''Night Observation (Night Tour).'' It offers viewers a glimpse into the unique nighttime activities that can be enjoyed on the island.' where id = 'eo0uN0rzdWr824xWRZILN';
