update content_bodies set title = 'Nemuro City Tourism PR Video: DEEP HOKKAIDO NEMURO - Nature (Summer) Edition', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique experience that differs from the typical Hokkaido charm. It showcases a deep and lesser-known side of Hokkaido, even to its own residents. The video promotes the attractions of Nemuro under the concept of ''DEEP HOKKAIDO NEMURO,'' highlighting its gourmet, nature, and culture.' where id = 'PuWILsoEMSrIIYZ8nUK5J';
update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　プロモーション”体験”編', description = '日本本土最東端に位置する根室は、一般的な北海道の魅力とは異なる独自の魅力を持っています。根室には、北海道民でさえあまり知らないディープな側面が存在します。このプロモーション動画『DEEP HOKKAIDO NEMURO』では、根室のグルメ、自然、文化を通じてその魅力を紹介しています。視聴者に根室ならではの体験を探求することを促す内容となっています。' where id = 'AJbfxy8f0IpyI3jwZyuey';
update content_bodies set title = 'Nemuro City Tourism PR Video: DEEP HOKKAIDO NEMURO - Experience Edition', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique perspective on Hokkaido that differs from the typical attractions. It showcases a deep and lesser-known side of Hokkaido, even to many locals. The promotional video, titled ''DEEP HOKKAIDO NEMURO,'' aims to highlight the region''s charm through its gourmet food, nature, and culture. This initiative invites viewers to explore the distinctive experiences that Nemuro has to offer.' where id = 'LYWtQ4pJhsSOIRs7vBTuv';
update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　ショート”野鳥”編', description = '日本本土最東端に位置する根室は、一般的な北海道の魅力とは異なる独自の体験を提供します。北海道民でさえあまり知らない、深い魅力を持つ根室の観光を『DEEP HOKKAIDO NEMURO』というコンセプトで紹介しています。グルメや自然、文化など、根室の魅力を伝えるこの動画は、観光情報を提供する根室観光NAVIのウェブサイトでも詳しく紹介されています。' where id = 'kIhQ1fE_-i896Ge9I1Vr4';
