update content_bodies set title = '宇和島を巡る', description = 'この動画は宇和島を巡ることについて紹介しています。宇和島の魅力や観光スポットを紹介し、視聴者にその地域の文化や歴史を知ってもらうことを目的としています。' where id = 'mXfMb4WLEtzRxRdp5Py6B';
