update content_bodies set title = '海神楽2018　9月15日　石見神楽（30秒版）', description = '島根県の伝統芸能「石見神楽」は、その華やかな演出が観光客に人気です。大田市温泉津町で開催される「海神楽」では、幻想的なロケーションで石見神楽を楽しむことができます。舞台は海岸に設営され、日本海を背景に迫力満点の演技が繰り広げられます。' where id = 'XJHjOjTvKfHZw3xTP97Z6';
update content_bodies set title = 'Umikagura 2018 - Iwami Kagura (30-second version)', description = 'Iwami Kagura, a traditional performing art from Shimane Prefecture, is popular among tourists for its vibrant performances. The ''Umikagura'' event in Yunotsu Town, Oda City, Shimane Prefecture, offers a chance to enjoy Iwami Kagura in a fantastical setting. The performances take place on a stage set up on the coast, with the Sea of Japan providing a dramatic backdrop.' where id = 'G_vSuoDi6waPHKseiFCQM';
