update content_bodies set title = 'VR宇和島城空撮', description = 'この動画は、VR技術を用いて宇和島城の空撮映像を紹介しています。宇和島城は日本の歴史的な城の一つで、美しい景観と共にその魅力を体験できる内容となっています。VRを通じて、視聴者は城の周囲を360度見渡すことができ、リアルな体験を楽しむことができます。' where id = 'iy8-LxQp7ZahprmwunxTc';
