update content_bodies set title = 'VR九島大橋', description = 'この動画はVR九島大橋について紹介しています。九島大橋は、九州と島を結ぶ重要な橋であり、VR技術を用いてその魅力を体験できる内容となっています。視聴者は、実際に橋を渡る感覚を味わいながら、周囲の景色や構造を楽しむことができます。' where id = 'P_aGmmU5Wt6x1cAgezgA6';
