update content_bodies set title = 'デカ曳山', description = 'この動画はデカ曳山について紹介しています。デカ曳山は、特にその大きさと独特なデザインで知られる伝統的な山車であり、地域の祭りやイベントで重要な役割を果たしています。動画では、デカ曳山の特徴やその歴史、祭りでの使用方法などが詳しく説明されています。' where id = 'BkuKOijv6u7jUSHnFYvWS';
