update content_bodies set title = '砂取り節祭り', description = 'この動画は砂取り節祭りについて紹介しています。砂取り節祭りは地域の伝統行事であり、参加者が砂を取り除くことをテーマにした祭りです。祭りでは、地元の人々が集まり、様々なアクティビティやパフォーマンスが行われます。地域の文化や歴史を感じることができる貴重な機会であり、観光客にも人気があります。' where id = '_7DVQXR_JoZgmiZrVWWDl';
