update content_bodies set title = '砂取り節祭り', description = 'この動画は砂取り節祭りについて紹介しています。砂取り節祭りは地域の伝統行事であり、参加者が砂を取り除くことを通じて、地域の文化や歴史を再確認する機会となっています。祭りでは、様々なパフォーマンスやイベントが行われ、地域の人々が一堂に会し、交流を深める場ともなっています。' where id = 'Hk9uN9HfpYUp18Tu-hOXh';
