update content_bodies set title = '波の花と垂水の滝', description = 'この動画では、波の花と垂水の滝について紹介しています。波の花は、海の波が風によって泡立ち、白い花のように見える現象で、美しい自然の一部です。また、垂水の滝は、その名の通り水が垂れ落ちる様子が特徴的で、訪れる人々に感動を与えます。動画では、これらの自然の美しさを映し出し、観る人に癒しを提供しています。' where id = '_EMf8GseoiO_z1j46-EjO';
