update content_bodies set title = 'ふるさと祭り東京2011', description = '東京ドームで開催された「ふるさと祭り東京2011」では、飯田燈籠祭りが披露されました。この祭りは地域の文化や伝統を紹介するイベントであり、多くの来場者が集まりました。飯田燈籠祭りは、特に美しい灯籠が特徴で、訪れた人々に感動を与えました。' where id = 'RTdjiQoQIru5gs_ru5wsX';
update content_bodies set title = 'Furusato Festival Tokyo 2011', description = 'The ''Furusato Festival Tokyo 2011'' was held at Tokyo Dome, where the Iida Lantern Festival was showcased.' where id = 'LeHxYCw96OIaiow9fEx3B';
update content_bodies set title = 'ふるさと祭り東京2011②', description = '東京ドームで開催された「ふるさと祭り東京2011」では、飯田燈籠祭りが披露されました。この祭りは地域の伝統や文化を紹介するイベントであり、多くの来場者が集まりました。飯田燈籠祭りは、特に美しい灯籠が特徴で、訪れた人々に感動を与えました。' where id = 'Bi4poJ7Jotv10lOCxE5sb';
