update content_bodies set title = 'キャンピングカーでの最後の一週間 - 日本のバンライフ', description = '日本でのバンライフは、美しい田舎を見たり、素晴らしい日本の人々と出会ったりする機会を与えてくれました。' where id = 'yHjgW-NLwR_qkRvPnoyad';
update content_bodies set title = 'Our Last Week in the Campervan - Van Life Japan', description = 'Van life in Japan has provided us with the opportunity to explore stunning countryside and connect with wonderful Japanese people.' where id = 'yVDw1d-HuH_4km2DCAhIQ';
update content_bodies set title = '長崎、過去と現在。日本の長崎を旅行するのはどんな感じですか？', description = '長崎は、年月を経て大きな回復と変革を遂げてきました。現在、長崎は文化のユニークな融合として存在し、日本の中で独自のアイデンティティを示しています。観光名所には、歴史的な過去を反映した原爆資料館や、伝統的な温泉体験ができる福の湯温泉があります。旅行者は、長崎の豊かな文化遺産と現代の発展を探索し、この魅力的な目的地を楽しむことができます。' where id = 'TpZ5WBmEAW2zBuSxAmMvC';
update content_bodies set title = 'Nagasaki, then and now. What is it like to travel to Nagasaki, Japan?', description = 'Nagasaki has undergone significant recovery and transformation over the years. Today, it stands as a unique blend of cultures, showcasing its distinct identity within Japan. The city offers various attractions, including the Atomic Bomb Museum, which reflects on its historical past, and Fukunoyu onsen, a traditional hot spring experience. Travelers can explore the rich cultural heritage and modern developments that make Nagasaki a fascinating destination.' where id = '9kpAn-UDvVdA72Kysf7xP';
update content_bodies set title = 'バンライフ日本 - 鹿児島の火山に滞在', description = 'このエピソードでは、キャンピングカーの旅で鹿児島を訪れます。鹿児島は美しい火山で知られています。火山は少し怖い存在ですが、素晴らしいハイキングの機会を提供してくれます。私たちは桜島を訪れ、火山の海岸公園や足湯を楽しみ、霧島山脈や韓国岳にも足を運びます。寒い冬の中で、しんゆ温泉でリラックスすることで、バンライフや温泉体験、自然の美しさを満喫します。このユニークな地域の魅力を一緒に体験しましょう。' where id = '69zysHlNzDnPndN4EW1OE';
update content_bodies set title = 'Van Life Japan - Staying on a Volcano in Kagoshima, Japan', description = 'In this episode of our camper van journey across Japan, we explore Kagoshima, known for its stunning volcanoes. While volcanoes can be intimidating, they offer fantastic hiking opportunities. We visit Sakurajima, where we enjoy the volcanic shore park and a footbath, and venture into the Kirishima mountains, including Mount Karakuni. The experience is enriched by relaxing at the Shinyu hot spring, providing a perfect contrast to the cold winter weather. Join us as we embrace the wonders of van life, onsen experiences, and the beauty of nature in this unique region.' where id = 'oH8447yE-Tc3OMoP78YI2';
update content_bodies set title = '日本最南端の無料キャンプ - 鹿児島、九州', description = '私たちは本土日本の最南端に到達しました！近くには無料のキャンプ場があり、キャンプ道具を取り出して、温かい冬の食事と星空の下での睡眠を楽しむ予定でした。しかし、少しキャンプの失敗があり、結局バンで寝ることになりました。それでも、鍋を作ることは素晴らしい体験で、冬にもかかわらず、天候はほとんど持ちこたえてくれました。' where id = '3_yQeOC3QJNN2oZUZm7J-';
update content_bodies set title = 'Free Camping at Japan''s Most Southern Point - Kagoshima, Kyushu', description = 'The adventure took us to the southernmost point of mainland Japan, where we found a free campsite. We set up our camping gear for a night filled with warm winter food and stargazing. However, we faced a camping mishap and ended up sleeping in our van instead. Despite this setback, cooking nabe was a delightful experience, and the weather was mostly favorable, allowing us to enjoy our winter outing.' where id = 'eQgKKkMW48zarkmdHvn_s';
update content_bodies set title = '冬の日本で車中生活をしながら暖を取る方法 (バンライフ)', description = '冬の日本でのバンライフは少し不快になることがあります。この動画では、九州をキャンピングカーで旅しながら、まず大分の歴史的な岡城跡を訪れ、その後、阿蘇九重国立公園の素晴らしい火山クレーターである阿蘇山を見に行きます。最後に、無料のキャンプ場である辻川原公園で一晩を過ごし、車中生活をしながら日中と夜間に暖を取るためのヒントを共有します。動画には松島ビーチやキャンプ道具、カメラ機材の紹介も含まれています。' where id = 'nsPSKzUkx7nKeyMHuoLc3';
update content_bodies set title = 'How We Keep Warm, Living in a Car in Winter Japan (Van Life)', description = 'Van life during winter in Japan can be challenging. This video follows our journey in a campervan through Kyushu, where we explore the historic Oka Castle Ruins in Oita and the stunning volcanic crater of Mount Aso in Aso-Kuju National Park. We also spend the night at Tsujikawara Park, a free campsite, where we share our tips for staying warm both during the day and at night while living in a van. The video includes various locations such as Matsushima beach and highlights our camping gear and camera equipment.' where id = 'D_jdqF6OoRM0GSeg1WAvn';
update content_bodies set title = '日本の秘湯 - 九州・別府の温泉 (バンライフ)', description = '別府は日本で最も有名な温泉地の一つで、美しい自然に囲まれた無料の秘湯が点在しています。この動画では、男女混浴の温泉を2つ紹介しており、どちらも硫黄の豊富な温泉です。紹介されている温泉は「鍋山の湯」と「蛇紋の湯」で、別府の温泉の美しさと静けさを体験できます。' where id = 'GUEH0b27fnEuJnhSS-_aa';
update content_bodies set title = 'Secret Hot Springs in Japan - Onsen in Beppu, Kyushu (Van Life)', description = 'Beppu, a renowned onsen town in Japan, is home to hidden outdoor hot springs that are free to access and set in stunning natural surroundings. The video showcases two mixed-gender hot springs, both rich in sulfur, providing a unique bathing experience. The locations featured are Nabeyama no Yu and Hebinyu, highlighting the beauty and tranquility of Beppu''s hot springs.' where id = 'RpRSdweBWpLr-reZuYDdw';
update content_bodies set title = '日本での車生活、私たちの食事 - バンライフと車中泊', description = '日本で車に住むことは、特に食事に関して独特の挑戦があります。この動画では、中国地方を旅しながらの私たちの食事ルーチンを紹介しています。季節の果物である柿や、コンビニのスナック、スーパーマーケットの定番である日本の弁当などを取り上げています。この内容は、バンライフの体験を楽しみながら、どのように食生活を適応させているかを示しています。' where id = 'AV6r8ZX0DJi-pwMwUV2mD';
update content_bodies set title = 'What We Eat, Living in a Car in Japan - Van life and Car Camping', description = 'Living in a car in Japan presents unique challenges, especially when it comes to food. This video showcases our eating routine while traveling through the Chugoku region. We highlight seasonal fruits like persimmons, snacks from convenience stores, and traditional Japanese bento boxes from supermarkets. The content provides insights into how we adapt our diet while embracing the van life experience.' where id = 'czgu-i4DfdTtB316001H6';
update content_bodies set title = '富士山でのバンライフ', description = '秋の富士山の麓で車中生活をすることは、寒さと美しさが共存する特別な体験でした。私たちは、山中湖にも足を運び、自転車をレンタルして周辺を探索しました。説明文には、山中湖や自転車レンタル、バンレンタルに関する旅行情報のリンクが含まれています。また、キャンプ用具やカメラ機材のリストも掲載されています。クリエイターはInstagramでの交流を呼びかけており、一部のリンクはアフィリエイトリンクであることを明記しており、購入者に追加費用はかからない形で小さな手数料を得る可能性があることを伝えています。' where id = 'zI0Mpt85DklwocT3lU9_M';
update content_bodies set title = 'Van Life at Mount Fuji', description = 'Living in a van at the base of Mount Fuji during the fall season was a unique experience, combining the beauty of nature with the challenges of cold weather. The journey included a visit to Lake Yamanaka, where we rented bikes to explore the area. The description provides links to travel information, including details about Lake Yamanaka, bike rentals, and van rentals. Additionally, it lists camping gear and camera equipment used during the trip. The creators invite viewers to connect with them on Instagram and mention that some links may be affiliate links, which could earn them a small commission at no extra cost to the buyer.' where id = 'C7RGn7qcvF9_8qqm7eyEP';
update content_bodies set title = '都市でのバンライフの現実', description = 'この動画では、日本の都市で数日間車中泊をしながらビザや日本の免許を申請する際の困難について語っています。彼らは、実際に屋根のある住まいがあるときは日本の都市での生活を楽しんでいますが、都市での車中泊は少し難しいと感じています。この動画では、バンライフの現実やそのデメリットについても触れています。' where id = 'c8pZ-WhvtCo0Va5vMlK9s';
update content_bodies set title = 'In the City - Realities of Van Life', description = 'The video discusses the challenges of living in a car while staying in a city in Japan for a few days to apply for visas and Japanese licenses. Although the creators enjoy living in Japanese cities when they have proper accommodation, they found it difficult to manage van life in an urban environment. The video highlights some of the realities and downsides of this lifestyle.' where id = 'er-heeItNZSHbPW3XI0wD';
update content_bodies set title = '日本の田舎を探る：北海道黒松内の夏', description = 'この動画では、北海道の黒松内での夏の日本の田舎の様子を紹介しています。' where id = '5-RzpNU5IMEyiMHb3aC4g';
update content_bodies set title = 'Exploring the Japanese Countryside: Summer In Kuromatsunai - Hokkaido, Japan', description = 'This video introduces the summer countryside of Japan, specifically in Kuromatsunai, Hokkaido.' where id = 'YCcxFMnKk1_HT6QvsdqEs';
update content_bodies set title = 'しだれ梅が見事な津市の結城神社へ行ってきました', description = '三重県津市の藤方に位置する結城神社は、しだれ梅の名所として知られています。美しいしだれ梅を楽しむために訪れました。詳細については、こちらのリンクをご覧ください。https://www.kankomie.or.jp/report/detail_202.html' where id = 'mF_Ltf5-eAAXEhsiuHAak';
update content_bodies set title = 'Visit to Yuki Shrine in Tsu City, Noted for Its Beautiful Weeping Plum Trees', description = 'I visited Yuki Shrine, a famous spot for weeping plum trees located in Fujikata, Tsu City, Mie Prefecture. For more details, visit https://www.kankomie.or.jp/report/detail_202.html' where id = '1aarCCpNLBXEmB2lAY8xx';
update content_bodies set title = '鈴鹿サーキット　新アトラクション「ぶんぶんばち」が登場', description = '鈴鹿サーキットに新しいアトラクション「ぶんぶんばち」が登場しました。このサーキットは楽しい発見がいっぱいで、新たに「チララのハローガーデン」もオープンしました。詳細については、提供されたリンクをご覧ください。' where id = 'mYBfbGfbccbjDlyTKEyWS';
update content_bodies set title = 'New Attraction ''Bunbunbachi'' at Suzuka Circuit', description = 'Suzuka Circuit is introducing a new attraction called ''Bunbunbachi''. The venue is filled with fun discoveries, and a new area named ''Chirara''s Hello Garden'' has also opened. For more details, visit the provided link.' where id = 'jAi91SZHdFGY9gEAfxoMK';
update content_bodies set title = '鳥出神社の鯨船行事', description = 'ユネスコ無形文化遺産に登録された鯨船山車を勇壮に繰り動かし、一進一退の攻防の末、鯨を仕留めるという、地上で捕鯨の様子を再現する全国的にも珍しい民俗行事です。１４日には町練り、１５日には鳥出神社への練り込みが行われます。詳細についてはHP「観光三重」をごらんください。' where id = 'cliyRyJl6RJhijYoAk8m-';
update content_bodies set title = 'Whale Boat Festival at Toride Shrine', description = 'The Whale Boat Festival, registered as an Intangible Cultural Heritage by UNESCO, features a grand display of whale boats in a unique folk event that reenacts the whaling process on land. Participants engage in a fierce back-and-forth struggle to capture a whale. The festival includes a town parade on the 14th and a procession to Toride Shrine on the 15th. For more details, please visit the ''Kankomie'' website.' where id = 'XRpEf1ew0SLRiCTi_-x3i';
update content_bodies set title = 'ナガシマスパーランド　ホワイトサイクロン最前列（三重県桑名市）【Full HD 1080p】', description = '絶叫コースターの聖地であるナガシマスパーランドで、ホワイトサイクロンの最前列に乗る体験をしました。ホワイトサイクロンは2018年1月28日に営業を終了したことに注意が必要です。撮影は特別な許可を得て行われ、映像には2016年度津クイーンの片岡優奈さんが登場します。また、ナガシマスパーランドの人気アトラクションや周辺の観光施設を紹介する詳細なレポートも含まれています。さらに、国内初のハイブリッドコースター「白鯨（HAKUGEI）」や「嵐（ARASHI）」に関する記事もあり、ナガシマリゾートの特集では、ジャンボ海水プールやイルミネーション、アウトレットパークなどの人気スポットが紹介されています。' where id = 'dVNv87Dt9q0O9JBRPi4L1';
update content_bodies set title = 'Nagashima Spa Land - Front Row of White Cyclone (Kuwana City, Mie Prefecture) [Full HD 1080p]', description = 'I experienced the front row of the White Cyclone at Nagashima Spa Land, known as the holy land of thrill rides! Please note that the White Cyclone ceased operations on January 28, 2018. The filming was done with special permission. The video features Yuna Kataoka, the 2016 Tsu Queen. The report also includes a comprehensive guide to Nagashima Spa Land, highlighting popular attractions and nearby facilities worth visiting. For more information, you can check out various articles about other attractions in the area, including the hybrid coaster HAKUGEI and the ARASHI ride, as well as a special feature on Nagashima Resort, which includes a water park, illumination displays, and shopping outlets.' where id = 'W_dybKtpy7-0bkvf1R_Qg';
update content_bodies set title = 'ナガシマスパーランド「嵐」（ARASHI）：予想不可能な動きを見せる4Dスピンコースター', description = 'ナガシマスパーランドに新しいジェットコースター『嵐（ARASHI）』が登場しました。この4Dスピンコースターは座席の制御がなく、動きがまったく予想できません。日本初の常識を覆す斬新で予想不可能な動きを体感できる「嵐」をぜひお楽しみください。詳しいレポートでは、津クイーンの感想や動画も紹介されています。' where id = 'tNzCIGxIE3UM52frR7BGi';
update content_bodies set title = 'Nagashima Spa Land ''ARASHI'': Unpredictable Movements of a 4D Spin Coaster', description = 'Nagashima Spa Land has introduced a new roller coaster called ''ARASHI''. This 4D spin coaster features no seat control, making its movements completely unpredictable. Experience the innovative and surprising motions of ''ARASHI'', which defy conventional expectations in Japan. For a detailed report, check out the article featuring thrilling experiences and feedback from the 2016 Tsukui Queen.' where id = 'oA36PAgMyKvcvql6M21RC';
update content_bodies set title = '高校生レストラン「まごの店」プロモーション動画', description = '多気町に位置する高校生レストラン「まごの店」のプロモーション動画です。この動画は三重県観光キャンペーン中南勢地域部会によって制作されました。' where id = 'tqvmLP4SDsz8Gy6TI9-wo';
update content_bodies set title = 'High School Student Restaurant ''Mago no Mise'' Promotional Video', description = 'This is a promotional video for ''Mago no Mise'', a high school student restaurant located in Taki Town. The video was created by the Mie Prefecture Tourism Campaign Nansei Regional Committee.' where id = 'Ym_1xyIKZwfpKVVODzro8';
update content_bodies set title = 'きいながしま港市', description = '紀伊長島港は県内でも有数の水揚げ高を誇り、新鮮な鮮魚や干物、特産のとらまき、みかんなど、郷土の自慢品が揃っています。詳細については、観光三重のHPをご覧ください。' where id = 'pcP0BroCMIk5vRpTsAfXM';
update content_bodies set title = 'Kiinagashima Port City', description = 'Kiinagashima Port boasts one of the highest fish landing volumes in the prefecture, offering a variety of local specialties such as fresh seafood, dried fish, toramaki, and mikan oranges. For more details, please visit the Mie Prefecture tourism website.' where id = 'hwNvlbdw8l7gA6QPZGMpC';
update content_bodies set title = '横山展望台', description = '横山展望台では、リアス海岸特有の複雑な海岸線と60の島々が織りなす英虞湾の絶景を楽しむことができます。展望台へは多くの遊歩道が整備されており、訪れる人々はゆっくりと景色を眺めながら散策することができます。詳細については、観光三重の公式HPをご覧ください。' where id = 'rX1jNijf5-TZQe-SBfSs-';
update content_bodies set title = 'Yokoyama Observatory', description = 'Yokoyama Observatory offers breathtaking views of Ago Bay, characterized by its unique ria coastline and the intricate arrangement of 60 islands. There are numerous walking paths leading to the observatory, allowing visitors to leisurely stroll and enjoy the scenery. For more details, please visit the official tourism website of Mie Prefecture.' where id = 'd8vaxL4eBCJxkU4k9e1en';
update content_bodies set title = '御在所ロープウエイ', description = '春の御在所岳では新緑が芽吹き、アカヤシオやシロヤシオなど多くの花が咲き誇ります。登山を楽しむこともできますが、ロープウェイを利用して山頂まで登ることも可能です。山頂では、ふもとでは見られない山ならではの花々を間近で楽しむことができる山上公園での散歩がオススメです。' where id = '7FxLMZRBSaaL2b-ay5WXP';
update content_bodies set title = 'Gozaisho Ropeway', description = 'In spring, Gozaisho Mountain is adorned with fresh greenery and a variety of flowers, including Akayashio and Shiroyashio. Visitors can enjoy hiking or take the ropeway to the summit, where they can experience the unique mountain flowers up close in the mountaintop park. This is highly recommended for those looking to appreciate the natural beauty that cannot be seen at the foot of the mountain.' where id = 'oJ00ZCPBkt2GtsA3uO6gb';
update content_bodies set title = '三反帆', description = '風の力だけで進む三反帆（川船）に乗り、水の流れる音や鳥の羽ばたく音を聞きながら、自然と一体となった感覚で熊野川をゆっくりと巡る体験を楽しむことができます。詳細については、観光三重のHPをご覧ください。' where id = 'cUJLiHfRIxU8_-Q4Wb3Y3';
update content_bodies set title = 'Sanpanh', description = 'Experience a leisurely journey along the Kumano River on a Sanpanh (a traditional riverboat) that moves solely by the power of the wind. Enjoy the sounds of flowing water and birds flapping their wings, creating a sense of unity with nature. For more details, please visit the Mie Prefecture tourism website.' where id = 'RplnJQX-ECyNQPkAbfBPc';
update content_bodies set title = '湯元山荘湯ノ口温泉', description = '湯元山荘湯ノ口温泉は、豊富な湯量と良質な源泉かけ流しの温泉が特徴で、体の芯まで温まることができます。温泉を楽しんだ後は、熊野杉を使用した温泉棟で木の香りに癒されることができます。また、入鹿温泉ホテル瀞流荘からトロッコ電車での湯めぐりもおすすめです。' where id = 'dagLLn9nUY9-OwgW7ecYl';
update content_bodies set title = 'Yumoto Sanso Yunokuchi Onsen', description = 'Yumoto Sanso Yunokuchi Onsen offers abundant hot spring water and high-quality, flowing natural hot springs that warm you to the core. After enjoying the soothing experience, relax in the hot spring building made from Kumano cedar, which provides a comforting wooden aroma. A recommended way to explore the area is by taking a trolley train from Iruka Onsen Hotel Toriryuso.' where id = 'Gd9ffkfDEWETGdtDBk_a-';
update content_bodies set title = '夢古道おわせ', description = '夢古道おわせは、尾鷲のお母ちゃんたちがもてなすバイキングです。ここでしか味わえない尾鷲の旬の魚や新鮮な野菜を使った料理が楽しめるほか、元気いっぱいのお母ちゃんたちとのふれあいも魅力の一つです。' where id = 'sOQ7Y_4Bon-lUzk9G3bGH';
update content_bodies set title = 'Yume Kodou Owase', description = 'Yume Kodou Owase offers a buffet hosted by the mothers of Owase. The restaurant features seasonal fish and fresh vegetables unique to Owase, providing a delightful culinary experience. Additionally, the warm interactions with the energetic mothers add to the charm of the place.' where id = 'JvnV7WP18Xj4gc-QLkJlI';
update content_bodies set title = 'イベント情報紙「観光三重」98号特集　ほのぼの春の自然散歩', description = '三重県観光連盟が発行するイベント情報紙「観光三重」の98号特集では、ほのぼのとした春の自然散歩に関連するスポットが紹介されています。詳細については、観光三重の公式HPをご覧ください。' where id = 'Tp9e_CCRr6vQagbfG9ROp';
update content_bodies set title = 'Event Information Paper ''Kankou Mie'' Special Edition 98: Heartwarming Spring Nature Walks', description = 'This is a feature on spots introduced in the special edition 98 of the event information paper ''Kankou Mie'', published by the Mie Prefectural Tourism Federation, focusing on heartwarming spring nature walks. For more details, please visit the Kankou Mie website.' where id = '62jte3v1MAtBrjiAaHlD2';
update content_bodies set title = 'ユニバーサル・スタジオ・ジャパンのスーパーニンテンドーワールドにあるかわいいヨッシーグッズ', description = 'ユニバーサル・スタジオ・ジャパンのスーパーニンテンドーワールドで手に入るかわいいヨッシーグッズを紹介します。このセクションでは、パーク内で見つけられるさまざまなヨッシーをテーマにした商品が取り上げられており、ヨッシーのファンにとって必見のスポットです。商品は子供から大人まで楽しめるアイテムが揃っており、誰もがお気に入りのキャラクターの一部を持ち帰ることができます。ユニバーサル・スタジオ・ジャパンやスーパーニンテンドーワールドを訪れる際の役立つリンクも提供されています。' where id = 'vNX_KadGm0MmsjqzV6TsN';
update content_bodies set title = 'ALL THE CUTE Yoshi Merchandise at Super Nintendo World inside Universal Studios Japan!', description = 'Explore the adorable Yoshi merchandise available at Universal Studios Japan''s Super Nintendo World. This section highlights various Yoshi-themed products that fans can find in the park, making it a must-visit for Yoshi enthusiasts. The merchandise includes a range of items that appeal to both children and adults, ensuring that everyone can take home a piece of their favorite character. For more information on visiting Universal Studios Japan and Super Nintendo World, useful links for tickets and guides are provided.' where id = 'ohdZmLDx5HulG1bca4y7T';
update content_bodies set title = '東京ディズニーランド＆ディズニーシーを訪れるのに最適な時期 | 月ごとの詳細', description = 'このガイドでは、東京ディズニーランドとディズニーシーを訪れるのに最適な時期と最悪な時期を月ごとに詳しく分析しています。著者は、年間を通じてパークを訪れた経験をもとに、天候、イベント、休日、混雑状況などの要素についての洞察を共有しています。訪問者が旅行を効果的に計画し、パークを最大限に楽しむための情報が提供されています。また、チケット、混雑カレンダー、季節イベントに関する便利なリンクも含まれており、ディズニーファンにとって包括的なリソースとなっています。' where id = 'iU4GGkEHzdw7JdOL1lSSB';
update content_bodies set title = 'The BEST Times to Visit Tokyo Disneyland & DisneySea | Month by Month Breakdown', description = 'This guide provides a detailed month-by-month analysis of the best and worst times to visit Tokyo Disneyland and DisneySea. The author, who has visited the parks throughout the year, shares insights on factors such as weather, events, holidays, and crowd levels. The content is designed to help potential visitors plan their trips effectively, ensuring they can enjoy the parks to the fullest. Useful links for tickets, crowd calendars, and seasonal events are also provided, making it a comprehensive resource for Disney fans.' where id = 'K2u46koDVtB6052cEOB4s';
update content_bodies set title = '東京ディズニーランド：2023年まで待つべき理由', description = '東京ディズニーランドへの旅行を計画しているなら、2023年まで待つことを検討してみてください。その理由は主に3つあります。まず、パークの運営が常に変化しており、体験に影響を与える可能性があります。次に、2023年は東京ディズニーリゾートの40周年であり、特別なイベントやお祝いが行われるでしょう。最後に、東京ディズニーシーの新エリア「ファンタジースプリングス」の拡張が予定されており、パークの魅力がさらに増すことが期待されます。これらの要素から、2023年は訪れるのに最適な時期と言えるでしょう。' where id = 'I6f8iLYPLw2y8IfuKVJxu';
update content_bodies set title = 'Tokyo Disneyland: Why You Should Wait Until 2023 to Visit Japan', description = 'If you''re planning a trip to Tokyo Disneyland, consider waiting until 2023. There are three main reasons for this recommendation. First, the operations of the parks are constantly changing, which could affect your experience. Second, 2023 marks the 40th anniversary of Tokyo Disney Resort, likely bringing special celebrations and events. Lastly, the expansion of Tokyo DisneySea with the new ''Fantasy Springs'' area is set to enhance the park''s offerings. These factors make 2023 an ideal time to visit.' where id = 'SD7kqIoymbkqcpudfaUUh';
update content_bodies set title = '東京、日本のキングダムハーツカフェ | フード＆グッズVLOG', description = '東京と大阪で期間限定オープンしているキングダムハーツのポップアップカフェを訪れます。このカフェでは、特別なフードメニューや限定のグッズが楽しめます。ポップアップの場所は、東京の渋谷ボックスと大阪の梅田ボックスが2021年12月11日から2021年1月11日まで、そして新宿のアーティナと秋葉原・大阪のスクウェア・エニックスカフェが2021年1月16日から2021年3月12日までオープンします。動画では、フードメニュー、記念コースター、購入可能なグッズについて紹介し、キングダムハーツをテーマにした食べ物を試食した体験をお伝えします。詳細は提供されたリンクをチェックしてください。' where id = 'B-zQ87ca1GQ2sYeWVO2KM';
update content_bodies set title = 'Kingdom Hearts Cafe in Tokyo, Japan | Food & Merchandise VLOG', description = 'Join me as I explore the Kingdom Hearts pop-up cafe in Tokyo, Japan, which is available for a limited time in both Tokyo and Osaka. The cafe features a unique food menu and exclusive merchandise. The pop-up locations include Shibuya Box in Tokyo and Umeda Box in Osaka from December 11 to January 11, 2021, and Artina in Shinjuku and Square Enix Cafe in Akihabara and Osaka from January 16 to March 12, 2021. The video covers the food offerings, souvenir coasters, and merchandise available for purchase, along with my personal experience trying the Kingdom Hearts-themed food. For more information, check out the provided links.' where id = 'KhLHTBxySb5JcSE4cxush';
update content_bodies set title = '東京ディズニーランド商品2020ツアー | 美女と野獣 + ベイマックス', description = 'この動画では、2020年の東京ディズニーランドとディズニーシーで販売されている商品を網羅的に紹介しています。イースター、東京ディズニーリゾートの37周年、夏のグッズ、ハロウィンやクリスマスなどの季節イベントに関連する商品が取り上げられています。特に「美女と野獣」や「ベイマックス」に関連するアイテムが目を引きます。また、東京ディズニーパスケースや東京ディズニーランドの拡張に関する情報も含まれています。旅行を計画している方のために、旅行ガイドや商品リンクも提供されています。' where id = 'DrmnP3uu3wvj6w0JWnGB4';
update content_bodies set title = 'Tokyo Disneyland Merchandise 2020 Tour | Beauty and the Beast + Baymax', description = 'This video provides a comprehensive tour of the merchandise available at Tokyo Disneyland and DisneySea in 2020. It covers various themes and events, including Easter, the 37th anniversary of Tokyo Disney Resort, summer merchandise, and seasonal events like Halloween and Christmas. Specific highlights include items related to ''Beauty and the Beast'' and ''Baymax.'' The video also features information on Tokyo Disney Pass cases and the expansion of Tokyo Disneyland. For those planning a trip, additional resources such as a travel guide and merchandise links are provided.' where id = 'mfQVVcIlbrs6Yb5cekd6j';
update content_bodies set title = '任天堂ストア日本のグッズ購入 | 渋谷、東京のショッピング', description = 'この動画では、東京・渋谷にある任天堂TOKYOストアでのグッズ購入を紹介しています。合計150ドル相当のアイテムが含まれており、どうぶつの森、スーパーマリオ、ポケモン、カービィなどの人気フランチャイズのグッズが揃っています。ストアでのショッピング体験についての情報が提供されており、ストアの位置情報、グッズリスト、東京旅行ガイドへのリンクも含まれています。また、割引オファー付きのVPNサービスも紹介されています。' where id = 'dkc-2XXN37rt754hyrSy7';
update content_bodies set title = 'Nintendo Store Japan Merchandise Haul | Shibuya, Tokyo Shopping', description = 'This video showcases a merchandise haul from the Nintendo TOKYO Store located in Shibuya, Tokyo, highlighting a total of $150 worth of items. The haul features various merchandise from popular franchises such as Animal Crossing, Super Mario, Pokemon, and Kirby. The video provides insights into the shopping experience at the store and includes links to the store''s location, a merchandise list, and a Tokyo travel guide. Additionally, it promotes a VPN service with a discount offer.' where id = '1f4X2aDWR7fkX1CiZiv43';
update content_bodies set title = '2020年の東京ディズニーランド訪問 | 再開後のパークの運営', description = '著者は東京ディズニーランドの再開初日に訪れ、これまでで最も空いているパークを体験しました。動画では、再開後のパークの運営について、ソーシャルディスタンスの確保、体温チェック、キャラクターグリーティングなどの様子が紹介されています。また、新しい「美女と野獣」エリアや飲食オプション、商品販売についても触れています。アトラクションの待ち時間については、長い列ができていても実際の待ち時間は短いことが強調されています。安全対策やこの時期のパーク訪問の全体的な体験についても詳しく説明されています。' where id = 'Rsnek_kVzZ3hG-8EZLzD1';
update content_bodies set title = 'Visiting Tokyo Disneyland in 2020 | How the park works since reopening', description = 'The author visited Tokyo Disneyland on its reopening day, noting it was the least crowded he had ever seen the park. The video covers various aspects of the park''s operations post-reopening, including social distancing measures, temperature checks, and character greetings. It highlights the new Beauty and the Beast area, dining options, and merchandise availability. The author discusses wait times for attractions, emphasizing that while queues may appear long, actual wait times are short. The video also provides insights into safety measures and the overall experience of visiting the park during this time.' where id = '0TtYi0w8OPmrwzueeYMNs';
update content_bodies set title = '東京ディズニーランドが再オープン！ | 知っておくべきこと', description = '東京ディズニーランドとディズニーシーは、2020年7月1日に再オープンすることを発表しました。これは、ディズニーパークの中で最後の再オープン日程の発表となります。この発表では、パークを訪れる予定の方々に必要な情報が提供されています。詳細については、再オープンガイドや東京ディズニーの旅行ガイドへのリンクを参照してください。コンテンツは、アジアのディズニーパークの旅行計画を専門とするクリスによって管理されており、訪問者が旅行のための最新かつ正確な情報を得られるようにしています。' where id = 'ov8ISsnMsJcqFinrBovH4';
update content_bodies set title = 'Tokyo Disneyland IS REOPENING! | What you need to know', description = 'Tokyo Disneyland and DisneySea are set to reopen on July 1, 2020, making them the last of the Disney Parks to announce reopening dates. This announcement provides essential information for visitors planning to return to the parks. For more details, you can visit the provided links, which include a full reopening guide and a travel guide for Tokyo Disney. The content is managed by Chris, who specializes in trip planning for Disney Parks in Asia, ensuring that visitors have the most accurate and current information for their trips.' where id = 'IPMY4RENcnIt6JcElnboE';
update content_bodies set title = '東京で『名探偵ピカチュウ』を観る + グッズ紹介！', description = 'この動画では、日本で『名探偵ピカチュウ』を観るための映画館訪問と、関連グッズの紹介が行われています。制作者は映画鑑賞の体験を共有し、購入した様々なアイテムを紹介しています。内容は『名探偵ピカチュウ』のファンや日本文化、グッズに興味のある人々を対象としています。また、日本旅行やアジアのディズニーパーク訪問のためのリソースも提供されており、旅行ガイドや東京ディズニーランドの電子書籍へのリンクが含まれています。' where id = '3_ozPEI_k6zR9uHuFGi6I';
update content_bodies set title = 'Watching Detective Pikachu in Tokyo, Japan + MERCH HAUL!', description = 'This video showcases a trip to the movies in Japan to watch Detective Pikachu, along with a merchandise haul. The creator shares their experience of watching the film and highlights various items purchased related to the movie. The content is aimed at fans of Detective Pikachu and those interested in Japanese culture and merchandise. Additionally, resources for planning trips to Japan and visiting Disney parks in Asia are provided, including links to travel guides and an e-book for Tokyo Disneyland.' where id = 'J0dz6skDciKi-1ayRBpvQ';
update content_bodies set title = '東京ディズニーランド ハロウィン 2018 ガイド | 日本旅行ガイド', description = '東京ディズニーランドと東京ディズニーシーでのハロウィンイベントは2018年10月31日まで開催されています。この期間中、特別なグッズやフードがハロウィンのために限定販売されます。詳細な情報は、TDR Explorerが提供するハロウィンガイドを参照することができます。また、TDR Explorerは東京ディズニーランド訪問の計画に役立つ電子書籍も提供しており、最新の情報や旅行のヒントをゲストに提供しています。' where id = 'eJ6luMLKosxXhMV2JCwI9';
update content_bodies set title = 'Tokyo Disneyland Halloween 2018 Guide | JAPAN TRAVEL GUIDE', description = 'The Halloween event at Tokyo Disneyland and Tokyo DisneySea runs until October 31, 2018. During this period, special merchandise and food items are available exclusively for the Halloween celebration. For more detailed information, visitors can refer to the Halloween guide provided by TDR Explorer. Additionally, TDR Explorer offers an e-book for planning visits to Tokyo Disneyland, ensuring that guests have access to the latest information and tips for their trip.' where id = 'iiLIvOUfghR67-_VxTldd';
update content_bodies set title = '伊賀流忍者博物館', description = '伊賀流忍者博物館は、伊賀上野城や俳聖殿などの名所が多い上野公園内に位置しています。ここでは、忍者やくノ一が忍者屋敷の仕掛けやどんでん返しを案内してくれます。また、忍術体験広場では迫力の忍術実演ショーも楽しむことができます。' where id = '4IRGUWRHiPaQHQSzABxTA';
update content_bodies set title = 'Iga-ryu Ninja Museum', description = 'The Iga-ryu Ninja Museum is located within Ueno Park, which is home to many famous sites such as Iga Ueno Castle and the Haisei Hall. The museum offers guided tours showcasing the tricks and mechanisms of ninja houses, including the famous ''kunoichi'' (female ninja). Visitors can also enjoy thrilling ninja performance shows at the Ninja Experience Plaza.' where id = 'VrblCZdryQm_mGPCZpuXf';
update content_bodies set title = '「The NINJA～忍者ってナンジャ！？～」', description = '三重県総合博物館MieMuで2016年10月25日から2017年1月9日まで開催されている「The NINJA～忍者ってナンジャ！？～」では、忍者の歩き方の修行に焦点を当てたシーンが展開されています。この展示は、忍者の技術や文化を学ぶ貴重な機会を提供しています。' where id = 'OLQgYtsKm6WwLN-1RtOFA';
update content_bodies set title = 'The NINJA: What is a Ninja!?', description = 'The exhibition ''The NINJA: What is a Ninja!?'' is being held at the Mie Prefectural Museum (MieMu) from October 25, 2016, to January 9, 2017. This event features a scene focused on the training of walking, which is an essential skill for ninjas.' where id = '9EbMEV2BSDJleMTz_GJLt';
update content_bodies set title = '伊賀の里　モクモク手づくりファーム', description = '伊賀の里モクモク手づくりファームは、自然、農園、手づくりをテーマにしたファクトリーファームです。2016年10月8日から10月10日まで、実りの秋を祝う収穫祭を開催します。詳細については、観光三重のHPをご覧ください。' where id = '-GEW3OrzC-xbhIjXy2Tya';
update content_bodies set title = 'Iga''s Moku Moku Handmade Farm', description = 'Moku Moku Handmade Farm is a factory farm themed around nature, agriculture, and handmade crafts. They will hold a harvest festival to celebrate the fruitful autumn from October 8 to October 10, 2016. For more details, please visit the Mie Tourism website.' where id = 'AYU5juyCF6f_LUI-h6vXR';
update content_bodies set title = '赤目四十八滝渓谷保勝会', description = '美しい名瀑や渓谷、樹木、渓流、さらには生きている化石と呼ばれるサンショウウオなど、大自然が生み出した芸術に出会うことができます。特に秋にはイロハモミジやカエデ類が紅葉し、素晴らしい渓谷の美しさを楽しむことができます。詳細については、観光三重の公式HPをご覧ください。' where id = 'px7N2MEt2sRLDHd_pW88u';
update content_bodies set title = 'Akame 48 Waterfalls Preservation Association', description = 'Experience the artistic beauty created by nature, including stunning waterfalls, valleys, trees, and streams, as well as living fossils like the salamander. In autumn, the Irohamomiji and other maple trees turn vibrant colors, offering a spectacular view of the valley''s beauty. For more details, please visit the official tourism website of Mie.' where id = 'Ovf01NnMovFGY4yfhgKB4';
update content_bodies set title = 'まつもとの來來憲', description = 'まつもとの來來憲は、四日市名物の大とんてきの元祖であり、なんと250gもの分厚い豚肉を使用しています。柔らかく焼き上げられた肉は、旨味が凝縮されており、にんにくエキスが効いた特性ダレとの相性は抜群です。' where id = 'cq-mIULBck_bouwSRvj4m';
update content_bodies set title = 'Matsumoto''s Rairaiken', description = 'Matsumoto''s Rairaiken is the original store of Yokkaichi''s famous ''big tonteki,'' featuring a thick 250g slice of pork. The tender meat is perfectly grilled, and its rich flavor pairs excellently with a special sauce infused with garlic extract.' where id = 'EcfqaBclj_xg067qQJ2Hj';
update content_bodies set title = 'はまぐりプラザ', description = '桑名のはまぐりは、木曽三川の淡水と海水が絶妙に混ざり合った環境で育ち、ふっくらと柔らかく、甘みが強いのが特徴です。食堂はまかぜでは、焼きはまぐりをはじめ、はまぐり丼やはまぐりうどんなど、さまざまな料理を楽しむことができます。詳細については、観光三重のHPをご覧ください。' where id = 'uyZKdo7bjAAVR4p97L5UN';
update content_bodies set title = 'Hamaguri Plaza', description = 'The hamaguri clams from Kuwana are nurtured in a rich environment where fresh water from the Kiso Three Rivers mixes perfectly with seawater, resulting in clams that are plump, tender, and sweet. At the restaurant Hamakaze, visitors can enjoy various dishes featuring hamaguri, including grilled hamaguri, hamaguri rice bowls, and hamaguri udon. For more details, please visit the Mie Tourism website.' where id = 'JO6jYKmG4MeSAbSM93oRd';
update content_bodies set title = '賛急屋', description = '賛急屋では、こだわりの和風出汁を使用した牛汁が特徴で、伊賀牛や地元産の野菜が使われています。この牛汁には、自慢のだし巻き卵が入っているのが特長です。定食では、牛汁と伊賀米コシヒカリのおにぎり、からあげ、地元食材の3点盛りを楽しむことができます。詳細については、HP観光三重をご覧ください。' where id = 'klgZu6nfCI47f2dGj5U4i';
update content_bodies set title = 'Sankyuya', description = 'Sankyuya features a unique beef soup made with carefully crafted Japanese dashi, using Iga beef and locally sourced vegetables. A standout characteristic of this dish is the inclusion of their signature dashi-maki tamago (Japanese rolled omelette). The set meal offers a delightful combination of beef soup, Iga Koshihikari rice balls, fried chicken, and a trio of local ingredients. For more details, please visit the Mie Tourism website.' where id = 'J2NRMDTw91wJvgKx7tvu_';
update content_bodies set title = '新玉亭', description = '新玉亭では、炭火焼による関西風の蒲焼を提供しています。表面はパリッと香ばしく、中はふわふわの食感です。ご飯の甘味と食感がうなぎの味を引き立てるように、伝統のタレをかけた際にちょうど良い食感になるよう、炊き方にも工夫が施されています。' where id = 'kFAXOGjz-3UcC85Qt52eo';
update content_bodies set title = 'Shintamatei', description = 'Shintamatei offers Kansai-style grilled eel, prepared over charcoal. The exterior is crispy and fragrant, while the inside is fluffy. The cooking method is carefully designed to enhance the eel''s flavor by complementing the sweetness and texture of the rice, ensuring the perfect consistency when traditional sauce is applied.' where id = 'hwGsd2KE5kci0UZEX4zYX';
update content_bodies set title = 'おわせお魚いちば　おとと', description = 'おわせお魚いちばおととは、尾鷲港で水揚げされた魚介類やぶり、まぐろなどが豊富に並ぶ地場産品の直売所です。店内には食堂があり、水産会社が経営しているため、新鮮な魚介類を使った料理を楽しむことができます。新鮮な食材を活かした料理が提供されるため、訪れる人々にとって魅力的なスポットとなっています。詳細については、HP観光三重をご覧ください。' where id = 'zDwGtLrC3TCMWs9Ud5-JN';
update content_bodies set title = 'Owase Fish Market Oto', description = 'Owase Fish Market Oto is a local direct sales store where seafood caught at Owase Port, including yellowtail and tuna, is displayed. The in-store restaurant offers dishes made with fresh seafood, thanks to its management by a seafood company.' where id = 'NsypE0C_hwYgQKG1ICbIa';
update content_bodies set title = '植木神社祇園祭', description = '植木神社祇園祭は、宵宮祭と遷幸祭から成る祭りで、勇壮な神輿と江戸時代から大切にされている豪華な楼車が町内を巡行します。神輿を傾けながら回る「クネリ」や祇園花の行列が中心となり、華やかな雰囲気を醸し出します。この祭りは多くの見物客を惹きつける魅力があります。詳細については、HP「観光三重」をご覧ください。' where id = 'KmuDDCMPDVIAGBhfOb3ua';
update content_bodies set title = 'Ueki Shrine Gion Festival', description = 'The Ueki Shrine Gion Festival consists of the evening festival and the procession of the deity. It features a magnificent parade of portable shrines and luxurious floats that have been cherished since the Edo period. The festival is highlighted by the ''Kuneri,'' where the portable shrines are tilted while moving, and the procession of Gion flowers, creating a vibrant atmosphere that attracts many spectators.' where id = 'reDlgelnoumugHJk1nVov';
update content_bodies set title = '伊雑宮御田植祭', description = '伊雑宮御田植祭は、勇壮な男達による「竹取神事」、古式ゆかしい装束に身を包んだ役人らによる「御田植神事」、一の鳥居へと向かう「踊込み」の3つの神事から構成されています。伝統と歴史を感じさせる荘厳な時代絵巻の再現は、一見の価値があります。詳細については、ＨＰ「観光三重」をご覧ください。' where id = '3MImqZAs6EzAY7tmeUGhC';
update content_bodies set title = 'Izaumi Shrine Rice Planting Festival', description = 'The Izaumi Shrine Rice Planting Festival consists of three main rituals: the ''Take-tori Ceremony'' performed by brave men, the ''Rice Planting Ceremony'' conducted by officials in traditional attire, and the ''Odori Komi'' procession towards the first torii gate. The solemn reenactment of this historical pageant, rich in tradition, is truly worth witnessing.' where id = 'CBXjrYOYdV3rMgI62K5Sq';
update content_bodies set title = 'イルカ島', description = 'イルカ島では、イルカやアシカのショーを楽しむことができるほか、イルカとのふれあい体験としておでこタッチやおやつをあげることができます。また、絆をテーマにしたイルカのモニュメントがあり、鐘を鳴らすことで大切な人との関係を深めることができます。「鳥羽湾めぐりとイルカ島」についての詳しい取材レポートは、リンクを参照してください。' where id = 'Fh3lxtGo0mMq_ksja33mG';
update content_bodies set title = 'Dolphin Island', description = 'At Dolphin Island, visitors can enjoy interactive experiences with dolphins and sea lions, including shows, touching their foreheads, and feeding them. There is also a monument themed around bonds, where you can ring a bell to deepen your relationship with loved ones. For more detailed reports on ''Toba Bay and Dolphin Island,'' visit the provided link.' where id = '69E6cSfUouq0hXNLrjMU0';
update content_bodies set title = 'しろんご祭', description = 'しろんご祭では、ホラ貝の合図で海女たちがつがいのアワビを獲るために競い合います。一番に獲った海女は、一年間海女頭として崇められ、豊漁が約束されると伝えられています。詳細については、HP「観光三重」をご覧ください。' where id = 'qpiGwhorLdi5qQT5LSmwm';
update content_bodies set title = 'Shirongo Festival', description = 'During the Shirongo Festival, ama (female divers) compete to catch pairs of abalone, signaled by the sound of a conch shell. The ama who catches the first pair is revered as the head ama for a year, and it is believed that this brings a bountiful catch for the year. For more details, please visit the official website ''Kankomie''.' where id = 'Na_fi9vIFD4KdENzKer5M';
update content_bodies set title = '観光三重2017 100号記念　10月のオススメ観光20セレクション', description = '秋の行楽シーズンに突入した10月に、三重県で開催されるおすすめの観光スポットを紹介します。この記事では、訪れるべき20の魅力的な観光地を厳選してお届けします。' where id = 'K6WvKONxn7SmUUy8Bthuj';
update content_bodies set title = 'Tourism Mie 2017 100th Issue: Recommended 20 Tourist Spots for October', description = 'This article highlights recommended tourist spots in Mie Prefecture during the peak of the autumn leisure season in October. It provides a selection of 20 attractions to visit.' where id = 'VUrNAQ1-i_f8nBtOC1ozN';
update content_bodies set title = '御在所ロープウエイ（三重県菰野町）', description = '御在所ロープウエイは、全長2,161ｍ、高低差780ｍ、所要時間12分の空中散歩を楽しめる世界有数のロープウエイです。春にはツツジが咲き誇り、夏は納涼とアカトンボ、秋は10月中旬から11月下旬までの紅葉が楽しめ、赤・黄・褐色の色彩が山を彩ります。冬には美しい樹氷と氷ばくが見られ、県内唯一のスキー場には多くのスキーヤーが集まります。四季折々に楽しめるスポットです。' where id = 'sLm_CgnATC2C8J5hTrKXs';
update content_bodies set title = 'Gozaisho Ropeway (Komono Town, Mie Prefecture)', description = 'The Gozaisho Ropeway offers a breathtaking aerial experience with a length of 2,161 meters and an elevation difference of 780 meters, taking approximately 12 minutes. Visitors can enjoy the vibrant azaleas in spring, refreshing views and red dragonflies in summer, and stunning autumn foliage from mid-October to late November, showcasing a spectrum of red, yellow, and brown hues. In winter, the area transforms with beautiful frost-covered trees and ice formations, attracting many skiers to the only ski resort in the prefecture. This spot is perfect for enjoying the changing seasons.' where id = 'LEOYTXi5AxqdhLitunhJa';
update content_bodies set title = '東建多度カントリークラブ・名古屋', description = 'この動画は、東建多度カントリークラブ・名古屋について紹介しています。' where id = 'JFW2N_QdyxPQWzhiLXWTH';
update content_bodies set title = 'Tokken Tado Country Club, Nagoya', description = 'This video introduces the Tokken Tado Country Club in Nagoya.' where id = 'HpGj4BcgJ_GB7lbWJaG5R';
update content_bodies set title = '鈴鹿サーキット', description = 'この動画は鈴鹿サーキットについて紹介しています。' where id = 'ijkSouBbhW-TmWscHL0oM';
update content_bodies set title = 'Suzuka Circuit', description = 'This video introduces the Suzuka Circuit.' where id = 'j4aCUAm35o60KzUpQeCUf';
update content_bodies set title = '鈴鹿の森庭園', description = 'この動画は鈴鹿の森庭園について紹介しています。鈴鹿の森庭園は、美しい自然環境の中に位置し、訪れる人々にリラックスできる空間を提供しています。庭園内には多様な植物や花々が植えられており、四季折々の風景を楽しむことができます。また、散策路や休憩スペースも整備されており、家族連れや友人同士での訪問にも適しています。' where id = 'GKy5lpaKx_8xzOmTpOiuJ';
update content_bodies set title = 'Suzuka Forest Garden', description = 'This video introduces the Suzuka Forest Garden.' where id = 'IRRMKaDR-BTjh2BOi9-em';
update content_bodies set title = '松阪もめん手織りセンター', description = '松阪もめん手織りセンターは、越後屋三井家跡に位置する松阪もめんの伝承施設です。三井高利や松阪商人によって江戸で大流行した松阪もめんの魅力を体験できる場所で、鞄やＴシャツ、ぬいぐるみなど現代風にアレンジされた商品が販売されています。また、松阪木綿の手織り体験も楽しむことができ、訪れる人々に伝統と現代の融合を提供しています。' where id = 'h81kAjenDSikUwPz_8hgv';
update content_bodies set title = 'Matsusaka Momen Handweaving Center', description = 'The Matsusaka Momen Handweaving Center is a facility dedicated to the tradition of Matsusaka cotton, located at the site of the Echigoya Mitsui family. Visitors can experience the charm of Matsusaka momen, which became popular in Edo thanks to Mitsui Takatoshi and Matsusaka merchants. The center offers a variety of modern products, including bags, T-shirts, and stuffed animals, all creatively designed using Matsusaka cotton. Additionally, guests can enjoy hands-on experiences in handweaving Matsusaka cotton.' where id = 'a-aa0u4at2Tm4fh7JCeyY';
update content_bodies set title = '松浦武四郎記念館', description = '北海道の名付け親として知られる松浦武四郎は、2018年に生誕200年を迎え、様々な催しが予定されています。三重県松阪市に位置する松浦武四郎記念館では、武四郎の功績を伝える重要文化財が1505点収蔵されており、展示室では彼の多様な姿が紹介されています。また、記念館に関する詳しい取材レポートでは、松阪市出身の探検家である武四郎の生涯が詳しく紹介されており、NHKによるドラマ化も決定しています。' where id = '2scattF5ssH8xtHOeTjSC';
update content_bodies set title = 'Matsuura Takeshiro Memorial Museum', description = 'Matsuura Takeshiro is known as the namesake of Hokkaido. In 2018, he celebrated his 200th birthday with various events planned. The Matsuura Takeshiro Memorial Museum in Matsusaka City, Mie Prefecture, houses 1,505 important cultural properties that convey Takeshiro''s achievements. The exhibition room showcases various aspects of his life. A detailed report on the museum highlights the life of this explorer from Matsusaka City, who is recognized as the namesake of Hokkaido, and mentions a planned drama adaptation by NHK.' where id = 'prdGKEZ4wOlRgbFOR41Py';
update content_bodies set title = '本居宣長記念館', description = '本居宣長記念館は、三重県松阪市にある宣長が暮らした旧宅「鈴屋」に隣接しています。来館者は、宣長の私生活や人柄を楽しみながら学べるクイズを体験でき、宣長が描いた迫力満点の日本地図にも目を奪われます。館内には、宣長の自筆稿本や遺愛の品など約1万6千点が収蔵されており、宣長の文学や歴史への貢献に興味がある人々にとって文化的な拠点となっています。' where id = '-vCSvdx96QBVFOdcoQ75R';
update content_bodies set title = 'Hon''ami Norinaga Memorial Museum', description = 'The Hon''ami Norinaga Memorial Museum is located adjacent to the former residence ''Suzuya'' in Matsusaka City, Mie Prefecture, where Norinaga lived. Visitors can enjoy learning about Norinaga''s private life and personality through quizzes, as well as admire powerful Japanese maps he created. The museum houses approximately 16,000 items, including Norinaga''s handwritten manuscripts and cherished belongings. It serves as a cultural hub for those interested in Norinaga''s contributions to Japanese literature and history.' where id = 'qKtT18hNi7jTkuXB_U1EN';
update content_bodies set title = '海女小屋はちまんかまど　20170527動画', description = '海女さんが目の前で新鮮な魚介類を焼いてくれることで、外国人観光客に大人気の海女小屋。三重県鳥羽市相差の海女小屋「はちまんかまど」では、海女さん達が踊りを披露してくれました。' where id = 'Ui1yO312vQpn0yeXdz1uY';
update content_bodies set title = 'Amagoya Hachiman Kamado - Video from May 27, 2017', description = 'The Amagoya, or sea women''s hut, is extremely popular among foreign tourists for its unique experience of having fresh seafood grilled right in front of them by the ama divers. At the Hachiman Kamado in Ousatsu, Toba City, Mie Prefecture, the ama divers also showcased traditional dances.' where id = 'Ea49ZtIE6xUZOrLEwyXMy';
update content_bodies set title = 'ミキモト真珠島　20170527動画', description = 'この動画は、ミキモト真珠島で行われている海女さんの潜水作業の実演を紹介しています。海女さんたちは、真珠を採取するために海に潜り、その技術や伝統を披露しています。真珠の採取は、長い歴史を持つ日本の文化の一部であり、海女さんたちの勇敢な姿が印象的です。' where id = 'Vp99qaJN-zFKG_qtm6XFo';
update content_bodies set title = 'Mikimoto Pearl Island Video from May 27, 2017', description = 'This video showcases the diving work performed by ama (female divers) at Mikimoto Pearl Island.' where id = 'OXS9XwBrU4xJZeHb-g2AL';
update content_bodies set title = '円座・佐八かんこ踊り', description = 'かんこ踊りは、白馬の尾で作ったじゃぐまをかぶり、太鼓を叩きながら篝火の周りを輪になって踊るお盆の行事です。この行事は県指定の無形民俗文化財に指定されています。松明の周りで太鼓を抱えながら舞う姿は非常に魅力的です。詳細については、HP観光三重をご覧ください。' where id = 'KZ38mMnTyzODgOAv694Bg';
update content_bodies set title = 'Kanko Dance at Enza and Sahachi', description = 'The Kanko dance is a traditional Obon event where participants wear a hat made from the tail of a white horse and dance around a bonfire in a circle while beating drums. This event is designated as an intangible cultural asset by the prefecture. The sight of dancers beating drums while performing around the torches is captivating.' where id = 'rXcU65XEaOopKIZZN23Kr';
update content_bodies set title = 'イベント情報紙「観光三重」99号特集　みえのウキウキ夏祭り', description = '三重県観光連盟が発行するイベント情報紙「観光三重」の99号では、みえのウキウキ夏祭りを特集しています。この祭りは、地域の魅力を引き出し、観光客を楽しませるイベントです。詳細については、観光三重の公式HPをご覧ください。' where id = 'NIimHhOUG7GROhaSTais8';
update content_bodies set title = 'Event Information Paper ''Kankou Mie'' Special Issue 99: Mie’s Exciting Summer Festival', description = 'The 99th issue of the event information paper ''Kankou Mie'', published by the Mie Prefectural Tourism Federation, features a special focus on Mie’s Exciting Summer Festival. For more details, please visit the Kankou Mie website.' where id = 'bJ1eOcaYQn_WW2aNoz0Dq';
update content_bodies set title = '桑名石取祭', description = '桑名石取祭は「山・鉾・屋台行事」としてユネスコの無形文化遺産に登録されています。祭りでは、数十台の祭車が市内を練り歩き、鉦や太鼓の音が盛大に響き渡ります。その様子から、日本一やかましい祭りとも称されています。' where id = '3yJ_ba3JGpOMm62rbGalg';
update content_bodies set title = 'Kuwana Ishitori Festival', description = 'The Kuwana Ishitori Festival is recognized as an Intangible Cultural Heritage by UNESCO as a ''Yama, Hoko, and Yatai event.'' During the festival, dozens of festival floats parade through the city, accompanied by the resounding sounds of bells and drums. It is often referred to as the loudest festival in Japan.' where id = '6LLwuFaXmPDqVGQwFX075';
update content_bodies set title = '世界遺産 巡礼路「熊野古道伊勢路」 ～映像シリーズ３', description = '神々の棲む場所である熊野では、人々が自分と向き合い、生まれ変わることができるとされています。一滴の雨露が流れ、海となり、天に昇り、再び雨となって戻るように、自然の中で神様と仏様が共存しています。ここでは、魂のよみがえりを願う人々が新たな一歩を踏み出す誓いを立てます。熊野古道は、日本各地から和歌山県の熊野三山を目指して歩かれた古道であり、伊勢神宮と熊野三山を結ぶ世界遺産の巡礼路「熊野古道伊勢路」の歴史と魅力を紹介します。' where id = 'X12XSah2jtrP2AOD-KzYe';
update content_bodies set title = 'World Heritage Pilgrimage Route ''Kumano Kodo Iseji'' - Video Series 3', description = 'A place where gods reside. Here, people confront themselves and are reborn. Just as a drop of dew flows into a stream, becomes the sea, ascends to the heavens, and returns as rain, Kumano is a world where both gods and Buddhas coexist in nature. It is said that people come here to wish for the resurrection of their souls, making a vow to take a new step towards something. The Kumano Kodo is an ancient path walked by pilgrims from various parts of Japan to the three Kumano shrines in Wakayama Prefecture. This summary introduces the history and charm of the World Heritage pilgrimage route ''Kumano Kodo Iseji,'' which connects the two major sacred sites of Ise Shrine and the Kumano Three Mountains.' where id = 'i_nhpQehtAhL5v9jB78aX';
update content_bodies set title = 'お伊勢さん菓子博2017－みえの魅力発信（2016.5.20）', description = '平成29年に三重県で開催されるビッグイベントは、「第27回全国菓子大博覧会・三重（愛称：お伊勢さん菓子博2017）」です。このイベントは、4月21日から5月14日まで開催され、菓子博の魅力を紹介することを目的としています。' where id = '5DyWmDDAHs0TvcUBDkmps';
update content_bodies set title = 'Ise Candy Expo 2017 - Promoting the Charm of Mie (May 20, 2016)', description = 'A major event in Mie Prefecture in 2017 is the 27th National Confectionery Expo, also known as the Ise Candy Expo 2017, which will be held from April 21 to May 14. This event aims to showcase the appeal of confectionery.' where id = 'oIFhtZHgmxoaZciM01H8P';
update content_bodies set title = '伊賀焼伝統産業会館で伊賀焼の陶器づくり体験', description = '伊賀焼伝統産業会館で伊賀焼陶芸体験に挑戦しました。ここでは陶芸家の方から直接指導を受けることができ、貴重な体験ができます。陶芸に興味がある方には特におすすめの場所です。詳細については、こちらのリンクをご覧ください。https://www.kankomie.or.jp/report/detail_178.html' where id = 'Hm9SGSTFu4GWNZMmnc272';
update content_bodies set title = 'Experience Iga Pottery Making at the Iga-yaki Traditional Industry Hall', description = 'I had the opportunity to try my hand at Iga-yaki pottery at the Iga-yaki Traditional Industry Hall. Here, you can receive direct guidance from a pottery artist. For more details, visit https://www.kankomie.or.jp/report/detail_178.html' where id = 'o5zCykDvUEDpcj18Zn2LC';
update content_bodies set title = '京都市観光PR映像_ショート動画⑤「伝統産業」', description = 'この動画は、京都市の伝統産業について紹介しています。京都は長い歴史を持つ都市であり、伝統的な工芸や産業が数多く存在します。これらの産業は、地域の文化や技術を反映しており、観光客にとっても魅力的な要素となっています。動画では、これらの伝統産業の特徴や魅力を視覚的に伝え、京都の文化的な深さを感じさせる内容となっています。' where id = 'HKIWNagC0T2kg7si7tW6y';
update content_bodies set title = 'Kyoto City Tourism PR Video - Short Video ⑤ ''Traditional Industries''', description = 'This video introduces the traditional industries of Kyoto City.' where id = 'EAQNt2IBC7acO1lrPSZ99';
update content_bodies set title = 'みえ食旅パスポートを持って出かけよう！～みえの魅力発信～', description = '三重をオトクに、楽しく満喫するための「みえ食旅パスポート」の取得方法や使い方について詳しく紹介しています。山村みるくがっこうや志摩地中海村での実際の利用例も掲載されており、三重県を観光する方には必見の内容です。公式サイトへのリンクも提供されています。' where id = 'rFQnlI8DRSWs9p1NR_L4C';
update content_bodies set title = 'Let''s Go Out with the Mie Food Travel Passport! - Promoting the Charm of Mie', description = 'The Mie Food Travel Passport is a tool for enjoying Mie in a fun and economical way. This article provides detailed information on how to obtain and use the passport. It also includes actual experiences of using the passport at places like Yamamura Milk School and Shima Mediterranean Village, making it a must-read for anyone planning to visit Mie Prefecture!' where id = 'fItfNNq326RgkyfyoQItR';
update content_bodies set title = 'イベント情報紙「観光三重」97号特集　みえのメモリアルタイム', description = '三重県観光連盟が発行するイベント情報紙「観光三重」の97号特集では、みえのメモリアルタイムに関連するスポットが紹介されています。詳細については、観光三重の公式ウェブサイトをご覧ください。' where id = 'cAeWHL-v4a68hbftmJqcI';
update content_bodies set title = 'Event Information Paper ''Kankou Mie'' Special Issue 97: Mie Memorial Time', description = 'This is a feature on spots introduced in the special issue 97 of the event information paper ''Kankou Mie'', published by the Mie Prefecture Tourism Federation, focusing on Mie Memorial Time. For more details, please visit the Kankou Mie website.' where id = '_ZulQbI4B2F6zFp2D8rnM';
update content_bodies set title = 'ナガシマスパーランド', description = 'ナガシマスパーランドは、ギネス認定のコースターを含む約50種類以上のアトラクションが揃う遊園地です。詳細については、HP観光三重をご覧ください。' where id = 'z1dXbQghF-0wYmI5V_Iz0';
update content_bodies set title = 'Nagashima Spa Land', description = 'Nagashima Spa Land is an amusement park featuring over 50 attractions, including a Guinness World Record roller coaster.' where id = '2Tvz5HRuN24fU86PkAnGy';
update content_bodies set title = 'アクアイグニス', description = 'アクアイグニスは、湯の山温泉に位置する「癒し」と「食」の総合リゾートです。ここでは、トップレベルのシェフたちが手がける料理に魅了されることができます。詳細については、HP観光三重をご覧ください。' where id = 'Nr0TateIzdZt7MmWopPku';
update content_bodies set title = 'Aqua Ignis', description = 'Aqua Ignis is a comprehensive resort located in Yunoyama Onsen, offering both relaxation and culinary experiences. Guests are captivated by the dishes prepared by top-level chefs.' where id = 'AbXn26VF79PMWrVsr8s06';
update content_bodies set title = 'パラミタミュージアム', description = 'パラミタミュージアムでは、萬古の優美な世界を体験できる北勢萬古名品展が12月25日まで開催されています。この展覧会は、萬古焼の魅力を存分に楽しむことができる貴重な機会です。詳細については、観光三重の公式ウェブサイトをご覧ください。' where id = 'JCW9l92k1HxWUfR1GYoQ2';
update content_bodies set title = 'Paramita Museum', description = 'The Paramita Museum is currently hosting the North Sei Banko Masterpieces Exhibition, showcasing the elegant world of Banko until December 25. For more details, please visit the official tourism website of Mie.' where id = 'rG97Sk8cGlpUsXds80syU';
update content_bodies set title = '四日市コンビナート夜景クルーズ', description = '日本を代表する工場夜景の聖地である四日市では、ベテランのガイドが同行し、宝石のように美しい工場夜景を楽しむことができます。さらに、遠くには中部国際空港セントレアの夜景も見えます。特に第一コンビナートの幻想的な夜景は、息を飲むほどの美しさを誇ります。' where id = '3Jlf_FXrZ5wbC6H1_vnBW';
update content_bodies set title = 'Yokkaichi Industrial Night View Cruise', description = 'Yokkaichi is a renowned site for factory night views in Japan. Accompanied by an experienced guide, participants can enjoy the stunning factory lights that resemble jewels, as well as the night view of Chubu Centrair International Airport in the distance. The enchanting night scenery of the First Industrial Complex is particularly breathtaking.' where id = 'JOjshwXym2iuzV5FXosVw';
update content_bodies set title = '志摩地中海村', description = '地中海のような感動を体験できる滞在型リゾートです。本場スペインのデザイナーが手がけた美しい街並みは、日本にいることを忘れさせるほどの魅力があります。' where id = '3mVSq4WrxiaI43YnyhZqG';
update content_bodies set title = 'Shima Mediterranean Village', description = 'Experience the sensation of being in the Mediterranean at this resort. The beautifully designed streets, crafted by a Spanish designer, are so stunning that you might forget you are in Japan.' where id = 'BoOjrnvkuQhw4_dl4YkOn';
update content_bodies set title = '湯元榊原舘', description = '榊原温泉は、お伊勢さん湯ごりの地として知られています。お肌を優しく包み込むこのお湯は、まるで美容液のようで、昔から美人の湯として親しまれています。詳細については、観光三重のHPをご覧ください。' where id = 'DogEV04C8j1QvkTIsBOFA';
update content_bodies set title = 'Yumoto Sakakibara-kan', description = 'Sakakibara Onsen is renowned as a hot spring area associated with Ise Shrine. The water, which envelops the skin gently and provides a moisturizing effect, has long been cherished as a beauty-enhancing bath.' where id = '_BCcg8xlVcZC2qE1DXRWO';
update content_bodies set title = '「The NINJA～忍者ってナンジャ！？～」', description = '三重県総合博物館MieMuで、2016年10月25日から2017年1月9日まで開催されている「The NINJA～忍者ってナンジャ！？～」の展示では、ナンジャ大滝を含むさまざまなシーンが紹介されています。この展示は、忍者の文化や歴史についての理解を深めることを目的としています。' where id = 'BZGO9M1RMF4UzRC5Yo8Ya';
update content_bodies set title = 'The NINJA: What is a Ninja!?', description = 'The exhibition ''The NINJA: What is a Ninja!?'' is being held at the Mie Prefectural Museum (MieMu) from October 25, 2016, to January 9, 2017. The event features various scenes, including the impressive ''Nanja Otaki'' waterfall.' where id = 'bN2Ma0ifz2UjGGPZFdADw';
update content_bodies set title = 'ミキモト真珠島新人海女特訓中!! Ｐａｒｔ2', description = '初練習から3週間が経過しました。彼女たちの上達ぶりをご覧ください。' where id = 'ks5QDDvQCta9s446j1YMZ';
update content_bodies set title = 'Mikimoto Pearl Island New Diver Training!! Part 2', description = 'It has been three weeks since the initial training. Please take a look at their progress!' where id = 'JW1Ede3-fLjOyYw6Ob1Ur';
update content_bodies set title = 'ミキモト真珠島新人海女特訓中!!', description = '今年、ミキモト真珠島に2名の新人海女が入社しました。彼女たちは夏休み前のデビューを目指して、ただいま特訓中です。' where id = 'T8O_zJ5p-ekMTQcMB6e-o';
update content_bodies set title = 'Training New Ama Divers at Mikimoto Pearl Island!', description = 'This year, two new ama divers have joined Mikimoto Pearl Island. They are currently undergoing training with the goal of debuting before the summer vacation.' where id = 'RmGE6gHIjctFlxT_WtLuM';
update content_bodies set title = '迫力満点の少林武術', description = '津のイオンで少林武術のパフォーマンスが行われました。日本では少林寺拳法として知られていますが、実際には中国の河南省で生まれた武道です。映画でしか見たことがなかった少林武術を目の当たりにし、その迫力に感動しました。' where id = 'WziCsWwYsdVCTA9d7gfLe';
update content_bodies set title = 'Spectacular Shaolin Martial Arts', description = 'A performance of Shaolin martial arts took place at the Aeon in Tsu. While it is known in Japan as Shaolin Temple Kenpo, it originated in Henan Province, China. The Shaolin martial arts, which I had only seen in movies, were truly impressive!' where id = 'D_5n5SdiSy-kaD7JnqvrD';
update content_bodies set title = '福王神社～福王山～東海自然歩道コース 山歩き', description = '菰野町にある福王山（標高597ｍ）に登った時の動画です。2回目の福王山でしたが、下りは福王神社と反対側の東海自然歩道へ下りてぐるっと1周回れるコースがあることを最近知り、気分新たに楽しみにして登ってきました。とても暑かったですが、蝉や虫の声、山と森の空気に癒された時間を過ごすことができました。' where id = 'hkCsbN60QH7vbr-D2d4bv';
update content_bodies set title = 'Fukuou Shrine - Fukuou Mountain - Tokai Nature Trail Course Hiking', description = 'This video captures my hike up Fukuou Mountain (elevation 597m) located in Komono Town. It was my second time climbing Fukuou Mountain, and I recently discovered a loop course that descends via the Tokai Nature Trail on the opposite side of Fukuou Shrine. I was excited to experience this new route. Despite the heat, I enjoyed a soothing time surrounded by the sounds of cicadas and insects, as well as the fresh air of the mountains and forests.' where id = 'qAdvrEUNai4d8Q2bDvPXw';
update content_bodies set title = '御在所', description = '御在所岳へは全長2161mのロープウエイで登りました。このロープウエイの最高支柱高は日本一の61mです。市街地の気温は35度でしたが、標高1212mの山頂では24度と涼しく、たくさんの赤トンボが飛んでいました。' where id = 'yoDfubai10cjv7RsTf0BK';
update content_bodies set title = 'Gozaisho', description = 'I took the ropeway to Gozaisho Mountain, which has a total length of 2161 meters. The highest support pillar of the ropeway is the tallest in Japan, standing at 61 meters. While the temperature in the city was 35 degrees Celsius, it was a cool 24 degrees at the summit, which is at an elevation of 1212 meters. Many red dragonflies were flying around.' where id = '-XK47-ku-iGHG02jRJOGL';
update content_bodies set title = '萬古まつり', description = '四日市で開催された萬古まつりは、5月12日と13日の2日間にわたって行われました。この祭りでは、萬古焼のキャラクター「ポッターくん」が大活躍し、多くの来場者を楽しませました。' where id = 'kGN7miyAg3dFiC64RV1Gn';
update content_bodies set title = 'Banko Festival', description = 'The Banko Festival in Yokkaichi was held on May 12th and 13th. The festival featured the popular character ''Potter-kun'' from Banko ware, who played an active role in the event.' where id = 'xli3xAEsajF-Yn2KVRZuB';
update content_bodies set title = '四日市コンビナート夜景クルーズ', description = '先日、みえのみどころええとこの取材のために四日市コンビナート夜景クルーズに行ってきました。普段は見ることができない船からの工場夜景は、非常に美しかったです。ぜひ体験してみてください！' where id = 'w77QHdL7hmqze5Dbcv49z';
update content_bodies set title = 'Yokkaichi Industrial Complex Night View Cruise', description = 'Recently, I went on the Yokkaichi Industrial Complex Night View Cruise to gather information for Mie’s attractions. The view of the factory nightscape from the boat, which is usually not accessible, was incredibly beautiful. I highly recommend it!' where id = 'qM-35vldDDy9ye2wN_Xfy';
update content_bodies set title = '鳥羽市相差・石神さんへの参道に新しくオープンした海女の家「五左屋」', description = '鳥羽市相差・石神さんへの参道に新しくオープンした海女の家「五左屋」は、古民家を改装した施設です。ここでは自由に休むことができ、お土産を購入したり、お茶を楽しんだりすることができます。訪れる人々にとって、リラックスできる素敵な場所となっています。' where id = 'PPWlAHGAB8sEz_WNmUluq';
update content_bodies set title = 'Newly Opened Ama House ''Gozaya'' on the Path to Ishigami-san in Toba City, Osatsu', description = 'The newly opened Ama house ''Gozaya'' is located on the path to Ishigami-san in Osatsu, Toba City. It is a renovated traditional house where visitors can relax freely, purchase souvenirs, and enjoy tea.' where id = 'XGfx8Op8ahfTuYEKZYFfP';
update content_bodies set title = '最高の足湯', description = '天気が良かったので、伊勢志摩スカイラインを通って鳥羽へ行きました。標高は555ｍで、展望台からは360度の美しい景色を楽しむことができました。また、足湯もあり、最も標高が高い足湯かもしれません。料金所でもらったくじを引いたところ、ラッキーにもソフトクリームが当たりました。' where id = '2EABs7dSmidliKHcthb5X';
update content_bodies set title = 'The Best Foot Bath', description = 'On a beautiful day, I traveled to Toba via the Ise-Shima Skyline, which has an elevation of 555 meters. From the observation deck, I enjoyed a stunning 360-degree view, and there was also a foot bath available. It might be the highest foot bath in the area. I was lucky to win a soft serve ice cream by drawing a lottery ticket I received at the toll booth.' where id = 'OzUink8FEfbGsmrzEi0Z7';
update content_bodies set title = '埼玉の醤油蔵見学に参加しよう！', description = '醤油がどのように大豆から作られるのか、興味を持ったことはありませんか？大豆の他に、小麦や塩、そして多くの努力と時間、少しの麹の魔法が必要です。埼玉の金武醤油公園で、代々受け継がれてきた伝統的な方法で醤油を作る武井家の醤油醸造プロセスを学びましょう。ここは稼働中の醤油蔵であり、観光地でもあり、訪問者は食事を楽しんだり、学んだり、遊んだり、伝統的な醤油を購入したりすることができます。' where id = 'tBgZFuI67SGMwd-bd-A00';
update content_bodies set title = 'Join Us on a Saitama Soy Sauce Brewery Tour!', description = 'Discover the fascinating process of how soybeans are transformed into the flavorful soy sauce used in sushi and stir-fries. At Kinbue Shoyu Park in Saitama, the Fueki family employs traditional methods passed down through generations to brew soy sauce. This working brewery not only offers insights into the brewing process but also serves as a tourist destination where visitors can enjoy food, learn, play, and purchase traditional soy sauce.' where id = 'PP-301P6VsyYGvKzHtvU1';
update content_bodies set title = '醤油学校への旅', description = '金武江醤油公園への訪問は、日本の醤油文化に浸る機会を提供します。参加者は「醤油学校」と呼ばれるツアーに参加し、大豆の袋から醤油の醸造プロセスを探ります。ツアーでは、数年にわたり醤油が熟成される大きな木製の樽を見学し、ランチにはうどんと共に様々な醤油の味を楽しみ、デザートには醤油ケーキを味わい、醤油の樽の中での思い出の写真を撮ることができます。' where id = 'pe9-tMK0fk9wmGU8XX7-_';
update content_bodies set title = 'A Trip to Soy Sauce School', description = 'A visit to Kinbue Shoyu Park offers an immersive experience in Japanese soy sauce culture. Participants can join a tour known as ''Soy Sauce School,'' where they explore the soy sauce brewing process, from sacks of soybeans to the aging in large wooden barrels. The tour includes tasting various soy sauce types paired with udon noodles for lunch, enjoying soy sauce cake for dessert, and taking memorable photos inside a soy sauce barrel.' where id = '89ACIxmBVw181XNgZgvwi';
update content_bodies set title = '埼玉のアウトドアアドベンチャー', description = '埼玉では、旅行者が楽しめるさまざまなアウトドアアクティビティが用意されています。特に注目すべきは、秩父のジオグラビティパークにある有名なジップラインや、荒川峡谷を横断するキャニオンウォークです。これらのアクティビティでは、自分の恐怖を乗り越え、秩父の自然の美しい景色を楽しむことができます。成功裏にこれらの体験を終えることで、達成感と新鮮な山の空気を味わうことができます。また、ユニークなグランピング体験を求める方には、コモリバー時玉秘密基地のキャンプ場がBBQや焚き火、埼玉の大自然の中での爽やかな朝の空気を提供しています。' where id = 'aR8QyfMVUgXKxOmkKQkTG';
update content_bodies set title = 'Outdoor Adventure in Saitama', description = 'Saitama offers a variety of exciting outdoor activities for travelers. Notable attractions include the famous zipline at Geo Gravity Park Chichibu and the Canyon Walk across the Arakawa Gorge, where visitors can challenge their fears and enjoy breathtaking views of Chichibu''s natural landscape. Successfully crossing these thrilling experiences provides a rewarding sense of accomplishment along with fresh mountain air. Additionally, for those seeking a unique glamping experience, the campgrounds at Comoriver Tokitama Himitsu Kichi feature BBQs, bonfires, and the refreshing atmosphere of Saitama''s great outdoors.' where id = 'rs4pp6zwjDq7iW2aZpdDL';
update content_bodies set title = '埼玉の盆栽庭園', description = '大宮盆栽村は、あらゆる方向に盆栽庭園が広がる活気あるエリアです。訪れることで、盆栽の日本文化をより深く理解する機会が得られます。美しく形作られた盆栽を鑑賞するだけでなく、自分自身の盆栽を作るワークショップにも参加できます。季節の美しさを反映した盆栽を作ることができ、また、盆栽美術館では長寿のエゾマツを見学し、日本の盆栽文化に触れることができます。' where id = 'eZnVUkvCjvhOvEWNyKU1X';
update content_bodies set title = 'The Bonsai Gardens of Saitama', description = 'Omiya Bonsai Village is a vibrant area filled with bonsai gardens, offering visitors a unique opportunity to appreciate the Japanese cultural tradition of bonsai. Guests can admire beautifully sculpted bonsai trees and even participate in workshops to create their own bonsai, reflecting the beauty of the seasons. Additionally, the Bonsai Art Museum showcases the long-lived Yezo Spruce tree, providing an immersive experience into the world of Japanese bonsai culture.' where id = 'cL5U8iPD3UIkNqZq96W3W';
update content_bodies set title = '岩槻の人形の日', description = '岩槻で伝統的な人形作りを体験できるイベントです。この地域は人形制作で知られており、2020年にオープンした岩槻人形博物館があります。地元の職人たちは、小さな人や動物の形を巧みに彫り、彫り込まれた溝にカラフルな布を押し込み、繊細な顔を描いて、毎回ユニークな人形を作り出します。ワークショップの参加者は、特定のポーズや髪型、表情の微妙な変化が、伝統的な「木目込み人形」にどれほどの個性を与えるかを実感できます。' where id = 'Xs1bsYRgjew1ZdweT5ZQJ';
update content_bodies set title = 'A Day of Dolls in Iwatsuki', description = 'Experience the traditional craft of doll-making in Iwatsuki, a neighborhood renowned for its unique dolls. The Iwatsuki Ningyo Museum, which opened in 2020, showcases the artistry of local craftspeople who skillfully carve dolls representing people and animals. Participants in workshops can engage in the intricate process of inserting colorful fabric into carved channels and painting delicate facial features. Each ''kimekomi-ningyo'' doll is distinct, with variations in posture, hairstyle, and facial expressions, allowing participants to appreciate how these subtle details contribute to the doll''s personality.' where id = 'da4fn0cm7u32-Lhs6TOMS';
update content_bodies set title = '秩父の360° VR巡礼', description = '日本の森林の精神的な体験を、秩父34観音巡礼路の360°バーチャルリアリティツアーを通じて体感してください。この没入型の体験は、息をのむような景色と地域の静けさを捉え、従来の写真や動画では伝えきれない軽やかさとリフレッシュ感を提供します。VR体験を楽しんだ後は、実際に埼玉を訪れて、この巡礼の美しさと静けさを十分に味わってみてください。' where id = 'dZbdD1Rx_TUts38QJClFT';
update content_bodies set title = 'A 360° VR Pilgrimage in Chichibu', description = 'Experience the spiritual essence of Japan''s forests through a 360° virtual reality tour of the Chichibu 34 Kannon Pilgrimage Route. This immersive experience captures breathtaking views and the tranquil stillness of the area, providing a sense of lightness and refreshment that traditional photos and videos cannot convey. After enjoying the VR experience, consider visiting Saitama in person to fully appreciate the beauty and serenity of this pilgrimage.' where id = 'egr09wXpfKS56HfTgSwLj';
update content_bodies set title = '秩父線ツアー', description = '秩父線ツアーでは、歴史的なサキタマ古墳群をはじめ、さまざまな観光名所を訪れることができます。国宝であるメヌマ聖伝山観義院は、その文化的な重要性で知られています。また、ツアーには長瀞川でのボート遊びや、宝登山ロープウェイからの美しい景色を楽しむアクティビティも含まれています。さらに、三十槌の氷柱や、地元の伝統や祭りを紹介する賑やかな秩父夜祭も有名です。' where id = 'CIAO67SDLKDXagUv4qIaN';
update content_bodies set title = 'Chichibu Line Tour', description = 'The Chichibu Line Tour offers a variety of attractions, including the Sakitama Ancient Burial Mounds, which are significant historical sites. Visitors can explore the Menuma Shodenzan Kangiin Temple, a National Treasure known for its cultural importance. The tour also includes activities such as boating on the Nagatoro River and enjoying the scenic views from the Mt. Hodosan Ropeway. Additionally, the area is famous for its icicles at Misotsuchi and the vibrant Chichibu Night Festival, showcasing local traditions and festivities.' where id = 'G1W7-ljl-E1o3HJu0fr9A';
update content_bodies set title = '秩父34観音寺巡り', description = '伝統的な白衣を身にまとい、菅笠をかぶり、頑丈な杖を持って秩父34観音巡礼路に出かけましょう。この巡礼路では、山の斜面に沿った森の小道を歩き、美しい石段を登って高台にある日本の寺院に到達し、時折険しい道の終わりに秩父の壮大な景色を楽しむことができます。13世紀にさかのぼるこの巡礼回路を通じて、日本の精神文化と豊かな自然に深く浸ることができます。' where id = 'vOfOg5iXJaNHIBJdzNdV9';
update content_bodies set title = 'Chichibu 34 Kannon Temple Circuit', description = 'Embark on the Chichibu 34 Kannon Pilgrimage Route dressed in traditional white robes known as ''hakui,'' complemented by a straw hat called ''sugegasa'' and a sturdy walking stick. This pilgrimage offers a serene experience as you traverse forest paths along mountainsides, ascend picturesque stone steps to reach elevated Japanese temples, and enjoy breathtaking views of Chichibu at the end of rugged trails. Immerse yourself in the rich spiritual culture of Japan while exploring the lush natural surroundings of this historic pilgrimage circuit, which dates back to the 13th century.' where id = 'XTngCh_78a_-WWeY6iJnh';
update content_bodies set title = '川越城の本丸御殿', description = '本丸御殿は、1848年に江戸時代の川越藩主・松平成恒によって建設され、川越で最も古い建物です。武士のような落ち着きを持つ本丸御殿は、川越城が大木屋宇都宮持朝によって建設された際に、古河公方足利成氏に対抗するために作られました。1457年には、宇都宮持朝が家臣の太田道真と太田道灌に城の建設を命じました。' where id = 'B2vcmPHET8oysZSMO4mtD';
update content_bodies set title = 'Honmaru Goten of Kawagoe Castle', description = 'Honmaru Goten, built in 1848 during the Edo Period by Matsudaira Naritsune, the master of the Kawagoe feudal domain, is the oldest building in Kawagoe. It reflects a samurai-like calmness and was constructed when Kawagoe Castle was established by Oogigayatsu Uesugi Mochitomo to confront Kogakubo Ashikaga Shigeuji. In 1457, Uesugi Mochitomo ordered his vassals, Ota Michizane and Ota Dokan, to build the castle.' where id = 'B_gb7XtPY5k4Eyf70EWps';
update content_bodies set title = 'うなぎ（埼玉）', description = 'うなぎは、日本のグルメ競争において常に一歩先を行っています。さまざまな店が独自の方法でうなぎを蒸したり焼いたりしており、通常は自家製の特製の旨味たっぷりのタレを何度も塗り重ねて仕上げます。' where id = '6EDDhPg7PO6UX8kmx1Fsh';
update content_bodies set title = 'Eel (Saitama)', description = 'Unagi, or eel, is a distinguished dish in Japan''s gourmet scene. Different shops have unique methods for steaming and grilling eel, often applying a special savory sauce multiple times during the cooking process.' where id = '_3oh0J851Gbi-Git0GWLW';
update content_bodies set title = '岩槻人形（埼玉）', description = '岩槻は大正時代（1912-1926年）から本格的に人形生産の中心地となりました。1923年の関東大震災や第二次世界大戦は、東京から岩槻への技術者の流入を促進しました。日本の急速な経済成長の時期には、岩槻は人形生産の主要な拠点としての地位を確立しました。現在、この地域を散策すると、多くの人形店や工房の看板が見られ、岩槻が人形の街であることを実感できます。' where id = 'j_XSjajAsYe8w1Y0vx1Ar';
update content_bodies set title = 'Iwatsuki ningyo(Saitama)', description = 'Iwatsuki became a significant center for ningyo (traditional Japanese dolls) production starting in the Taisho period (1912-1926). The Great Kanto Earthquake in 1923 and World War II contributed to the influx of technical skills from Tokyo to Iwatsuki. During Japan''s rapid economic growth, the city solidified its status as a major ningyo production hub. Today, visitors can see numerous ningyo shops and workshops throughout the neighborhood, highlighting Iwatsuki''s identity as a ningyo city.' where id = '5wYiCk5VaEMHxRdWSKZKm';
update content_bodies set title = '正伝山寺（熊谷）', description = '正伝山寺は、結婚に関する霊的な力で知られています。1760年に建設された本堂は、華麗な彫刻で飾られており、初期近代装飾建築の極致と称されています。この寺は国宝に指定されています。' where id = '0x2GCERJToptJeJ8MNPs4';
update content_bodies set title = 'Shodenzan Temple (Kumagaya)', description = 'Shodenzan Temple is renowned for its spiritual influence on marriage. The temple''s main building, built in 1760, features exquisite carvings, making it a prime example of early modern decorative architecture. It has been recognized as a National Treasure.' where id = 'qgyw6oKVcbOcAjEsPgH2_';
update content_bodies set title = '秩父鉄道の蒸気機関車（熊谷-三峰口）', description = 'この動画では、秩父鉄道の熊谷駅と三峰口駅の間を走る蒸気機関車を紹介しています。蒸気機関車の特徴や歴史的意義に焦点を当て、その運行や美しい風景を楽しむことができる内容となっています。' where id = 'gE6YfJJw00OJVV-xtvpau';
update content_bodies set title = 'Steam Locomotive(Chichibu Railway) Kumagaya-Mitsumineguchi', description = 'This video showcases the Steam Locomotive operating on the Chichibu Railway, specifically between the stations of Kumagaya and Mitsumineguchi. It highlights the unique features and historical significance of this steam locomotive, providing viewers with an insight into its operation and the scenic route it travels.' where id = 'dtavIgvsn1b1WLsgVpMgY';
update content_bodies set title = '川越城（本丸御殿）', description = '川越城は1457年に最初に建設され、現在の構造は1848年に追加されました。この場所では歴史を感じることができます。' where id = 'RObrReG4zyHxyoeKOjBJ7';
update content_bodies set title = 'Kawagoe Castle (Honmaru Goten)', description = 'Kawagoe Castle was originally constructed in 1457, and the current structure was added in 1848. Visitors can experience a sense of history at this site.' where id = 'tAFP-IP2dDZLnteqR7GwK';
update content_bodies set title = '埼玉観光PR動画2019', description = '埼玉県は「東京のすぐ北」に位置する地域で、訪れる人々にユニークな体験を提供しています。特に、川越の江戸時代の町並みや、人気のある長瀞川のホワイトラフティングが魅力です。埼玉は東京からの日帰り旅行に最適な目的地です。' where id = 'H87PfFuVia57ihl8OjYXy';
update content_bodies set title = 'Saitama tourism PR video 2019', description = 'Saitama Prefecture, located just north of Tokyo, offers unique experiences for visitors. Highlights include the historic Edo townscape in Kawagoe and the popular white rafting on the Nagatoro River. Saitama is an ideal destination for a day trip from Tokyo.' where id = 'CJIjHCBfExBZBAbOiE7yY';
update content_bodies set title = '川越江戸の街並みを歩く | 360 VR動画 | 埼玉県日本', description = '川越市は「小江戸」と呼ばれ、江戸時代の街並みや文化が今も残っています。時の鐘は、江戸時代からの川越の時間の流れを示す重要なランドマークです。川越は池袋駅から30分、新宿駅から50分と、東京からのアクセスも良好です。観光名所としては川越氷川神社や着物体験などがあります。' where id = 'S__BR4n5CIcdWcQb_RlKy';
update content_bodies set title = 'Walking Kawagoe Edo Townscape | 360 VR Video | Saitama Japan', description = 'Kawagoe City, known as Little Edo, retains the cityscape and culture of the Edo period (1603-1868). The Time Bell Tower is a significant landmark that signifies the passage of time in Kawagoe. The city is conveniently located just 30 minutes from Ikebukuro Station and 50 minutes from Shinjuku Station, making it easily accessible from Tokyo. Visitors can explore various attractions, including the Kawagoe Hikawa Shrine and experience wearing a kimono.' where id = '3lxIclp6T_LFXRQ4_NNfh';
update content_bodies set title = '埼玉西武ライオンズマスコットの行田冒険：忍城での甲冑武士との近接遭遇！', description = '行田のシンボルである忍城は、街の上空に優雅に浮かんでいます。明治時代に破壊された後、再建され、現在は過去を垣間見ることができる博物館として機能しています。また、城を訪れると、忍城の武士たちによる迫力ある剣戟のパフォーマンスや、ショー後の写真撮影の機会を楽しむことができます。勇敢なパフォーマーの中には英語を話せる人もおり、短いツアーを提供したり、食事スポットを推薦したりしてくれます。美しい行田市の風景を体験し、武士たちと出会いましょう！' where id = 'QA_eLJVHknM9t-xmnb4UY';
update content_bodies set title = 'Saitama Seibu Lions Mascot''s Gyoda Adventures: Close Encounters with Armored Samurai at Oshi Castle!', description = 'Oshi Castle, a prominent symbol of Gyoda, majestically overlooks the city. Originally destroyed during the Meiji Era, it has been reconstructed and now functions as a museum showcasing its historical significance. Visitors can enjoy thrilling performances by the Oshi Castle warriors, which include exciting swordfights and opportunities for post-show photos with the brave fighters. Some performers are fluent in English and can provide short tours or recommend local dining spots. Experience the stunning scenery of Gyoda City at Oshi Castle, where the warriors are eager to meet you!' where id = 'mGroJsY6C4ThsHnY8Jk0t';
update content_bodies set title = '埼玉西武ライオンズマスコットの行田冒険：世界に一つだけの日本の足袋を作ろう！', description = '行田市にある足袋と暮らしの博物館では、日本の足袋作りの技術や職人技を直接体験できます。1930年代、行田市は日本一の足袋生産地となり、全国の約80％を占めていました。2017年には、足袋工房の従業員の生活を描いたドラマ『陸王』が放送され、行田市は再び注目を集めました。工場の海外移転や伝統的な着物を着る人の減少により足袋の生産は減少していますが、行田市では職人が手作りした足袋を購入できます。訪問者は自分の好きな生地を選び、職人がその生地を使って足袋を作る様子を見学できます。博物館は改装された工場で、足袋の歴史を深く知ることができます。足袋は伝統的な服装でなくても履けるため、贈り物やお土産にも最適です。行田市を訪れて、この timeless craft を体験してみませんか？' where id = '_fzlm86jiTFJ7ZFH0Y3Yg';
update content_bodies set title = 'Saitama Seibu Lions Mascot''s Gyoda Adventures: Making One-Of-A-Kind Japanese Tabi Socks!', description = 'At the Tabi to Kurashi Museum in Gyoda City, visitors can experience the craftsmanship of Japanese tabi socks. Gyoda City was the leading tabi manufacturer in Japan during the 1930s, producing about 80% of the nation''s tabi. The city gained renewed attention with the 2017 drama ''Rikuoh,'' which highlights the lives of tabi workshop employees. Despite a decline in tabi production due to factory relocations and fewer people wearing traditional kimonos, expertly crafted tabi are still available in Gyoda City. Visitors can select their own fabric and watch as skilled artisans create their custom tabi, explaining each step of the process. The museum, housed in a renovated warehouse, offers a glimpse into the history of tabi. Tabi can be worn as socks even without traditional clothing, making them perfect gifts or souvenirs. A visit to Gyoda City promises an engaging experience with this timeless craft.' where id = '8-5XzG27CX4U8WEgitAf1';
update content_bodies set title = '城峯公園は日本の三大冬桜で知られています。', description = '城峯公園は、600本の珍しい「十月桜」と呼ばれる冬桜で知られています。冬桜は通常10月中旬から咲き始め、冬の時期に楽しむことができます。また、11月上旬からは紅葉が始まり、11月中旬には冬桜と紅葉を同時に楽しむことができる貴重な時期となります。この時期は紅葉のピークでもあり、木々は鮮やかな赤色に染まります。' where id = 'Y4AgjJWQE7GoiwxWXdMSz';
update content_bodies set title = 'Jomine Park is known for Japan’s big three winter cherry blossoms.', description = 'Jomine Park is famous for its unique winter cherry blossoms, particularly the rare ''October cherry blossom'' variety, with 600 trees in total. These blossoms typically begin to bloom in mid-October, allowing visitors to enjoy them during the winter months. The park is also known for its stunning autumn foliage, which starts changing color in early November. By mid-November, visitors can experience the rare opportunity to see both the winter cherry blossoms and the vibrant autumn leaves simultaneously, as this is the peak time for fall colors, with trees displaying bright red hues.' where id = 't2y2VHHCrCJJ7Ix0CC1Zu';
update content_bodies set title = '東京から約90分で行ける秋のランザン渓谷のハイキング', description = 'ランザン渓谷では美しい秋の色彩と渓谷の風景を楽しむことができ、1928年に京都の有名な嵐山に似ていることから「武蔵の国の嵐山」と名付けられました。嵐山とランザンは日本語で同じように書かれます。それ以来、秋のシーズンには多くの観光客が訪れています。秋のシーズンは一般的に11月下旬から12月上旬までです。' where id = 'xIGXvu7X7iCE-JhJq6rNY';
update content_bodies set title = 'Hike with the autumn leaves of Ranzan Valley from Tokyo it takes about 90 minutes', description = 'Ranzan Valley offers stunning autumn colors and scenic views, earning the nickname ''Arashiyama of Musashi country'' in 1928 due to its resemblance to Kyoto''s famous Arashiyama. The names Arashiyama and Ranzan are written the same way in Japanese. Since then, the valley has attracted many tourists during the autumn season, which typically lasts from late November to early December.' where id = 'Zg0BIjIAv2vEzSTdvvn1a';
update content_bodies set title = 'COEDOビールレストラン「WoodBakers」江戸川越', description = '川越でお腹が空いたときには、WoodBakersで新鮮なピザとCOEDOビールを楽しむことができます。英語のメニューも用意されており、外国人客にも便利です。特におすすめは、モッツァレラチーズがたっぷりのマルゲリータピザで、COEDOビールとの相性も抜群です。ピザは石窯で丁寧に作られ、チーズがとろける完璧な焼き加減で提供されます。ピザの他にも、パスタやデザートなど多彩な料理が揃っています。' where id = 'Q23HsgOAL7my7cMQ5H-Ra';
update content_bodies set title = 'COEDO BEER Restaurant ''WoodBakers'' Edo Kawagoe', description = 'WoodBakers in Kawagoe offers freshly made pizza and Coedo Beer, perfect for satisfying your hunger. The restaurant provides an English menu, making it accessible for international visitors. A highlight is the Margarita pizza, which is generously topped with mozzarella cheese and pairs well with COEDO BEER. Each pizza is carefully crafted in a stone oven, ensuring a perfect cook with melted cheese. In addition to pizza, the menu features a variety of other dishes, including pasta and desserts.' where id = 'F_NkKg1ZFKJFk8tdHxCcU';
update content_bodies set title = 'COEDOビールバー「アートカフェエレバート」江戸川越', description = '散策の後に休憩するのにおすすめなのが、アートカフェエレバートです。このカフェは西洋風の建物にあり、周囲の江戸様式の日本建築と鮮やかな対比を成しています。川越で作られたクラフトビール「コエドビール」を楽しむことができ、店の前でも販売されているため、町を散策しながら飲むこともできます。営業時間は午前11時から午後6時までで、住所は埼玉県川越市仲町6-4、350-0065です。' where id = '3sevc7sqQc25IS8_x7ucT';
update content_bodies set title = 'COEDO Beer Bar ''Art Cafe Elevato'' Edo Kawagoe', description = 'Art Cafe Elevato is a recommended spot to take a break after exploring the area. This cafe is housed in a Western-style building, which contrasts sharply with the traditional Edo-style architecture of the surrounding streets. Visitors can enjoy craft beer from Kawagoe, known as ''Coedo Beer,'' at the cafe. Additionally, Coedo Beer is available for purchase outside the shop, allowing guests to sip while strolling through the town. The cafe operates from 11 am to 6 pm and is located at 6-4, Nakacho, Kawagoe-shi, Saitama, 350-0065, Japan.' where id = 'nXMgt7w5fWMNBifvghKW7';
update content_bodies set title = '京浜東北線ツアー', description = '京浜東北線ツアーでは、埼玉県の魅力を紹介します。まず、埼玉新都心は様々な施設が揃った現代的な都市エリアです。浦和の十日町祭りでは、地元の文化や伝統を体験できます。また、浦和名物のうなぎも楽しめるグルメスポットです。大宮の武蔵一宮氷川神社は重要な文化的な場所であり、川口の川口西公園はリラックスやレクリエーションに最適な静かな環境を提供しています。このツアーは、埼玉の現代性と伝統の融合を体現しています。' where id = 'XB4vMEOUK5HHz5gUblzU6';
update content_bodies set title = 'Keihin Tohoku Line Tour', description = 'The Keihin Tohoku Line Tour offers a glimpse into the attractions of Saitama Prefecture. Key highlights include Saitama Shintoshin, a modern urban area with various facilities. The Juninchimachi Festival in Urawa showcases local culture and traditions. Food enthusiasts can enjoy grilled eel, a specialty of Urawa. Additionally, the Musashi-Ichinomiya Hikawa Shrine in Omiya is a significant cultural site, while Kawaguchi-Nishi Park in Kawaguchi provides a serene environment for relaxation and recreation. This tour encapsulates the blend of modernity and tradition in Saitama.' where id = 'FhLik56nVUgzHjzz4FRtn';
update content_bodies set title = '埼玉花巡り', description = '埼玉花巡りでは、四季折々の美しい花々を楽しむことができます。真っ赤な彼岸花、鮮やかなコスモス、優雅なダリアなどが見られます。秋には豊かな紅葉が広がり、冬には繊細な桜やロウバイの美しさが楽しめます。春には桜と菜の花の素晴らしい組み合わせが見られ、初夏には色とりどりのアジサイや花菖蒲が咲き誇ります。また、古代ハスも紹介されており、この地域の花の遺産を垣間見ることができます。' where id = '5I6Kel9fYMGkOqQYtqfW2';
update content_bodies set title = 'Saitama Flower Tour', description = 'The Saitama Flower Tour showcases a variety of beautiful flowers throughout the seasons. Visitors can enjoy the stunning red spider lilies, vibrant cosmos, and elegant dahlias. In the fall, the landscape transforms with rich autumn colors, while winter brings the delicate beauty of cherry blossoms and wintersweet. Spring features a delightful mix of cherry blossoms and canola flowers, followed by the lush hydrangeas and irises in early summer. The tour also highlights the ancient lotus, offering a glimpse into the region''s floral heritage.' where id = '0a-FkSyKFLyjWwSzxch0V';
update content_bodies set title = '埼玉西武ライオンズマスコットの川越冒険：小江戸の街を人力車で巡ろう！', description = '埼玉西武ライオンズのマスコット、レオとリナが川越市の「小江戸」として知られる伝統的な倉庫街を人力車で巡る冒険に参加します。この動画では、川越の伝統的な時の鐘や、江戸時代の建物が残る倉造りの倉庫街を訪れます。人力車に乗ることで、川越の歴史的な雰囲気を異なる視点から体験でき、注目を集めること間違いなしです。レオとリナと一緒に、川越の観光名所を楽しみながら写真を撮る素晴らしい時間を過ごしましょう。' where id = 'dZ7BruewvnuHln8lETE8h';
update content_bodies set title = 'Saitama Seibu Lions Mascot''s Kawagoe Adventures: Ride a Rickshaw Through Koedo''s Streets!', description = 'Join Leo and Lina, the mascots of the Saitama Seibu Lions, as they embark on an adventure in Kawagoe City, known as ''Koedo'' or Little Edo. In this video, they ride a rickshaw through the historic warehouse district, visiting iconic sites like Toki no Kane, the traditional time bell tower, and the kurazukuri warehouse area, which showcases some of the few remaining Edo Period buildings in Tokyo. The rickshaw ride offers a unique perspective of Kawagoe''s rich history and charm, making it a delightful experience for visitors. Leo and Lina enjoy taking pictures and exploring the sights, and viewers are encouraged to share in the fun of this stylish travel experience.' where id = 'ZjbtTKQ0F6NoHHhWjxecD';
update content_bodies set title = '埼玉西武ライオンズマスコットの川越冒険：お菓子の小道を食べ歩こう！', description = '埼玉西武ライオンズのマスコット、レオとリナが川越市の「お菓子の小道」を食べ歩く様子を紹介します。この場所は伝統的なお菓子で有名で、シンプルな材料を使ったお菓子を専門に扱うお店が並び、今でも多くの人に愛される懐かしい味を楽しむことができます。動画では、レオとリナが、いもけんぴ（甘いさつまいもフライ）、アイスクリーム、巨大ふがしなどのクラシックなお菓子を試食しながら、伝統的な雰囲気を楽しんでいます。また、動画には登場しませんが、タマリキというお店では、訪問者が小さな工場でのキャンディ作りの様子を見学でき、新鮮なお菓子を一年中楽しむことができます。川越は西武新宿線本川越駅から徒歩15分の距離にあります。' where id = 'p8V1eCJSNJNBAQCr5TBcN';
update content_bodies set title = 'Saitama Seibu Lions Mascot''s Kawagoe Adventures: Eat Your Way Through Penny Candy Lane!', description = 'Join Leo and Lina, the mascots of the Saitama Seibu Lions, as they explore Kawagoe City''s Penny Candy Lane, a place famous for its traditional sweets. The shops here focus on simple ingredients, preserving the nostalgic flavors that many still enjoy today. In the video, Leo and Lina sample a variety of classic candies, including imo kenpi (candied sweet potato fries), ice cream, and giant fugashi, all while soaking in the traditional atmosphere of the street. Although not featured in the video, visitors can also observe the candy-making process at Tamariki, a shop that showcases its small factory and fresh candies throughout the year. Kawagoe is easily accessible, located a 15-minute walk from Honkawagoe Station on the Seibu Shinjuku Line.' where id = 'H5RRRbYF6rxeLn65llRyE';
update content_bodies set title = '埼玉西武ライオンズマスコットの川越冒険：川越氷川神社で「恋の運」を試そう！', description = '埼玉西武ライオンズのマスコット、レオとリナが1500年の歴史を持つ有名な恋愛成就スポット、川越氷川神社を訪れます。この神社は幸せな夫婦の霊を祀り、恋愛運を求める多くの人々が訪れます。動画では、レオとリナが神社の縁結び風鈴を鳴らしたり、運勢を占ったりする様子が紹介されています。訪れる人々は、風鈴に吊るした願い事が風鈴が鳴ると叶うと信じています。また、愛を占う「愛鯛」も楽しめ、赤い糸の鉛筆を使うことで、運命の人との距離を縮めることができます。川越氷川神社は埼玉県川越市宮下町2-11-3にあり、本川越駅からバスや徒歩でアクセス可能です。' where id = 'lXSPQCa6UVNUgSBy1_Iv6';
update content_bodies set title = 'Saitama Seibu Lions Mascot''s Kawagoe Adventures: Try Your ''Luck in Love'' at Kawagoe Hikawa Shrine!', description = 'Join Leo and Lina, the mascots of the Saitama Seibu Lions, as they explore Kawagoe Hikawa Shrine, a renowned matchmaking site with a 1500-year history. The shrine honors the spirits of happily married couples and attracts many visitors seeking love. In the video, Leo and Lina engage in traditional activities like ringing matchmaking wind chimes and fishing for fortunes. Visitors believe that wishes written on paper hung from the wind chimes will come true when they ring clearly. The shrine hosts a popular event featuring these picturesque wind chimes, drawing young couples each year. Additionally, the ai-tai fortune fishing offers a playful way to predict love luck, while using a red thread pencil symbolizes the gradual closeness to a loved one. Kawagoe Hikawa Shrine is located at 2-11-3 Miyashitamachi, Kawagoe City, Saitama Prefecture, accessible by a short bus ride or walk from Honkawagoe Station.' where id = '0VgSWALjnN0b1PBULO4qU';
update content_bodies set title = '東武東上線ツアー', description = '東武東上線ツアーは、埼玉県のさまざまな観光名所を探索するユニークな機会を提供します。見どころには、川越の有名な鐘楼「時の鐘」や、興味深い地質形成で知られる「百穴」が含まれています。また、亡くなった子供たちの霊を祀る「水子供養公園」の静けさを楽しむことができます。さらに、伝統的な「流鏑馬」は、日本の豊かな文化遺産を披露します。最後に、須賀屋館跡と嵐山歴史博物館は、この地域の歴史と考古学的重要性についての洞察を提供します。' where id = 'rKx-h9R4XYD-o_kfyCG27';
update content_bodies set title = 'Tobu Tojo Line Tour', description = 'The Tobu Tojo Line Tour offers a unique opportunity to explore various attractions in the Saitama region. Highlights include the historic Toki no Kane, a famous bell tower in Kawagoe, and the Hundreds Caves of Yoshimi, known for their fascinating geological formations. Visitors can also enjoy the serene MizukoKaiduka Park, which is dedicated to the spirits of deceased children. Additionally, the traditional Yabusame, a horseback archery event, showcases Japan''s rich cultural heritage. The Sugaya Yakata Ruins and the Historical Museum of Ranzan provide insights into the area''s history and archaeological significance.' where id = '7daKNZ9Ieg1K-VxiaQp0R';
update content_bodies set title = 'ガリガリ君アイスキャンディ工場見学', description = 'ガリガリ君アイスキャンディ工場見学は、この人気の日本のアイスキャンディの製造過程を探るユニークな機会を提供します。見学は約90分で、入場料は無料です。参加者は、10:00、13:00、15:00のスケジュールに従ってツアーに参加できます。工場の所在地は、埼玉県本庄市児玉町児玉850-10、367-0212です。この体験は、埼玉での楽しいアクティビティを探している方や、東京からの短い旅行に最適です。' where id = 'GQEYJRnqpIisPKLhML6KR';
update content_bodies set title = 'Gari Gari Kun Ice Candy Factory Tour', description = 'The Gari Gari Kun Ice Candy Factory Tour offers a unique opportunity to explore the production of this popular Japanese ice candy. The tour lasts approximately 90 minutes and is free of charge. Visitors can join the tour at scheduled times: 10:00, 13:00, and 15:00. The factory is located at 850-10, Kodamacho Kodama, Honjo-shi, Saitama, 367-0212, Japan. This experience is perfect for those looking for fun activities in Saitama, especially for short trips from Tokyo.' where id = 'ro7fxlN6CmiQhXZ6oIbZu';
update content_bodies set title = '東武伊勢崎線（スカイツリー）ツアー', description = '東武伊勢崎線ツアーでは、埼玉県のさまざまな観光名所を楽しむことができます。特に、華やかなコスモスの花が見られる羽生コスモス花祭りが魅力です。また、埼玉水族館では多様な海洋生物を観察でき、渡良瀬湿地では自然の生態系を体験できます。さらに、文化的な重要性を持つ鷲宮神社や、さまざまな動物がいる東武動物公園も訪れることができます。加須の大凧や、草加松原の散策路も楽しめるため、自然と文化を満喫できる充実した体験が待っています。' where id = 'edASlWs-UzDQsWIdGA_mw';
update content_bodies set title = 'Tobu Isesaki (Sky Tree) Line Tour', description = 'The Tobu Isesaki Line Tour offers a variety of attractions in the Saitama region, including the Hanyu Cosmos Flower Festival, which showcases beautiful cosmos flowers. Visitors can explore the Saitama Aquarium, known for its diverse marine life, and the Watarase Wetland, a natural habitat for various species. The tour also includes a visit to the Washinomiya Shrine, a significant cultural site, and the Tobu Zoo, which features a range of animals. Additionally, guests can enjoy the big kites of Kasukabe and take a scenic walk along the Soka-Matsubara Walking Trail, making it a comprehensive experience of the area''s natural and cultural offerings.' where id = 'LFmVR9NWkWEd-OoXJN2V7';
update content_bodies set title = '西武線ツアー', description = '西武線ツアーでは、狭山エリアのさまざまな観光スポットを楽しむことができます。ジョンソンタウンはユニークなショッピングとダイニングの目的地で、訪れる人々に魅力を提供します。また、狭山スキー場でウィンタースポーツを楽しんだり、西武園遊園地で遊んだり、川越の歴史的な名所である時の鐘や賑やかな川越祭りを探索したりできます。さらに、入間の三井アウトレットパークでは多様なショッピングオプションが用意されています。' where id = 'hkkssbzU-7N0gmk7ll_mG';
update content_bodies set title = 'Seibu Line Tour', description = 'The Seibu Line Tour offers a variety of attractions in the Sayama area, including Johnson Town, a unique shopping and dining destination. Visitors can enjoy winter sports at Sayama Ski Resort, have fun at Seibuen Amusement Park, and explore the historical sites of Kawagoe, such as the iconic Toki no Kane bell tower and the vibrant Kawagoe Festival. Additionally, shopping enthusiasts can visit Mitsui Outlet Park in Iruma for a range of retail options.' where id = 'pdEzK150DHmrMmfEG75P0';
update content_bodies set title = '長瀞の桜トンネル', description = '長瀞は日本の桜名所100選に選ばれており、3000本以上の桜の木があります。4月には、長瀞の桜が一斉に開花します。特に、北桜通りと南桜通りでは、両側の木々が花のトンネルを形成し、壮観な景色を作り出します。また、宝登山神社へ向かう道沿いには、30種類の桜が並び、イルミネーションや並木道も楽しめます。桜の見頃は、例年4月上旬から中旬にかけてです。' where id = 'p5xahuRXwmxKbwCY0EQ6l';
update content_bodies set title = 'Nagatoro Cherry Blossom Tunnel', description = 'Nagatoro is recognized as one of Japan''s top 100 cherry blossom viewing spots, featuring over 3,000 cherry trees that bloom simultaneously in April. The most notable areas are Kita Sakura Dori Avenue and Minami Sakura Dori Avenue, where the trees create a stunning flower tunnel. Visitors can also enjoy illuminations and tree-lined paths, as well as a variety of 30 different cherry blossom types along the road leading to Hodosan Shrine. The cherry blossom season typically lasts from early to mid-April.' where id = 'VtoONuswwJ29D2fzO_9wd';
update content_bodies set title = '熊谷桜', description = '熊谷桜は江戸時代から知られる桜の名所で、約500本の吉野桜が植えられています。この美しいスポットは、JR埼京線の熊谷駅南口から徒歩5分の場所に位置しており、東京からの短い旅行に最適です。桜の花が満開の時期には、多くの訪問者がこの場所を訪れ、素晴らしい桜の景色を楽しむことができます。' where id = 'zuwV-SeYxkyTUhyRLkfcj';
update content_bodies set title = 'Kumagaya Cherry Blossom', description = 'Kumagaya Cherry Blossom is a renowned cherry blossom viewing location that has been appreciated since the Edo Era. It features nearly 500 Yoshino cherry trees, making it a picturesque spot for visitors. The site is conveniently located just a 5-minute walk from the South Exit of Kumagaya Station on the JR Saikyo Line, making it easily accessible for those traveling from Tokyo. This destination is ideal for a short trip, offering a beautiful experience of cherry blossoms in full bloom.' where id = 'Xvpts76C0ZZ6LZQ_OTErv';
update content_bodies set title = '川越の短い旅「江戸着物散策」', description = '川越の街を着物を着て散策してみませんか？川越には江戸時代の雰囲気が色濃く残っており、着物を着ることでその体験をより一層楽しむことができます。古い商家や蔵、さらには「時の鐘」として知られる川越の鐘楼を背景に写真を撮ることができます。さらに、毎月8日は「川越の着物の日」で、着物を着て参加店舗を訪れると特別割引が受けられます。ぜひ、川越の蔵造りエリアで江戸の体験を共にしましょう。アクセスは本川越駅から徒歩約10分です。詳細は川越観光のウェブサイトをご覧ください。' where id = 'OGqiYYz2mhUEBTYViuQSD';
update content_bodies set title = 'Kawagoe short trip ''Edo Kimono Walking''', description = 'Experience the charm of Koedo Kawagoe by wearing a kimono and strolling through the city. Kawagoe retains much of its Edo-era atmosphere, making it the perfect backdrop for a traditional kimono experience. Visitors can take photos in front of historic merchant homes, warehouses, and the iconic ''Bell of Time'' tower. Additionally, the 8th of each month is ''Kawagoe''s Kimono Day,'' offering exclusive discounts at participating stores for those dressed in kimono. Join us in reliving the Edo period in the Kuradzukuri area, just a 10-minute walk from Hon-Kawagoe Station. For more information, visit the Koedo Kawagoe Tourism website.' where id = 'fUI5Up1m_P0KoSt-XZ-Pw';
update content_bodies set title = '黄とピンクの花の権現堂公園の桜', description = '権現堂公園は、約1,000本の桜の木が1キロメートルにわたって並ぶ有名な桜の名所です。埼玉県の幸手市内の内郷間地区に位置し、東武日光線の幸手駅から徒歩35分、または「五霞町役場」行きの朝日バスに乗り、「権現堂」で下車することでアクセスできます。この公園は菜の花でも知られており、訪れる人々にとって美しいスポットとなっています。' where id = 'l0-oTRdhyozVEbhX2gzoq';
update content_bodies set title = 'Yellow & Pink Flower Gongendo Park Cherry Blossom', description = 'Gongendo Park is a renowned cherry blossom viewing location featuring nearly 1,000 cherry trees that line a 1 km stretch. Located in the Uchigouma district of Satte City, it is accessible by a 35-minute walk from Satte Station on the Tobu Nikko Line or by taking the Asahi Bus to ''Gokamachi Yakuba'' and getting off at ''Gongendo''. This park is also known for its canola flowers, making it a picturesque spot for visitors.' where id = 'cvcHk3cvZ2eLEOKyuLtFp';
update content_bodies set title = '桃の花の里 東秩父', description = '東秩父の桃の花の里は、春の美しさで知られ、「楽園」として親しまれています。鮮やかな桃の花が山々を彩り、訪れる人々に自然の魅力を提供します。この美しいエリアは、観光客にとって人気のスポットであり、春の花見を楽しむのに最適です。アクセスは、東武東上線の小川町駅からエーグルバスで25分、または寄居駅から10分のバスに乗り、その後40分の徒歩で到着します。' where id = '_mp5YtPqz3EueF6w3GfKI';
update content_bodies set title = 'A Village of Peach Blossoms  Higashichichibu Hanamomo no Sato', description = 'Higashichichibu Hanamomo no Sato, known as ''paradise'', is renowned for its stunning spring beauty, where vibrant peach blossoms paint the mountains in vivid colors. This picturesque area is a popular destination for those looking to experience the charm of nature during the blooming season. Visitors can access the site from Ogawamachi Station via a 25-minute bus ride or from Yorii Station with a 10-minute bus ride followed by a 40-minute walk.' where id = 'MD3Ij7-vs7HknMQD9TEw5';
update content_bodies set title = '盆栽は日本の伝統芸術！「大宮盆栽美術館」', description = '大宮は盆栽の聖地として知られています。大宮盆栽美術館では、季節に合わせた40〜50本の盆栽が庭に展示されており、伝統的な座席に合わせた盆栽の装飾や器のコレクションがホールに展示されています。隣接する大宮盆栽村では、実際の盆栽庭園も訪れることができます。また、今年の4月27日から30日には、埼玉で第8回世界盆栽大会が開催され、日本の誇る盆栽の最高峰を鑑賞することができます。この機会に埼玉を訪れて、盆栽芸術の美しさを体験してください。美術館へのアクセスは便利で、JR宇都宮線の東口から徒歩5分、東武野田線の大宮公園駅から徒歩10分です。' where id = 'pJd8Lp0Tox0oWfco5cxFN';
update content_bodies set title = 'Bonsai is Japanese traditional Art!  ”Omiya Bonsai Art Museum”', description = 'Omiya is renowned as a sacred place for bonsai. The Omiya Bonsai Art Museum features a seasonal display of 40 to 50 bonsai trees in its garden, alongside a collection of traditional bonsai decorations and vessels exhibited in the hall. Visitors can also explore the adjacent Omiya Bonsai Village, which showcases actual bonsai gardens. Additionally, the 8th World Bonsai Convention will take place in Saitama from April 27th to 30th, offering a chance to see some of Japan''s finest bonsai works. This event is a great opportunity to visit Saitama and experience the beauty of bonsai art firsthand. Access to the museum is convenient, being a short walk from Toro Station and Omiya Kouen Station.' where id = 'IOoClSaEDqedlNQTi5fjN';
update content_bodies set title = '三峰神社の朝日', description = '三峰神社は、数百年の歴史を持つ杉に囲まれた三年山の頂上に位置しています。山々に囲まれた境内は、澄んだ空気と共に感情の霊が包まれた爽やかな雰囲気を醸し出しています。また、壮大な彫刻が施された殿堂を含む多くの歴史的建物があります。アクセスは西武秩父駅からの直通バスがあり、また大物バス祭りから徒歩で約2.5時間のハイキングコースも楽しめます。神社内には温泉を楽しめる宿泊施設「吟竹閣」もあり、運が良ければ日の出時に雲海を見ることができます。雲海を楽しむためには、宿泊をお勧めします。' where id = 'yq9ssZFjFNQ-ZBDP3xu8Q';
update content_bodies set title = 'Mitsumine shrine at first light', description = 'Mitsumine Shrine is located at the summit of Sannen peak, surrounded by ancient cedar trees. The shrine''s precincts offer a refreshing atmosphere with clear air and a spiritual ambiance. Visitors can explore historical buildings, including a hall adorned with magnificent sculptures. Access is convenient with a direct bus from Nishitokichi Station, or a scenic 2.5-hour hike from the Oimono Bus Festival. The shrine also features the accommodation facility ''Yinchukaku,'' where guests can enjoy hot springs. For those lucky enough, witnessing a sea of clouds at sunrise is a breathtaking experience, making an overnight stay highly recommended.' where id = 'Fz_Fi1ut6-wD-y230KYx6';
update content_bodies set title = 'トーヴェ・ヤンソンあけぼの子どもの森公園', description = 'トーヴェ・ヤンソンあけぼの子どもの森公園は、北欧の童話の世界に迷い込んだような雰囲気を持つ美しい公園です。自然に囲まれたこの公園には、特徴的なキノコの家や入浴小屋があります。風景に魅了されて多くの人々が遠方から訪れ、大人たちも遊びのように楽しんでいます。また、写真撮影を楽しむ人々にも人気です。冬に春を待ちながら撮影された映像があり、秋には紅葉、初夏には新緑が美しく、四季折々の景色を楽しむことができます。池袋から約50分、最寄り駅からは徒歩20分の距離にあり、自然豊かなエリアでハイキングのように楽しむことができます。' where id = 'RNcEFTvg-uC4meAKvu1dV';
update content_bodies set title = 'Tove Jansson Akebono Children’s Forest Park', description = 'Tove Jansson Akebono Children’s Forest Park is a picturesque park that feels like a scene from a Northern European fairy tale. Surrounded by nature, it features a charming mushroom house and even a bathing shack. The park attracts many visitors, including adults who enjoy the whimsical atmosphere and take part in playful activities. It is also a popular spot for photography. The park showcases beautiful seasonal views, from winter waiting for spring to the vibrant autumn leaves and fresh greenery in early summer. Located about 50 minutes from Ikebukuro, it requires a 20-minute walk from the nearest station, making it a great place for hiking enthusiasts.' where id = 'T-YHIUTAcmzWCFW0JLq_a';
update content_bodies set title = '川越「江戸体験」東京からの日帰り旅行', description = '川越は「小江戸川越」と呼ばれ、古くから江戸のように発展してきた街です。150年前、武士の時代に東京は「江戸」と呼ばれていましたが、川越の街並みには、現代の東京では味わえない江戸のエッセンスが残っています。川越では、江戸の風情を感じながら、街の景観や着物、グルメ、ショップを楽しむことができます。川越への日帰り旅行は、歴史的な街を探索し、江戸の風味を楽しむ絶好の機会です。川越へのアクセスは、東武東上線、西武新宿線、JR川越線など、さまざまな鉄道で便利です。' where id = 'yP5SClWhgt2Q2QOvRzTQa';
update content_bodies set title = 'Kawageo ''Edo Experience'' Day trip from Tokyo', description = 'Kawagoe, known as KOEDO Kawagoe, has a rich history that reflects the essence of Edo, the name for Tokyo during the Samurai era 150 years ago. Unlike modern Tokyo, Kawagoe retains the traditional streets and atmosphere of Edo. Visitors can immerse themselves in the Edo experience through its cityscape, traditional kimono, gourmet food, and unique shops. A day trip to Kawagoe offers a chance to explore this historical city and enjoy its Edo flavor. Access to Kawagoe is convenient via various train lines, including the Tobu Tojo Line, Seibu Shinjuku Line, and JR Kawagoe Line.' where id = 'rQpLVTakFAZxvr8VeZffN';
update content_bodies set title = 'レオとリナが足立久保の氷柱に来た！', description = 'レオとリナは、足立久保の氷柱の美しさに感動しました。この場所では、甘酒や地元の茶を提供する「おもてなしレディ」など、さまざまな魅力があります。寒い気温にもかかわらず、心は温かく、氷柱の前ではダンスやパフォーマンスも行われています。足立久保の氷柱は、埼玉県秩父市横瀬町に位置し、西武秩父足立久保駅から徒歩10分でアクセスできます。午前9時から午後4時まで開放されており、入場料は中学生以上200円で、環境保全に寄付されます。入場券には甘酒または横瀬町の茶の無料ドリンクが含まれています。訪れるのに最適な時期は1月上旬から3月中旬です。' where id = 'f49u91GFVkNFxfRLLH554';
update content_bodies set title = 'Leo and Lina came to Ashigakubo''s Ice pillar!', description = 'Leo and Lina were captivated by the stunning beauty of the icicle at Ashigakubo. The site offers various attractions, including the ''Omotenashi Lady'' who serves sweet sake and locally brewed tea, adding to the charm of the experience. Despite the cold temperatures, the atmosphere is warm and inviting, with dances and performances taking place right in front of the icicle. Located in Yokoze-machi, Chichibu, Saitama, the Ashigakubo Icicle is accessible via a 10-minute walk from Seibu Chichibu Ashigakubo Station. Visitors can enjoy the icicle from 9:00 a.m. to 4:00 p.m. for a fee of 200 yen, which contributes to the environmental maintenance of the site. Each ticket includes a complimentary drink of sweet sake or Yokaze-machi tea. The best time to visit is from early January to mid-March.' where id = 'oalcHYoeETjnd95UO8DIq';
update content_bodies set title = 'レオとリナのこたつボート乗船！', description = 'レオとリナは埼玉の有名な町、長瀞を訪れました。冬の間、こたつが搭載されたボートでクルージングを楽しむことができます。この特別なボートでは、乗客が暖かく過ごせるため、二匹の友達はボートの中でみかんを食べながら、日本の冬の美しい景色を楽しみました。こたつボートは2017年1月1日から2月28日まで運行され、長瀞駅から徒歩3分でアクセス可能です。乗船料金は大人900円、3歳以上の子供500円です。川のボートは3月10日から再開予定で、料金は異なります。詳細については、長瀞川ボート情報センターにお問い合わせください。' where id = '5kRW-TCek0fOdpyIlSuSw';
update content_bodies set title = 'Leo and Lina Ride the Kotatsu Boat!', description = 'Leo and Lina visit Nagatoro, a famous town in Saitama, during winter to enjoy a unique experience on a Kotatsu boat. This special boat features a kotatsu, allowing passengers to stay warm while cruising. The two furry friends enjoy the scenic winter views of Japan while eating oranges inside the boat. The Kotatsu boat operates from January 1st to February 28th, 2017, and is accessible with a short walk from Nagatoro Station. The boarding fee is 900 yen for adults and 500 yen for children aged three and older. River boating is expected to resume on March 10th, with different fees. For more information, visitors can contact the Nagatoro River Boating Information Office.' where id = 'aIZpOkcxbQLKzW4rxKeGE';
update content_bodies set title = 'レオとリナが秩父のいちご狩りに来た', description = '秩父の農場では、大きくて赤いいちごが育っています。レオとリナは、両手を使っていちごを摘みながら楽しそうにしています。この農場では、自分で摘んだいちごを30分間好きなだけ食べることができます。秩父のいちごは、昼夜の温度差によって特に甘くなります。美味しいいちごを摘んで食べる体験にぜひ参加してください！いちご狩りのシーズンは1月から6月中旬までで、1月と2月は1700円から始まり、月によって価格が変動します。' where id = 'co9j3T3wjShSxpPDpb-y-';
update content_bodies set title = 'Leo and Lina Came to Chichibu''s Strawberry Picking', description = 'Leo and Lina are enjoying strawberry picking at a farm in Chichibu, where they can pick big, red strawberries. The farm allows visitors to eat as many strawberries as they can within 30 minutes after picking them. The Chichibu strawberries are known for their exceptional sweetness, attributed to the temperature variations between day and night. The strawberry picking season runs from January to mid-June, with prices starting at 1700 yen in January and February, varying by month. This is a delightful opportunity to experience the joy of picking and tasting fresh strawberries.' where id = 'pB7LjLHifW7ZCdfoqAeY5';
update content_bodies set title = '埼玉西武ライオンズのマスコットが埼玉のミッション観光大使に就任', description = '埼玉西武ライオンズのマスコット、レオとリナが埼玉のミッション観光大使（台湾部長）に就任しました。埼玉県知事から正式な任命状が手渡されました。レオは、台湾の観光客を引き寄せるために、アクロバットやパフォーマンスを通じて埼玉をPRしたいと述べました。リナは、台湾の人々と交流し、特に自分の誕生日である5月に秩父の芝桜を訪れることを勧めたいと語りました。レオとリナは、埼玉の観光情報を今後も発信していく予定です。' where id = 'TAr_OmlYRb7KtiMjlNN2e';
update content_bodies set title = 'Saitama Seibu Lions Mascot Took Office as Saitama''s Mission Tourism Ambassadors', description = 'The mascots of the Saitama Seibu Lions, Leo and Lina, have been appointed as Saitama''s Mission Tourism Ambassadors, specifically for Taiwan. The governor of Saitama presented them with an official appointment letter. Leo expressed his intention to promote Saitama through acrobatics and performances to attract Taiwanese tourists. Lina shared her desire to connect with the people of Taiwan and encourage them to explore Saitama''s attractions, particularly recommending a visit to Chichibu''s Shibazakura in May, which is her birthday month. Leo and Lina will continue to provide tourist information about Saitama.' where id = 'iqvgz7aVGwDSYRuex2Ya3';
update content_bodies set title = '日本の最速新幹線にファーストクラスで乗車 - グランクラス JR東日本', description = '日本のファーストクラス新幹線、グランクラスの体験は期待以上のものでした。著者は、この美しい列車に乗る機会を与えてくれたJR東日本に感謝の意を表しています。グランクラスのチケットは、公式サイトから予約可能です。また、著者は「観光名所を超えて」という旅行ガイドを紹介しており、東京と大阪の間にある120以上の隠れた名所が掲載されています。このガイドは著者のウェブサイトで入手できます。さらに、グッズ販売やPatreonでの追加コンテンツ、SNSのリンクも紹介されています。' where id = 'xYHdg-BsbEzYMY2fNIh1N';
update content_bodies set title = 'I Rode On Japan''s Fastest Bullet Train in FIRST CLASS Across The Country - Gran Class JR East', description = 'The experience of riding Japan''s first class bullet train, known as Gran Class, exceeded all expectations. The author expresses gratitude to JR East for the opportunity to travel on this beautiful train. For those interested in booking a ticket, it can be done through their website. Additionally, the author promotes a travel guide titled ''Beyond The Tourist Trail,'' which features over 120 hidden gems in Japan between Tokyo and Osaka. The guide is available on the author''s website. There are also links to merchandise, Patreon for extra content, and social media.' where id = 'sunaFNQmpbDlhrIKT_LHO';
update content_bodies set title = '首都圏外郭放水路', description = 'クレヨンしんちゃんで有名な春日部市にある首都圏外郭放水路は、河川の水位を制御するための巨大な地下神社です。この施設は、日本の先進技術を駆使しており、同時に水族館としても機能しています。その壮大さに驚かされることでしょう。埼玉県の地理に不慣れな方や、防水技術の複雑な説明が苦手な方も安心してください。訪問前に専門家が簡単に説明してくれます。この素晴らしい場所を訪れることに失望することはありません。地下神社（水族館）を見学するには予約が必要です。詳細は、提供されたリンクをご覧ください。' where id = '0UGRhlKfIjFBfsymKuVfB';
update content_bodies set title = 'Metropolitan Area Outer Underground Discharge Channel', description = 'The Metropolitan Area Outer Underground Discharge Channel, located in Kasukabe, a city known for Crayon Shin-Chan, features a remarkable underground shrine that serves as a water level control tank. Utilizing advanced Japanese technology, this facility also functions as an aquarium. Visitors will be impressed by its grandeur. For those unfamiliar with Saitama''s geography or complex waterproofing technologies, a professional will provide a simple explanation before the visit. Reservations are required to observe this unique underground temple and aquarium. For more information, visit the provided link.' where id = '-Eq2mDycY1u0hnpTuXgdF';
update content_bodies set title = 'クレヨンしんちゃんに会いに春日部へ！', description = '春日部ララガーデンスタジオシネマで開催される「25周年特別展」に参加しませんか？このイベントでは、人気フランチャイズの最初の映画「クレヨンしんちゃんVSヒュゲレ魔王」の再上映が行われます。また、しんちゃんのグッズもたくさん楽しめます。さらに、東武スカイツリーラインでは、クレヨンしんちゃんラッピング電車に乗ることができ、春日部での楽しい体験が待っています。展示は2016年11月3日から2017年3月31日まで、毎日午前10時から午後8時まで、春日部ララガーデンの3階、ゲームセンター「クレヨンしんちゃん嵐を呼ぶブリブリシネマスタジオ」で開催されます。' where id = 'DYJgVELnViA6I0uToTRvM';
update content_bodies set title = 'Meet Crayon Shin-Chan in Kasukabe!', description = 'Join the celebration of the 25th Anniversary Special Exhibition at the Kasukabe Lala Garden Studio Cinema. The event features a re-screening of the original movie ''Crayon Shin-Chan VS Hyigure Demon King'', marking a significant milestone in the beloved franchise. Attendees can also enjoy various Shin-Chan merchandise. Additionally, visitors can ride the Crayon Shin-Chan Wrapped Train on the Tobu Skytree Line, making it a fun-filled experience in Kasukabe. The exhibition runs from November 3, 2016, to March 31, 2017, and is open daily from 10 a.m. to 8 p.m. at LaLa Garden Kasukabe, located on the 3rd floor of the Game Center Crayon Shin-Chan Arashi no Yobu Buriburi Cinema Studio.' where id = 'qg87sct8zU7PEtFj2I-cS';
update content_bodies set title = '日本の驚異 | 誰も話さない隠れた場所！ | 旅行動画 4K', description = 'この旅行動画では、日本の隠れた驚異を紹介し、見落とされがちな美しい場所を特集しています。動画は日本の紹介から始まり、富士山、東京、伏見稲荷大社などの象徴的なスポットの美しい映像が続きます。また、白川郷、高野山、地獄谷野猿公苑など、あまり知られていない目的地も取り上げています。嵐山の竹林の美しさ、清水寺の歴史的意義、石垣島の穏やかな風景を体験できます。動画は、大阪、広島、札幌などのさまざまな都市を巡り、日本の多様な文化と自然の美しさを包括的に紹介します。' where id = 'Noi0EoXRkTMu8dX6thIIo';
update content_bodies set title = 'Wonders of Japan | The Hidden Places No One Talks About! | Travel Video 4K', description = 'This travel video showcases the hidden wonders of Japan, featuring breathtaking locations that are often overlooked. The journey begins with an introduction to Japan, followed by stunning visuals of iconic sites such as Mount Fuji, Tokyo, and Fushimi Inari Shrine. The video also highlights lesser-known destinations like Shirakawa-go, Koyasan, and the Jigokudani Monkey Park. Viewers will experience the beauty of the Arashiyama Bamboo Forest, the historical significance of Kiyomizu-dera Temple, and the serene landscapes of the Ishigaki Islands. The video concludes with a tour of various cities, including Osaka, Hiroshima, and Sapporo, providing a comprehensive look at Japan''s diverse culture and natural beauty.' where id = 'T0uSVis_OmdhWe2x4OS7k';
update content_bodies set title = '日本の驚異 | 日本の最も素晴らしい場所 | 旅行動画 4K', description = '「日本の驚異」は、豊かな文化と現代の驚異が融合した国、日本の魅力を紹介します。東京の賑やかな街並みから、京都の静かな寺院まで、旅行者を魅了するスポットが満載です。富士山や春の桜、伝統的な茶道など、誰もが楽しめる体験が待っています。先進的な技術と深い伝統が共存する日本は、ユニークで忘れられない体験を提供します。この動画では、日本の驚異に浸り、各地の魅力を発見する機会を逃さないよう呼びかけています。' where id = 'vqiS2T5aVDybeA8EWYFo9';
update content_bodies set title = 'Wonders of Japan | The Most Amazing Places in Japan | Travel Video 4K', description = 'Wonders of Japan showcases the country''s rich culture and modern marvels, blending ancient traditions with contemporary life. From the vibrant streets of Tokyo to the tranquil temples of Kyoto, this destination offers a captivating experience for every traveler. Highlights include iconic Mount Fuji, cherry blossoms in spring, and traditional tea ceremonies. Japan''s advanced technology coexists harmoniously with its deep-rooted customs, making it a unique place to explore. The video invites viewers to immerse themselves in the diverse wonders of Japan, where each location reveals fascinating aspects of this incredible nation.' where id = 'shgAHN47P7NWf-0Eat_Ds';
update content_bodies set title = '日本の驚異 | 日本の最も素晴らしい場所と興味深い事実 | 旅行動画 4K', description = 'この旅行動画では、日本の驚異を紹介し、国の最も素晴らしい場所や興味深い事実を強調しています。動画は日本の紹介から始まり、富士山や嵐山の竹林、清水寺などの象徴的な場所を取り上げています。他にも、石垣島、白川郷、厳島神社などの注目すべきスポットが紹介されています。また、北海道、沖縄、四国などの地域や、松本城や広島平和記念公園などの有名なランドマークもカバーされています。この視覚的な旅を通じて、日本の豊かな文化と美しい風景を探求することができます。' where id = '_D8vfsoEnmaRl9uVWMm1P';
update content_bodies set title = 'Wonders of Japan | Most Amazing Places and Interesting Facts in Japan | Travel Video 4K', description = 'This travel video showcases the wonders of Japan, highlighting some of the most amazing places and interesting facts about the country. The video begins with an introduction to Japan and features iconic locations such as Mount Fuji, Arashiyama Bamboo Forest, and Kiyomizu-dera Temple. Other notable sites include the Ishigaki Islands, Shirakawa-go, and Itsukushima Shrine. The video also covers various regions like Hokkaido, Okinawa, and Shikoku, along with famous landmarks such as Matsumoto Castle and the Hiroshima Peace Memorial Park. Viewers are invited to explore Japan''s rich culture and stunning landscapes through this visual journey.' where id = 'KQppr9VM_SZu9ZyDktz27';
update content_bodies set title = '東京のすぐ隣にある日本で最も見落とされがちなエリアの一人旅', description = 'この旅行ガイドは、東京の近くにある観光客にあまり知られていない美しいエリアを紹介しています。これらのスポットは、世界で最も賑やかな都市のすぐそばにありながら、観光客がほとんど訪れないことが特徴です。千葉観光局のスポンサーによるこのガイドでは、鋸山や可愛らしいカフェ、巨大な神像などのユニークなスポットを探索することを勧めています。また、キノコ狩りや長い吊りモノレールの乗車体験も紹介されています。さらに、東京と大阪の間にある120以上の隠れた名所を収めた電子書籍『Beyond The Tourist Trail』も宣伝されています。詳細は千葉観光局のインスタグラムをフォローしてください。' where id = 'ybAXJVfiP_gDEnVxb0ygt';
update content_bodies set title = 'Solo Travelling Japan''s Most Overlooked Area (right next to Tokyo!)', description = 'This travel guide highlights the lesser-known yet beautiful areas near Tokyo, showcasing how close they are to the bustling city while remaining largely untouched by tourists. Sponsored by Chiba Tourism, the guide encourages visitors to explore unique spots like Mt. Nokogiri, charming cafes, and a giant deity statue. It also features activities such as mushroom picking and a long suspended monorail ride. The guide promotes an e-book titled ''Beyond The Tourist Trail,'' which includes over 120 hidden gems between Tokyo and Osaka. For more information, follow Chiba Tourism on Instagram.' where id = 'uuUEZZbi3IBWkH73Nr2p3';
update content_bodies set title = '奈良県の十津川村でのスロートラベル - 日本の隠れた魅力を3日間探る', description = '著者は、日本の隠れた魅力が詰まった十津川村での体験を共有しています。この地域は非常に評価が低いが、素晴らしい場所がたくさんあると述べ、次回の訪問を計画していることを明かしています。記事では、十津川への公共交通機関の情報や、バスの時刻表、ハテナシ村やセイノ滝、ドロキョウ峡などの観光スポットが紹介されています。また、ユニークな体験を求める旅行者向けの電子書籍ガイドの提供や、ツアー予約のリンク、追加コンテンツへのアクセスについても言及されています。' where id = 'O1npEbGTiGJaVLVbnfe71';
update content_bodies set title = '3 Days Off-The-Beaten-Track in Japan - Slow Travel Through Totsukawa Village in Nara', description = 'The author shares their experiences in Totsukawa Village, an underrated area in Japan filled with hidden gems. They express excitement about discovering new locations and are already planning a return trip. The article provides practical information on public transport to Totsukawa, including train and bus schedules, and highlights various attractions such as Hatenashi Village, Seino Waterfall, and Dorokyo Gorge. The author also mentions the availability of an e-book guide for travelers seeking unique experiences in Japan, along with links to book tours and access additional content.' where id = 'zqYEa5ATOdo1CMM7SBqyH';
update content_bodies set title = '日本で最も過小評価されている町には予想外のひねりがある（大阪から公共交通機関でアクセス可能）', description = '著者は、大阪から公共交通機関でアクセスできる日本の好きなエリア、特に泥峡（Dorokyo Gorge）を紹介しています。過去3年間で8回訪れたことがあると述べています。動画では、無料キャンプ場、熊野本宮大社、川湯温泉、湯の峰温泉などのさまざまな観光スポットについての章が含まれています。公共交通機関が利用可能であるものの、泥峡へのバスは1日2本しかなく、帰りのバスは3本のみであることを明らかにしています。バスの所要時間は1時間6分で、料金は1,090円です。また、著者は「観光地を超えて」という旅行ガイドを宣伝しており、日本の120以上の隠れた名所を紹介しています。' where id = 'BXZWcLXbbwshFDP3zFPnN';
update content_bodies set title = 'Japan''s Most Underrated Town Has a Twist You Wouldn''t Expect (Close to Osaka via Public Transport)', description = 'The author shares their favorite area in Japan, accessible from Osaka via public transport, specifically highlighting Dorokyo Gorge. They mention having visited this location multiple times over the past three years. The video includes chapters on various attractions such as a free campsite, Kumano Hongu Taisha, Kawayuu Onsen, and Yunomine Onsen. The author clarifies that while public transport is available, there are limited bus services to Dorokyo Gorge, with only two buses a day going there and three returning. The bus ride takes over an hour and costs 1,090 yen. The author also promotes their travel guide, ''Beyond The Tourist Trail,'' which features over 120 hidden gems in Japan.' where id = 'I-jTmascMH6oFnJm3vXG4';
update content_bodies set title = '東京から大阪へのプライベート夜行バス', description = 'この動画では、東京から大阪へのプライベート夜行スリーパー バスの旅を紹介しています。料金は14,500円（約110ドル）で、使用されるバスはプレミアムクラス（1D）のドリームリライヤー17です。体験は「カーテンの呪いが解けた」と表現されており、快適で楽しい乗車を示唆しています。動画は、イントロダクション、ナビゲーションと料金の詳細、バスルームツアー、休憩所、トイレツアー、大阪到着の様子を含んでいます。最後には旅行のまとめと、安いたこ焼き屋のおすすめがあります。' where id = 'J7GsE2M48AERnJyNZLkGi';
update content_bodies set title = 'Tokyo to Osaka on Japan’s Private Overnight Bus', description = 'This video documents a journey on a private overnight sleeper bus from Tokyo to Osaka. The fare for the trip is 14,500 JPY (approximately 110 USD). The bus used for this journey is the Dream Relier 17, categorized as Premium Class (1D). The experience is described as having ''CURTAIN CURSE CURED,'' indicating a comfortable and enjoyable ride. The video includes various segments: an introduction, navigation and pricing details, a tour of the bus room, a rest stop, a washroom tour, and the arrival in Osaka. It concludes with a trip summary and a recommendation for a cheap takoyaki place.' where id = 'pvvRuhu23bgqB97MvwERn';
update content_bodies set title = '日本で最も人気のある紅葉スポットを目指して33km走った話（そして主張を証明するために）', description = '著者は、日本の上高地にあるカラス沢カールでのトレイルランニングの体験を共有しています。この場所は紅葉を楽しむための有名なスポットで、通常は6時間のハイキングと小屋での宿泊が必要ですが、小屋が満室だったため、著者は走ることを選びました。走っている間、著者は喜びを感じ続け、素晴らしい体験だったと述べています。また、著者は「観光名所を超えて」という旅行ガイドを宣伝しており、東京と大阪の間にある120以上の隠れた名所を紹介しています。さらに、グッズやPatreonのサポート、SNSのリンクも提供しています。' where id = 'pF6nlHqBlZwfpgnO-o_vQ';
update content_bodies set title = 'I Ran 33kms To See Japan''s Most Popular Autumn Leaves Spot (and prove a point)', description = 'The author shares their experience as a trail runner in Japan, specifically at Karasawa Cirque in Kamikochi, a renowned location for autumn leaves. The journey typically requires a six-hour hike and an overnight stay, but due to a full hut, the author opted to run the distance instead. They describe the experience as exhilarating and fulfilling, expressing joy throughout the run. Additionally, the author promotes their travel guide, ''Beyond The Tourist Trail,'' which features over 120 hidden gems in Japan, available on their website. They also provide links for merchandise, Patreon support, and social media.' where id = 'ShiNaNEbSBARVZk9_FyfQ';
update content_bodies set title = '日本の離島での4日間 - 隠岐諸島', description = '隠岐諸島は、日本の他のどこにもないユニークな体験を提供します。野生の馬、険しい崖、透き通った水、そして寺院の上に流れ落ちる滝があり、自然愛好家や秘境を求める冒険者にとっての楽園です。著者は、これらの島を訪れることを強く勧めており、忘れられない体験ができると述べています。また、日本の隠れた名所を探求したい旅行者のために、東京と大阪の間にある120以上のユニークな場所を紹介した旅行ガイド「Beyond The Tourist Trail」も利用可能です。隠岐諸島のフェリー時刻表や交通手段に関する情報も提供されており、さらに商品やソーシャルメディアへのリンクもあります。' where id = 'YcbW3GFBgUTYAvHUJckvF';
update content_bodies set title = '4 Days on the Remote Islands of Japan - Oki Islands', description = 'The Oki Islands offer a unique experience unlike any other place in Japan. With wild horses, rugged cliffs, crystal clear waters, and waterfalls cascading over temples, it is a paradise for nature lovers and those seeking off-the-beaten-path adventures. The author highly recommends visiting these islands for an unforgettable experience. Additionally, for travelers looking to explore more hidden gems in Japan, the travel guide ''Beyond The Tourist Trail'' is available, featuring over 120 unique locations between Tokyo and Osaka. Useful resources such as ferry timetables and transportation options around the Oki Islands are also provided, along with links to merchandise and social media for further engagement.' where id = 'UqqG6TRgvphFgUhQj2GPi';
update content_bodies set title = '箱根は過大評価されているのか？日本をジープで旅する', description = '著者は、訪れるべきとされる場所についての体験を振り返り、必ずしも期待に応えられるわけではないことを示唆しています。中には訪問者を物足りなく感じさせる場所もありますが、著者は富士山に対して強い敬意を表し、決して失望させないと述べています。また、ルーフトップテントや商品、追加コンテンツのためのPatreon、SNSのハンドル、音楽のクレジットなど、さまざまなリソースへのリンクも含まれています。' where id = 'MB9nlrzrp2Icd1xK76mhc';
update content_bodies set title = 'Is Hakone... Overrated? Living in my Jeep Around Japan', description = 'The author reflects on the experience of visiting highly recommended places, suggesting that not all of them meet expectations. While some locations may leave visitors feeling underwhelmed, the author expresses a strong admiration for Mt. Fuji, stating that it never disappoints. The content also includes links to various resources such as rooftop tents, merchandise, and Patreon for additional content, as well as social media handles and music credits.' where id = 'BMzKG0rd07tmZW_a1org-';
update content_bodies set title = '新潟の冬の魅力 - ウィークエンドトリップ', description = 'この週末、新潟が「雪国」と呼ばれる理由を発見しました。東京に住んでいた頃、近くに素晴らしい場所がたくさんあったことが恋しいです。新潟は美しい冬の風景が広がる完璧な週末の getaway です。この動画は新潟観光局のスポンサーによるもので、地域の真冬の魅力を紹介しています。私のコンテンツをサポートしたい方のために、グッズや Patreon での特別アクセスも用意しています。また、私のソーシャルメディアリンクや好みの宿泊施設、撮影機材の詳細もご覧いただけます。' where id = 'fqwOz-jlmsetTpFCWUKr9';
update content_bodies set title = 'The Best of Japanese Winter in Niigata - A Weekend Trip', description = 'This weekend, I discovered why Niigata is known as ''Snow Country.'' Living in Tokyo, I miss the proximity to such amazing destinations. Niigata offers a perfect weekend getaway with its beautiful winter scenery. The video is sponsored by Niigata Tourism, showcasing the midwinter delights of the region. For those interested in supporting my content, I have merchandise available and a Patreon for exclusive access. You can also find my social media links and details about my preferred accommodation and filming gear.' where id = 'BHNEPMCfa6n5qm7IG7GPM';
update content_bodies set title = '富士山周辺をキャンピングカーで旅した話 - 静岡、日本', description = 'この動画では、5人の友人と共に静岡と富士山周辺をキャンピングカーで3日間旅した体験を共有しています。多くの困難に直面しましたが、それでも私にとって最も楽しい旅行の一つとなりました。訪れた美しい場所には、河口湖、富士吉田フォトストリート、城ヶ崎海岸などがあります。また、旅の途中でFPVドローンとGoPro 9を失ったことについても触れています。さらに、Airstream Caravelと2021年型Ford F-150を獲得するチャンスがある支援のリンクを紹介しています。追加コンテンツについてはPatreonをチェックし、Instagramでもフォローしてほしいと呼びかけています。' where id = '9qiul8aO8zq3yfOOUZQ2x';
update content_bodies set title = 'I Rented a Camper Van To Roadtrip Around Mt Fuji - Shizuoka, Japan', description = 'In this video, I share my experience of a three-day road trip around Shizuoka and Mt. Fuji with five friends in a camper van. Despite facing several challenges, it turned out to be one of the most enjoyable trips I''ve ever had. We visited various beautiful locations, including Lake Kawaguchi, Fujiyoshida Photo Street, and the Jogasaki Coast, among others. I also mention the unfortunate loss of my FPV drone and GoPro 9 during the trip. Additionally, I encourage viewers to support a cause by visiting a link for a chance to win an Airstream Caravel and a 2021 Ford F-150. For more content, I invite them to check out my Patreon and follow me on Instagram.' where id = '5N2iQ9rMTYKHZBh7WZIGQ';
update content_bodies set title = '秋のワンダーランド！奈良を秋に一人旅、4K', description = '著者は奈良を訪れる前に期待があまり高くなかったが、実際に訪れてみてその期待を大きく上回る体験をした。公園では美しい秋の葉を楽しむだけでなく、野生動物と触れ合うことができるというユニークな体験ができる。著者は奈良が過大評価されているわけではなく、むしろ過小評価されているかもしれないと感じている。この動画は秋の奈良の美しさを紹介し、一人旅の楽しさを強調している。' where id = 'jFpKPpZGXrseeJLq_r1vG';
update content_bodies set title = 'An Autumn Wonderland! Solo Travelling Through Nara in Fall, 4K', description = 'The author had medium-low expectations before visiting Nara but was pleasantly surprised by the experience. The park offers a unique opportunity to enjoy beautiful autumn leaves while interacting with wild animals, making it an extraordinary destination. The author believes that Nara is not overrated and may even be underrated as a travel spot in Japan. The video showcases the beauty of Nara in the fall and highlights the joy of solo travel.' where id = 'qYhLiDFdn6maSz5HYkKuL';
update content_bodies set title = '九州でのバケットリストを消化 - バーナード・フォーリーと共に！4K', description = 'この動画では、スポーツが苦手な私がバーナード・フォーリーと共に九州での3日間を過ごした様子をお届けします。福岡、大分、熊本の各県を巡り、醤油工場やラグビーワールドカップ、阿蘇山でのサイクリングなど、さまざまなアトラクションを楽しみました。楽しいアクティビティに満ちたこの体験を、視聴者の皆さんにも楽しんでいただければと思います！' where id = 'EYPc_DNf9An8D6GBf9QT6';
update content_bodies set title = 'Ticking Things Off The Bucket List in Kyushu, Japan - With Bernard Foley! 4K', description = 'In this video, I spent three exciting days in Kyushu, Japan, with rugby player Bernard Foley, despite my lack of sports skills. We explored various attractions in Fukuoka, Oita, and Kumamoto prefectures, including soy sauce factories, the Rugby World Cup, and biking around Mt. Aso. The experience was enjoyable and filled with fun activities. I hope viewers enjoy the journey as much as we did!' where id = 'PRZuY3iYbBZPPpo6fvO4q';
update content_bodies set title = 'ルーフトップテントでの日本のオーバーランドキャンプ - 新潟・長野', description = 'この動画では、ホストが新潟と長野を巡る日本のロードトリップの体験を共有しています。東京から始まり、可愛らしいスズキ・ジムニー・シエラを使用しての旅です。カップルはルーフトップテントに夢中になり、旅の途中で購入を検討するほどです。訪れた主な場所には、清津峡、北陸キャンプ場、苗名滝、野尻湖、ソー滝、燕温泉が含まれています。動画はStoryblocksのスポンサーによるもので、ホストのグッズやPatreonでのサポートも紹介されています。' where id = 'e0KKb6pmK5gaGk7jdfzL-';
update content_bodies set title = 'Overland Camping Through Japan with a Rooftop Tent - Niigata & Nagano, Japan', description = 'In this video, the host shares their exciting road trip experience through Japan, specifically in Niigata and Nagano, while using a rooftop tent. The journey begins in Tokyo and features a charming Suzuki Jimney Siera. The couple expresses their newfound obsession with rooftop tents and even considers purchasing one during the trip. Key locations visited include Kiyotsu Gorge, Hokuryuko Camping Ground, Naena Falls, Lake Nojiri, So Falls, and Tsubame Onsen. The video is sponsored by Storyblocks, and viewers are encouraged to check out the host''s merchandise and support her on Patreon for additional content.' where id = 'bkzDYeP1YtmbruUr-1scm';
update content_bodies set title = '四国の一人旅', description = '四国は著者のお気に入りの地域であり、最近の旅行で多くのアクティビティがあることを再認識しました。この旅行は四国観光のスポンサーによるもので、著者はこの旅を非常に深く、リラックスでき、洞察に満ちた体験として表現しています。香川、高知、徳島の各地域のユニークな魅力を強調し、観光サイトへのリンクも紹介しています。また、著者をPatreonでサポートする方法や、SNSでの情報発信についても触れています。動画で使用した音楽や宿泊施設の情報も共有されています。' where id = 'TE2P8sJ0tHab_GZjB6MOQ';
update content_bodies set title = 'Solo Travelling Shikoku, Japan', description = 'Shikoku is a favorite region of Japan for the author, who discovered an abundance of activities during their recent trip. Sponsored by Shikoku tourism, this journey was described as one of the most in-depth, relaxing, and insightful experiences. The author expresses gratitude for the opportunity to explore the area, highlighting the unique offerings of Kagawa, Kochi, and Tokushima. The video includes links to tourism sites for each region, as well as information on supporting the author through Patreon and social media. Additionally, the author shares resources for music used in the video and preferred accommodation options.' where id = 'xopsM_gRmh-8JTdFPXEJF';
update content_bodies set title = '廃墟のモール、谷のキャンプ、そして犬の仲間！日本の夏 - 天川、奈良', description = 'この動画は、日本の夏の本質を捉え、小さな犬の仲間と旅行する喜びを強調しています。クリエイターは、このような冒険を続けたいという思いを表現しています。次回のコンテンツには、初めてのソロジープオーバーランディング体験が含まれ、非常に楽しみです。視聴者は、追加コンテンツや早期アクセスのためにPatreonでのサポートを促されています。また、ソーシャルメディア、音楽リソース、好みの宿泊施設のリンクも提供されています。' where id = 'xYtDzpXBAfjOs8286is0Z';
update content_bodies set title = 'Abandoned Malls, Valley Camping and a Dog Companion! Japanese Summer - Tenkawa, Nara', description = 'This video captures the essence of summer in Japan, highlighting the joy of traveling with a small dog companion. The creator expresses a desire to continue such adventures. Upcoming content includes a solo Jeep overlanding experience, which promises to be exciting. Viewers are encouraged to support the creator on Patreon for additional content and early access. Links to social media, music resources, and preferred accommodation options are also provided.' where id = 'Ay2N2qZhi8kHAs6uU1YyI';
update content_bodies set title = '日本の隠れた滝のオアシスと伝統的な宿場町へのハイキング - 三重と長野', description = 'この動画では、日本の隠れた滝のオアシスへの美しいハイキング旅行と、三重と長野の伝統的な宿場町の訪問が紹介されています。制作者は、素晴らしい景色に興奮し、これが新しいお気に入りの週末旅行かもしれないと述べています。視聴者は、サブスクリプションボックスの割引を受けるためのリンクを通じてチャンネルをサポートするよう促されており、Patreonで追加コンテンツにアクセスすることもできます。また、制作者は自身のSNSアカウントや好みの宿泊施設についても共有しています。' where id = 'OjOlwqJn5R_tMRFUrZjXQ';
update content_bodies set title = 'I Hiked to Japan''s Hidden Waterfall Oasis + Traditional Post Town - Mie and Nagano', description = 'The video showcases a beautiful hiking trip to a hidden waterfall oasis in Japan, along with a visit to a traditional post town in Mie and Nagano. The creator expresses excitement about the stunning scenery, describing it as possibly their new favorite weekend getaway. Viewers are encouraged to support the channel through various links for discounts on subscription boxes and to access additional content on Patreon. The creator also shares their social media handles and preferred accommodation options.' where id = '_1Kgz76C_DAlwoS1fnipZ';
update content_bodies set title = '日本の夏生活 - オーストラリア旅行計画、犬の世話 + ヴィーガンフード', description = 'この夏のVlogでは、日本の暑く湿気の多い夏の生活が紹介されています。制作者はこの季節を楽しんでおり、旅行計画や犬の世話、ヴィーガンフードのハイライトが含まれています。視聴者には、サブスクリプションボックスの割引コードを利用するよう促されており、Patreonでの支援も呼びかけています。また、宿泊施設や撮影機材のリンクも共有されており、さらなる交流のためのSNSアカウントも紹介されています。' where id = 'xCgov9wBMl9WyFzPV6W8y';
update content_bodies set title = 'Summer Life in Japan - Aus travel plans, dog-sitting + vegan food', description = 'The summer vlog showcases the vibrant life in Japan during the hot and humid season, which the creator enjoys despite the weather. The video includes travel plans, dog-sitting experiences, and highlights of vegan food options. Viewers are encouraged to use discount codes for subscription boxes and to support the creator on Patreon for additional content. The creator shares links for accommodation and filming gear, along with social media handles for further engagement.' where id = 'awEb7r1e9Xi80mKFm7tds';
update content_bodies set title = '私の日本のビザが切れそう、ビッグニュース、桜の季節と東京 - 日本での生活', description = 'この動画では、最近の大きな変化について語られています。特に、今後の生活における重要な出来事があることを示唆しており、労働ビザの承認が得られれば、今年の日本での生活が非常に良いものになると楽観的な気持ちを表現しています。また、PatreonでのサポートやInstagramアカウント、宿泊施設や撮影機材に関するリンクも紹介されています。' where id = 'V3_p5c_PyClyxxjeJUTsE';
update content_bodies set title = 'My Japan Visa Is Expiring, Big Announcement, Sakura Season & Tokyo - Life in Japan', description = 'In this video, the creator discusses significant changes that have occurred recently, hinting at exciting developments in their life in Japan. They express optimism about the upcoming year, contingent on the approval of their working visa. The video also includes links to support the creator on Patreon, their Instagram accounts, and resources for accommodation and filming gear.' where id = 'Sr-8E73yDvV4CTsrhBGnE';
update content_bodies set title = '奈良で秘密の水泳スポットを見つけた', description = 'この動画では、クリエイターが奈良で見つけた美しい水泳スポットについての体験を共有しています。水は日本で見た中で最も美しいと表現されており、2日目に訪れた滝についても言及されています。クリエイターは責任ある旅行の重要性を強調し、視聴者に自分の後始末をし、自然を尊重するよう呼びかけています。また、PatreonでのサポートやInstagramアカウント、音楽や宿泊施設のリソースへのリンクも提供しています。' where id = 'eszba9Dl-Rjdp2rmkU3ik';
update content_bodies set title = 'I Found A Secret Swimming Hole in Nara, Japan', description = 'In this video, the creator shares their experience discovering a breathtaking swimming hole in Nara, Japan, describing the water as the most beautiful they have ever seen in the country. They also mention a stunning waterfall visited on the second day. The creator emphasizes the importance of responsible travel, urging viewers to clean up after themselves and respect nature. Additionally, they provide links for supporting their content on Patreon, their Instagram accounts, and resources for music and accommodation.' where id = 'MPQ8nTMtfLAYxCiiCuDOr';
update content_bodies set title = '桜の季節は本当にどんな感じ？東京、日本', description = '東京を訪れると、圧倒されること間違いなしです。やることがたくさんあり、どれだけの時間があっても全てを見尽くすのは難しいため、最適なルートを選ぶのが大変です。この週末旅行では、主要な観光スポットに加え、隠れた珍しいスポットも紹介しています。旅行者が東京を効果的に楽しむためのガイドとなっています。' where id = 'CNW58ZUR11TVWd1rvR46O';
update content_bodies set title = 'What is Cherry Blossom Season REALLY like?! Tokyo, Japan', description = 'Visiting Tokyo can be an overwhelming experience due to the abundance of activities and limited time to explore. This weekend trip guide highlights major attractions as well as some unique and lesser-known spots. The content aims to help travelers navigate the city effectively and enjoy their visit.' where id = '8jQHxBVKY4hq6aXRnQZuf';
update content_bodies set title = '日本での生活、現在 - さようなら餅、コロナ感染、フォトシュートなど', description = '著者は、日本での特にストレスの多い冬について振り返っています。この冬は好きな季節ではないものの、周囲の素晴らしい人々に感謝していると述べています。投稿には、サブスクリプションボックスの割引リンクや、追加コンテンツのためのPatreon、さらなる交流のためのSNSアカウントが含まれています。また、著者の好む宿泊施設や撮影機材についても触れています。全体として、日本での冬の生活を垣間見る内容で、苦労とポジティブな側面が強調されています。' where id = '5ngudpEE0f2p7pJ_XFxAD';
update content_bodies set title = 'Life in Japan, Currently - RIP Mochi, Catching Covid, Photoshoots & More', description = 'The author reflects on a particularly stressful winter in Japan, which is not their favorite season. Despite the challenges, they express gratitude for the supportive people around them. The post includes links for discounts on subscription boxes, a Patreon for extra content, and social media handles for further engagement. The author also shares their preferred accommodation and filming gear. Overall, it offers a glimpse into their winter life in Japan, highlighting both struggles and positive aspects.' where id = 'JbUXnp0daGMtqabQ6xxMA';
update content_bodies set title = 'オーストラリアのために自分の日本旅行テレビ番組を制作しました', description = '著者は、オーストラリアのチャンネル7で放送されている旅行テレビ番組『Going Solo In Japan: The Wonders Of Kyushu』をホストするという子供の頃の夢が実現したことに興奮を表しています。この番組は現在、Channel 7plusでストリーミング中です。視聴者はオーストラリアから、または位置変更アプリを使用してエピソードにアクセスできます。著者は、早期アクセスや追加コンテンツのためのPatreonページ、個人やパフォーマンス関連の更新のためのInstagramアカウントへのリンクも提供しています。また、制作に使用した音楽や撮影機材のリンクも含まれています。' where id = 'u6D3324j0U1iXypsqUV-S';
update content_bodies set title = 'I Hosted My Own Japan Travel TV Show for Australia', description = 'The author shares their excitement about fulfilling a childhood dream by hosting a travel TV show titled ''Going Solo In Japan: The Wonders Of Kyushu'' on Channel 7 in Australia. The show is currently available for streaming on Channel 7plus. Viewers can access the episode from Australia or use a location-changing app. The author also provides links for additional content, including a Patreon page for early access and extra material, as well as their Instagram accounts for personal and performance-related updates. The post includes links to music and filming gear used in the production.' where id = 'cxBWi8xLzCJwAO8ulgNsn';
update content_bodies set title = '大阪での私の日常 - ストレス、ショッピング、オーバーランドキャンプ', description = 'この動画では、クリエイターが日本の大阪でのストレス、ショッピング、オーバーランドキャンプに関する日常生活の様子を共有しています。視聴者には、提供されたリンクを通じて旅行に参加するよう招待しています。また、滝での水泳が禁止されていることを視聴者から指摘されたことにも触れています。クリエイターは、追加コンテンツや早期アクセスのためにPatreonでのサポートを呼びかけ、個人用とパフォーマンス関連のInstagramアカウントも紹介しています。さらに、好みの宿泊施設や撮影機材のリンクも提供しています。' where id = 'OPxtGwJ8N6OOYf-JVc5iE';
update content_bodies set title = 'My Everyday Life Living in Osaka, Japan - Stress, Shopping and Overlanding Camping', description = 'In this video, the creator shares insights into their daily life in Osaka, Japan, highlighting experiences related to stress, shopping, and overlanding camping. They invite viewers to join their travel adventures through a provided link. A note mentions that swimming at a waterfall is not allowed, a fact brought to their attention by a viewer. The creator encourages support on Patreon for additional content and early access, and shares their Instagram handles for personal and performance-related content. They also provide links for preferred accommodation and filming gear.' where id = 'j0Elhnb7BUlQeUVjUtvtY';
update content_bodies set title = '日本の秋 - 徳島の剣山ハイキング 4K', description = 'この動画では、徳島の祖谷渓と剣山への美しい日帰り旅行を紹介しています。秋の紅葉が見事で、自然の驚異とも言えるこの地域は、秋に訪れるのに最適な場所です。剣山と祖谷渓は公共交通機関でアクセス可能ですが、少し難易度が高いかもしれません。交通手段や祖谷渓に関する情報はリンクで提供されています。また、グッズ購入やPatreonでのサポート、SNSのアカウントも紹介されています。' where id = 'YxOi4WDqfoTc21Orf_A6z';
update content_bodies set title = 'Autumn in Japan - Hiking Mt Tsurugi, Tokushima 4K', description = 'This video showcases a stunning day trip to Iya Valley and Mt Tsurugi in Tokushima, Japan, highlighting the breathtaking beauty of the autumn foliage. The region is described as a natural wonderland, making it an ideal destination during the fall season. While Mt Tsurugi and Iya Valley can be reached via public transport, it may present some challenges. Additional resources for transport and information about Iya Valley are provided in the links. The video also includes links for merchandise, Patreon support for extra content, and social media handles for further engagement.' where id = 'KNYZ2We1i-dlHKBk91tcp';
update content_bodies set title = '白川郷と乗鞍岳のハイキング、キャンプ、探検 - 岐阜、日本', description = 'この動画では、ホストが岐阜県での週末旅行を共有し、白川郷と乗鞍岳を探検します。最初は期待していなかったものの、結果的に素晴らしく魔法のような体験となりました。岐阜の美しさや魅力が強調され、長野に比べて見過ごされがちな目的地であることが示されています。ホストは乗鞍岳と白川郷に関する情報リンクを提供し、PatreonやSNSを通じてコンテンツを支援する方法も紹介しています。動画で使用されている音楽はArtlistとMusicbedからのもので、ホストのお気に入りの宿泊オプションも共有されています。' where id = 'JA5mHCPFothW0MxlcHTSD';
update content_bodies set title = 'Hiking, Camping and Exploring Shirakawa-go and Mt Norikura - Gifu, Japan', description = 'In this video, the host shares their recent weekend trip to Gifu, Japan, where they explored Shirakawa-go and Mt Norikura. Initially, they had low expectations for the trip, but it turned out to be a magical experience. The video highlights the beauty and offerings of Gifu, a destination often overlooked in favor of Nagano. The host provides links for more information on Mt Norikura and Shirakawa-go, as well as ways to support their content through Patreon and social media. Music used in the video is sourced from Artlist and Musicbed, and the host shares their preferred accommodation options.' where id = '82ccH0rrgkg3f50ifj-gz';
update content_bodies set title = '現在の日本の日常生活', description = 'この動画では、クリエイターが日本の日常生活についての洞察を共有し、視聴者からの「もっと身近なコンテンツを」というリクエストに応えています。この種のコンテンツを作ることは挑戦ですが、その機会を楽しんでいます。次回の動画では、通常のプログラムに戻り、上高地でのハイキングが紹介される予定です。クリエイターはサムネイル写真を撮影してくれたクリスに感謝し、彼のインスタグラムをフォローするよう視聴者に促しています。また、Peak Designの30Lエブリデイバックパックへの感謝の言葉や、大阪のアクションパークや京都のラフティングなど、日本でのさまざまなアクティビティへのリンクも紹介されています。視聴者は、追加コンテンツや早期アクセスのためにPatreonでクリエイターをサポートするよう招待されており、ソーシャルメディアや商品へのリンクも提供されています。' where id = '2bz-GQicVcwROa_UF9L5S';
update content_bodies set title = 'Everyday Life In Japan, Currently', description = 'In this video, the creator shares insights into everyday life in Japan, responding to viewer requests for more relatable content. The video highlights the challenges of creating such content but embraces the opportunity. Upcoming videos will return to regular programming, including a hike in Kamikochi. The creator thanks Chris for the thumbnail photo and encourages viewers to follow him on Instagram. Additionally, the video features a shoutout to Peak Design for their Everyday Backpack 30L, along with links to various activities in Japan, such as Action Park Osaka and white water rafting in Kyoto. Viewers are invited to support the creator on Patreon for extra content and early access, and links to social media and merchandise are provided.' where id = 'BFohTUphPt-gtTHEq90m-';